const startVertIdx = vertices.findIndex(
  (v) => v[0] === startX && v[1] === startY && v[2] === startZ
);
const endVertIdx = vertices.findIndex(
  (v) => v[0] === endX && v[1] === endY && v[2] === endZ
);
