  vertices.push([startX.toPrecision(4), startY.toPrecision(4), startZ]);
  vertices.push([endX.toPrecision(4), endY.toPrecision(4), endZ]);
  wireframeEdges.push([vertices.length - 2, vertices.length - 1]);
