const axios = require('axios');
const FormData = require('form-data');

const client = new Discord.Client({ 
  intents: [
    Discord.Intents.FLAGS.GUILDS,
    Discord.Intents.FLAGS.GUILD_MESSAGES
  ]
});
const API_KEY = 'YOUR_API_KEY_HERE';

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
});

client.on('messageCreate', async (message) => {
  if (message.author.bot || !message.content.startsWith('!chat')) {
    return;
  }
  const msg = message.content.slice(5).trim();
  if (!msg) {
    message.reply('Please provide a message to chat!');
    return;
  }
  const form = new FormData();
  form.append('text', msg);

  try {
    const resp = await axios.post('https://api.deepai.org/api/text-generator', form, {
      headers: {
        'Content-Type': `multipart/form-data; boundary=${form._boundary}`,
        'api-key': API_KEY,
      },
    });
    message.reply(resp.data.output);
  } catch (error) {
    console.error(error);
    message.reply('Sorry, an error occurred while processing your request');
  }
});

client.login('YOUR_DISCORD_BOT_TOKEN');
```

คุณสามารถแก้ไข syntax นี้เพื่อเปลี่ยน `FLAGS` เป็น `Discord.Intents.FLAGS.[INTENT_NAME]` ทุกแห่งเพื่อให้เหมาะสมกับ Discord

