  for (let i = 0; i <= canvas.height; i += gridSpacing) {
    ctx.beginPath();
    ctx.moveTo(0, i);
    ctx.lineTo(canvas.width, i);
    ctx.stroke();
  }
}

function findClosestGridPosition(point) {
  const closestX = Math.round(point.x / gridSpacing) * gridSpacing;
  const closestY = Math.round(point.y / gridSpacing) * gridSpacing;

  return { x: closestX, y: closestY };
}

