Вот две функции для реализации сортировки вставками и сортировки bogosort на C++:

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <chrono>
#include <random>

// Сортировка вставками
void insertion_sort(std::vector<int>& arr, int& iterations) {
  for (int i = 1; i < arr.size(); ++i) {
    int key = arr[i];
    int j = i - 1;
    while (j >= 0 && arr[j] > key) {
      arr[j + 1] = arr[j];
      --j;
      ++iterations;
    }
    arr[j + 1] = key;
  }
}

// Проверка, отсортирован ли вектор
bool is_sorted(std::vector<int>& arr) {
  for (int i = 1; i < arr.size(); ++i) {
    if (arr[i - 1] > arr[i])
      return false;
  }
  return true;
}

// Сортировка bogosort
void bogosort(std::vector<int>& arr, int& iterations) {
  std::mt19937 rng(std::chrono::system_clock::now().time_since_epoch().count());
  while (!is_sorted(arr)) {
    std::shuffle(arr.begin(), arr.end(), rng);
    ++iterations;
  }
}

int main() {
  // Считываем вектор чисел из файла
  std::ifstream file("numbers.txt");
  std::vector<int> arr;
  int x;
  while (file >> x)
    arr.push_back(x);

  // Сортировка вставками
  int iterations_insertion_sort = 0;
  std::vector<int> arr_insertion_sort = arr;
  auto start = std::chrono::high_resolution_clock::now();
  insertion_sort(arr_insertion_sort, iterations_insertion_sort);
  auto end = std::chrono::high_resolution_clock::now();
  std::cout << "Insertion sort iterations: " << iterations_insertion_sort << std::endl;
  std::cout << "Insertion sort time: " << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms" << std::endl;

  // Сортировка bogosort
  int iterations_bogosort = 0;
  std::vector<int> arr_bogosort = arr;
  start = std::chrono::high_resolution_clock::now();
  bogosort(arr_bogosort, iterations_bogosort);
  end = std::chrono::high_resolution_clock::now();
  std::cout << "Bogosort iterations: " << iterations_bogosort << std::endl;
  std::cout << "Bogosort time: " << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms" << std::endl;

  // Записываем отсортированный вектор в файл
  std::ofstream out("sorted_numbers.txt");
  for (auto& x : arr_insertion_sort)
    out << x << std::endl;

  return 0;
}
