This isnt ordering the array, please fix it by keeping on mind this:
The kernels to be written should sort the contents of the file datSeq1M.bin in 10 iteration
steps. In iteration 1, 1024 subsequences of 1024 integer values are to be sorted in parallel. In
iteration 2, 512 subsequences of 2048 integer values are to be sorted in parallel based on the
merging of the previously sorted halves. And so on and so forth, until iteration 10 is reached,
where 2 previously sorted subsequences of 512K values are merged, yielding the whole sorted
sequence.
Assume that the values of the whole sequence, when stored in memory, are organized as the
elements of 1024 X 1024 matrix. The threads in a block thread process successive matrix rows

According to the instructions provided, the program should sort the given elements in iterations by merging the previously sorted parts. However, the current code does not match these instructions as it does not have any logic to merge sorted sub-sequences. To fix this issue, we need to modify the kernel function, add a function to merge the previously sorted subsequences and adjust the main function accordingly.

Here is an updated version of the code:

```cpp
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <libgen.h>
#include <unistd.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>
#include <time.h>

#include <cuda_runtime.h>

#define ROWS 1024
#define COLS 1024
#define ITERATIONS 10

__global__ void bitonicSortKernel(int *mat, int iteration, int blockSize)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int offset = idx * COLS;
    int i, j, k;
    int temp;

    for (i = blockSize >> 1; i > 0; i >>= 1)
    {
        for (j = 0; j < i; j++)
        {
            for (k = 0; k < (COLS >> 1); k++)
            {
                int ixj = k ^ j;

                if ((k & i) == 0 && (ixj > k) && (mat[offset + k] > mat[offset + ixj]))
                {
                    // Swap elements
                    temp = mat[offset + k];
                    mat[offset + k] = mat[offset + ixj];
                    mat[offset + ixj] = temp;
                }
            }
            __syncthreads();
        }
    }
}

__global__ void mergeSortedSequences(int *mat, int blockSize)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int cols = blockDim.x;

    int blockStartIndex = idx / cols * blockSize;
    int inputSequence = idx % cols;
    int inputIndex = blockStartIndex + inputSequence * (blockSize / cols);
    int outputIndex = blockStartIndex * 2;

    __shared__ int temp[ROWS * 2];
    int compareOffset = inputSequence % 2 == 0 ? blockSize / cols : -blockSize / cols;

    for (int i = 0; i < blockSize / cols; i++)
    {
        int compareValue = mat[inputIndex + i + compareOffset];
        int currentValue = mat[inputIndex + i];

        int smallerValue = min(compareValue, currentValue);
        int largerValue = max(compareValue, currentValue);

        temp[outputIndex] = smallerValue;
        temp[outputIndex + 1] = largerValue;

        outputIndex += 2;
    }
    __syncthreads();

    outputIndex = blockStartIndex * 2;
    memcpy(mat + outputIndex, temp + outputIndex, COLS * sizeof(int));
}

bool isSorted(int* data, int size) {
  for (int i = 0; i < size - 1; i++) {
    if (data[i] > data[i + 1])
      return false;
  }
  return true;
}

