__global__ void bitonicSortKernel(int *mat)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int offset = idx * COLS;
    int th;
    int inc, low, temp;

    for (int k = 2; k <= COLS; k *= 2)
