```cpp
if (slot && slot->getAttachment()) {
    float centerX = 0.0f;
    float centerY = 0.0f;

    // Check if it's a RegionAttachment
    spine::RegionAttachment* regionAttachment = dynamic_cast<spine::RegionAttachment*>(slot->getAttachment());
    if (regionAttachment) {
