        for (size_t i = 0; i < vertices.size(); i += 2) {
            centerX += vertices[i];
            centerY += vertices[i + 1];
        }

        centerX /= (vertices.size() / 2);
        centerY /= (vertices.size() / 2);
    }

    // Check if it's a MeshAttachment
    spine::MeshAttachment* meshAttachment = dynamic_cast<spine::MeshAttachment*>(slot->getAttachment());
    if (meshAttachment) {
        const spine::Vector<float>& vertices = meshAttachment->getVertices();

        for (size_t i = 0; i < vertices.size(); i += 2) {
            centerX += vertices[i];
            centerY += vertices[i + 1];
