using System.Drawing.Imaging;

static Pix PreprocessImage(string imagePath)
{
    Bitmap originalBitmap = new Bitmap(imagePath);
    Bitmap resizedBitmap = new Bitmap(originalBitmap, new Size(originalBitmap.Width * 2, originalBitmap.Height * 2));
    Bitmap grayscaleBitmap = new Bitmap(resizedBitmap.Width, resizedBitmap.Height);

    for (int y = 0; y < resizedBitmap.Height; y++)
