            int gray = (int)((color.R * 0.3) + (color.G * 0.59) + (color.B * 0.11));
            Color grayColor = Color.FromArgb(gray, gray, gray);
            grayscaleBitmap.SetPixel(x, y, grayColor);
        }
    }

    return PixConverter.ToPix(grayscaleBitmap);
}
