```java
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

import java.io.FileOutputStream;
import java.io.IOException;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Vector<Log> logs = new Vector<>();
        // Simulate adding logs to the vector
        logs.add(createLog("Database query", 1, 1000));
        logs.add(createLog("Database query", 2, 1100));
        logs.add(createLog("Database query", 3, 900));
        logs.add(createLog("File upload", 1, 1200));
        logs.add(createLog("File upload", 2, 1300));

        Map<String, List<Long>> groupedLogs = new LinkedHashMap<>();
        for (Log log : logs) {
            long duration = log.endTime - log.startTime;
            groupedLogs.computeIfAbsent(log.action, k -> new ArrayList<>()).add(duration);
        }

        try (Workbook workbook = new XSSFWorkbook()) {
            Sheet sheet = workbook.createSheet("Logs Summary");
            int rowNumber = 0;

            for (Map.Entry<String, List<Long>> entry : groupedLogs.entrySet()) {
                String action = entry.getKey();
                List<Long> durations = entry.getValue();
                Collections.sort(durations); // Sort durations for percentile and median calculation

                Row row = sheet.createRow(rowNumber++);
                row.createCell(0).setCellValue("Action: " + action);
                row = sheet.createRow(rowNumber++);
                row.createCell(0).setCellValue("Average:");
                row.createCell(1).setCellValue(average(durations));
                row = sheet.createRow(rowNumber++);
                row.createCell(0).setCellValue("Median:");
                row.createCell(1).setCellValue(median(durations));
                row = sheet.createRow(rowNumber++);
                row.createCell(0).setCellValue("90% Percentile:");
                row.createCell(1).setCellValue(percentile(durations, 0.9));
                rowNumber++;
            }

            try (FileOutputStream outputStream = new FileOutputStream("LogsSummary.xlsx")) {
                workbook.write(outputStream);
            }
        }
    }

    private static Log createLog(String action, long threadId, long duration) {
        Log log = new Log();
        log.action = action;
        log.threadId = threadId;
        log.startTime = System.currentTimeMillis();
        log.endTime = log.startTime + duration;
        return log;
    }

    private static double average(List<Long> values) {
        if (values == null || values.isEmpty()) {
            return 0;
        }
        double sum = 0;
        for (Long value : values) {
            sum += value;
        }
        return sum / values.size();
    }

    private static double median(List<Long> values) {
        if (values == null || values.isEmpty()) {
            return 0;
        }
        int middle = values.size() / 2;
        return values.size() % 2 == 1 ? values.get(middle) : (values.get(middle - 1) + values.get(middle)) / 2.0;
    }

    private static double percentile(List<Long> values, double percentile) {
        if (values == null || values.isEmpty()) {
            return 0;
        }
        int index = (int) Math.ceil(percentile * values.size()) - 1;
        return values.get(index);
    }
}

class Log {
    public String action;
    public long threadId;
    public long startTime;
    public long endTime;
}
```

