You can use the following code to parse XML files and create a text file with the specified format. This code assumes that the XML files are in the same directory as the JPG files.

```csharp
using System.IO;
using System.Xml;

public void ProcessXmlFiles(string folderPath, string outputFilename)
{
    DirectoryInfo directoryInfo = new DirectoryInfo(folderPath);
    FileInfo[] xmlFiles = directoryInfo.GetFiles("*.xml");

    using StreamWriter outputFile = new StreamWriter(Path.Combine(folderPath, outputFilename));

    foreach (FileInfo xmlFile in xmlFiles)
    {
        XmlDocument doc = new XmlDocument();
        doc.Load(xmlFile.FullName);

        string jpgFilePath = Path.Combine(folderPath, doc.SelectSingleNode("//filename").InnerText);
        XmlNode bndbox = doc.SelectSingleNode("//bndbox");

        string outputLine = $"{jpgFilePath} 1 {bndbox["xmin"].InnerText} {bndbox["ymin"].InnerText} {bndbox["xmax"].InnerText} {bndbox["ymax"].InnerText}";
        outputFile.WriteLine(outputLine);
    }
}
