    glPushMatrix();
    glScalef(1, 1, 1);
    glColor3f(1.0f, 0.0f, 0.0f);
    glRasterPos2f(-0.15f, 0.1f);
    const char* text = "Game Over!";
    int len = strlen(text);
    for (int i = 0; i < len; i++) {
        glutBitmapCharacter(GLUT_BITMAP_TIMES_ROMAN_24, text[i]);
    }
    glRasterPos2f(-0.15f, 0.1f);
