    glPushMatrix();
    glTranslatef(figur.pos.x, figur.pos.y+0.15, 0.0f);
    glScalef(0.2, 0.2, 0.2);

    glBegin(GL_QUADS);
    glColor3f(1.0f, 0.0f, 0.0f); //здоровье

