    glVertex2f(figur.health * 0.2f - 0.3f, 0.2f);
    glVertex2f(figur.health * 0.2f - 0.3f, 0.25f);
    glVertex2f(-0.3f, 0.25f);

    glEnd();

    glPopMatrix();
}

