```javascript
const canvas = document.getElementById("canvas");
const ctx = canvas.getContext("2d");

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const rotationSpeed = 0;
const gridSize = 50;
const gridSpacing = 25;
const zoomStep = 10;
const minZoom = 100;

let grid = [];
for (let x = -gridSize; x <= gridSize; x += gridSpacing) {
  for (let y = -gridSize; y <= gridSize; y += gridSpacing) {
    for (let z = -gridSize; z <= gridSize; z += gridSpacing) {
      grid.push({ x, y, z });
    }
  }
}

let angleX = 0;
let angleY = 0;
let zoom = 800;

function rotate(point, angleX, angleY) {
  const { x, y, z } = point;
  const cosX = Math.cos(angleX);
  const sinX = Math.sin(angleX);
  const cosY = Math.cos(angleY);
  const sinY = Math.sin(angleY);

  const newY = y * cosX - z * sinX;
  const newZ = y * sinX + z * cosX;
  const newX = x * cosY - newZ * sinY;
  const newZ2 = x * sinY + newZ * cosY;

  return { x: newX, y: newY, z: newZ2 };
}

function project(point, width, height) {
  const { x, y, z } = point;

  const scale = zoom / (400 + z);
  const newX = x * scale + width / 2;
  const newY = y * scale + height / 2;

  return { x: newX, y: newY };
}

function getPointSize(z) {
  const zFar = 1;
  const zNear = 0.2;
  return Math.max(((z + gridSize) / (gridSize * 2)) * (zFar - zNear) + zNear, 0);
}

canvas.addEventListener("wheel", (e) => {
  e.preventDefault();
  const delta = e.deltaY / Math.abs(e.deltaY);
  zoom += delta * zoomStep;
  zoom = Math.max(minZoom, zoom);
});

canvas.addEventListener("mousedown", (e) => {
  const deltaX = e.clientX - canvas.width / 2;
  const deltaY = e.clientY - canvas.height / 2;
  angleY += deltaX * 0.01;
  angleX += deltaY * 0.01;
});

function draw() {
  ctx.fillStyle = "rgba(1,2,1,0.8)";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (const point of grid) {
    const rotated = rotate(point, angleX, angleY);
    const projected = project(rotated, canvas.width, canvas.height);

    const size = getPointSize(rotated.z);
    const gradient = ctx.createRadialGradient(projected.x, projected.y, size / 2, projected.x, projected.y, size);

    gradient.addColorStop(0, 'rgba(55,155,255,1)');
    gradient.addColorStop(1, 'rgba(55,155,255,0)');
    ctx.fillStyle = gradient;

    ctx.beginPath();
    ctx.arc(projected.x, projected.y, size, 0, Math.PI * 2);
    ctx.closePath();
    ctx.fill();
  }

  angleX += rotationSpeed;
  angleY += rotationSpeed;

  requestAnimationFrame(draw);
}

draw();
