            if (playersInGame.contains(player)) {
                sumoBot.getTrait(SumoPVPTrait.class).startPVP(player);
            }
        }, 60L);
    }

    public void endGame(Player player, boolean playerVictory) {
        restoreInventory(player);
        player.teleport(hub);

        if (playerVictory) {
