        player.getMetadata(SumoInventoryManager.class.getSimpleName()).add(new SumoInventoryMetadata(contents));
        player.getInventory().clear();
    }

    private void restoreInventory(Player player) {
        ItemStack[] contents = player.getMetadata(SumoInventoryManager.class.getSimpleName()).get(0).as(ItemStack[].class);
        player.getInventory().setContents(contents);
        player.removeMetadata(SumoInventoryManager.class.getSimpleName());
    }
