```cpp
#include <iostream>
#include <string>
#include <bitcoin/bitcoin.hpp>

std::string generateBitcoinAddress(const std::string& hex_private_key) {
    bc::ec_secret secret;
    if (!bc::decode_base16(secret, hex_private_key)) {
        return "";
    }

    bc::wallet::ec_private privateKey(secret, bc::wallet::ec_private::mainnet_p2kh);
    bc::wallet::ec_public publicKey(privateKey);

    bc::wallet::payment_address payAddress = bc::wallet::payment_address::extract(publicKey);

    return payAddress.encoded();
}

int main() {
    std::string hex_private_key;
    std::cout << "Enter the hexadecimal private key: ";
    std::cin >> hex_private_key;

    std::string bitcoin_address = generateBitcoinAddress(hex_private_key);

    if (bitcoin_address.empty()) {
        std::cerr << "Invalid private key!" << std::endl;
        return 1;
    }

    std::cout << "Generated Bitcoin address: " << bitcoin_address << std::endl;
    return 0;
}
