To use the I2S interface with the TTGO T-display ESP32 board, you can use the ESP32 I2S library available in the Arduino IDE. This library provides functions to configure and control the I2S interface of the ESP32 microcontroller. Here is a simple example code that initializes the I2S interface and outputs a sine wave:

```C++
#include <driver/i2s.h>
#include <math.h>

#define PI 3.14159f
#define SAMPLE_RATE 44100
#define CHANNELS 2
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE 4096

i2s_config_t i2s_config = {
  .mode = (i2s_mode_t)(I2S_MODE_MASTER | I2S_MODE_TX),
  .sample_rate = SAMPLE_RATE,
  .bits_per_sample = (i2s_bits_per_sample_t)BITS_PER_SAMPLE,
  .channel_format = I2S_CHANNEL_FMT_RIGHT_LEFT,
  .communication_format = (i2s_comm_format_t)(I2S_COMM_FORMAT_I2S | I2S_COMM_FORMAT_I2S_MSB),
  .dma_buf_count = 2,
  .dma_buf_len = BUFFER_SIZE
};

i2s_pin_config_t pin_config = {
  .bck_io_num = 26,
  .ws_io_num = 25,
  .data_out_num = 22,
  .data_in_num = I2S_PIN_NO_CHANGE
};

void setup() {
  i2s_driver_install(I2S_NUM_0, &i2s_config, 0, NULL);
  i2s_set_pin(I2S_NUM_0, &pin_config);
}

void loop() {
  static uint32_t sample_index = 0;
  static uint8_t buffer[BUFFER_SIZE];

  for (int i = 0; i < BUFFER_SIZE; i += 4) {
    float sample = 32767.0f * sinf(2 * PI * sample_index / SAMPLE_RATE);
    *(int16_t *)(buffer + i) = (int16_t)sample;
    *(int16_t *)(buffer + i + 2) = (int16_t)sample;
    sample_index++;
  }

  i2s_write_bytes(I2S_NUM_0, (char *)buffer, BUFFER_SIZE, portMAX_DELAY);
}
