```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

// Function to create a new node and return its address
struct Node* create_node(int data) {
    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    new_node->data = data;
    new_node->next = NULL;

    return new_node;
}

// Function to insert a new node at the beginning
void insert_beginning(struct Node** head, int data) {
    struct Node* new_node = create_node(data);

    if (*head == NULL) {
        *head = new_node;
        new_node->next = *head;
    } else {
        struct Node* temp = *head;

        while (temp->next != *head)
            temp = temp->next;

        new_node->next = *head;
        temp->next = new_node;
    }
}

// Function to insert a new node at the end
void insert_end(struct Node** head, int data) {
    struct Node* new_node = create_node(data);

    if (*head == NULL) {
        *head = new_node;
        new_node->next = *head;
    } else {
        struct Node* temp = *head;

        while (temp->next != *head)
            temp = temp->next;

        temp->next = new_node;
        new_node->next = *head;
    }
}

// Function to insert a new node at a given position
void insert_at_position(struct Node** head, int data, int position) {
    struct Node* new_node = create_node(data);

    if (position == 1) {
        insert_beginning(head, data);
        return;
    }

    int count = 1;
    struct Node* temp = *head;

    while (count < position - 1 && temp->next != *head) {
        temp = temp->next;
        count++;
    }

    if (count < position - 1) {
        printf("Invalid position!\n");
        return;
    }

    new_node->next = temp->next;
    temp->next = new_node;
}

// Function to delete a node from beginning
void delete_beginning(struct Node** head) {
    if (*head == NULL) {
        printf("List is empty!\n");
        return;
    }

    if ((*head)->next == *head) {
        free(*head);
        *head = NULL;
        return;
    }

    struct Node* temp = *head;
    struct Node* last = *head;

    while (last->next != *head)
        last = last->next;

    *head = (*head)->next;
    last->next = *head;
    free(temp);
}

// Function to delete a node from end
void delete_end(struct Node** head) {
    if (*head == NULL) {
        printf("List is empty!\n");
        return;
    }

    if ((*head)->next == *head) {
        free(*head);
        *head = NULL;
        return;
    }

    struct Node* temp = *head;
    struct Node* prev;

    while (temp->next != *head) {
        prev = temp;
        temp = temp->next;
    }

    prev->next = *head;
    free(temp);
}

// Function to delete a node at a given position
void delete_at_position(struct Node** head, int position) {
    if (*head == NULL) {
        printf("List is empty!\n");
        return;
    }

    if (position == 1) {
        delete_beginning(head);
        return;
    }

    int count = 1;
    struct Node* temp = *head;
    struct Node* prev;

    while (count < position && temp->next != *head) {
        prev = temp;
        temp = temp->next;
        count++;
    }

    if (count < position) {
        printf("Invalid position!\n");
        return;
    }

    prev->next = temp->next;
    free(temp);
}

// Function to search a node
void search(struct Node* head, int data) {
    if (head == NULL) {
        printf("List is empty!\n");
        return;
    }

    int position = 1;
    struct Node* temp = head;

    do {
        if (temp->data == data) {
            printf("Node found at position %d\n", position);
            return;
        }
        temp = temp->next;
        position++;
    } while (temp != head);

    printf("Node not found!\n");
}

// Function to display the list
void display(struct Node* head) {
    if (head == NULL) {
        printf("List is empty!\n");
        return;
    }

    struct Node* temp = head;

    do {
        printf("%d ", temp->data);
        temp = temp->next;
    } while (temp != head);

    printf("\n");
}

int main() {
    int choice, data, position;
    struct Node* head = NULL;

    while (1) {
        printf("1. Insert at beginning\n");
        printf("2. Insert at end\n");
        printf("3. Insert at position\n");
        printf("4. Delete from beginning\n");
        printf("5. Delete from end\n");
        printf("6. Delete at position\n");
        printf("7. Search a node\n");
        printf("8. Display the list\n");
        printf("9. Quit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter the data: ");
                scanf("%d", &data);
                insert_beginning(&head, data);
                break;
            case 2:
                printf("Enter the data: ");
                scanf("%d", &data);
                insert_end(&head, data);
                break;
            case 3:
                printf("Enter the data: ");
                scanf("%d", &data);
                printf("Enter the position: ");
                scanf("%d", &position);
                insert_at_position(&head, data, position);
                break;
            case 4:
                delete_beginning(&head);
                break;
            case 5:
                delete_end(&head);
                break;
            case 6:
                printf("Enter the position: ");
                scanf("%d", &position);
                delete_at_position(&head, position);
                break;
            case 7:
                printf("Enter the data: ");
                scanf("%d", &data);
                search(head, data);
                break;
            case 8:
                display(head);
                break;
            case 9:
                exit(0);
            default:
                printf("Invalid choice!\n");
        }
    }

    return 0;
}
```
This is a menu-driven C program implementing a circular linked list with operations for creating and manipulating the list. The program presents the user with multiple options to add, delete, search, or display elements within the list. The user can insert elements at the beginning, end, or any specified position and can likewise delete elements from the beginning, end, or any specified position.

