package ex2;

import java.util.ArrayList;
import java.util.List;

public class NumberRepository {

    private String[] simpleNumberData = "2, 4, 6, 2, 9, 10".split(", ");
    private String[] scientificNumberData = "2e3, 2e4, 6e3".split(", ");

    public static class SimpleNumber extends Number {
        private int value;

        public SimpleNumber(int value) {
            this.value = value;
        }

        @Override
        public double doubleValue() {
            return value;
        }

        @Override
        public float floatValue() {
            return value;
        }

        @Override
        public int intValue() {
            return value;
        }

        @Override
        public long longValue() {
            return value;
        }
    }

    public static class ScientificNumber extends Number {
        private int base;
        private int exponent;

        public ScientificNumber(int base, int exponent) {
            this.base = base;
            this.exponent = exponent;
        }

        @Override
        public double doubleValue() {
            return Math.pow(base, exponent);
        }

        @Override
        public float floatValue() {
            return (float) Math.pow(base, exponent);
        }

        @Override
        public int intValue() {
            return (int) Math.pow(base, exponent);
        }

        @Override
        public long longValue() {
            return (long) Math.pow(base, exponent);
        }

    }

    public List<SimpleNumber> getSimpleNumbers() {
        List<SimpleNumber> simpleNumbers = new ArrayList<>();
        for (String simpleNumberDatum : simpleNumberData) {
            simpleNumbers.add(new SimpleNumber(Integer.parseInt(simpleNumberDatum)));
        }
        return simpleNumbers;
    }

    public List<ScientificNumber> getScientificNumbers() {
        List<ScientificNumber> scientificNumbers = new ArrayList<>();
        for (String scientificNumberDatum : scientificNumberData) {
            scientificNumbers.add(new ScientificNumber(Character.getNumericValue(scientificNumberDatum.charAt(0)), Character.getNumericValue(scientificNumberDatum.charAt(2))));
        }
        return scientificNumbers;
    }

    public List<Number> getAllNumbers() {
        List<Number> allNumbers = new ArrayList<>();
        allNumbers.addAll(getSimpleNumbers());
        allNumbers.addAll(getScientificNumbers());
        return allNumbers;
    }

}
```

I've added `SimpleNumber` and `ScientificNumber` as inner classes in `NumberRepository` and made them extend the `Number` class, which requires them to provide an implementation for the following methods: `doubleValue()`, `floatValue()`, `intValue()`, `longValue()`.

Finally, I've corrected the `getAllNumbers()` method to use `addAll()` instead of `add()`, since `getSimpleNumbers()` and `getScientificNumbers()` return lists of numbers.

