import {
  QueryFunction,
  QueryObserverResult,
  QueryStatus,
  RefetchOptions,
  RefetchQueryFilters,
  UseQueryOptions,
  useQuery,
} from '@tanstack/react-query';

import { BranchStatus } from 'models/BranchStatus';

const queryStatusToBranchStatus: Record<
  QueryStatus | 'loading' | 'error' | 'success' | 'idle',
  BranchStatus
> = {
  success: BranchStatus.FINISHED,
  loading: BranchStatus.LOADING,
  error: BranchStatus.ERROR,
  idle: BranchStatus.IDLE,
};

interface UseQueryWrapperInterface<T> {
  result: T;
  branchStatus: BranchStatus;
  refetch: <TPageData>(
    options?: (RefetchOptions & RefetchQueryFilters<TPageData>) | undefined,
  ) => Promise<QueryObserverResult>;
}

export const useQueryWrapper = <T, K>(
  key: string[] | [string, K],
  func: QueryFunction<T>,
  opts?: UseQueryOptions<T>,
): UseQueryWrapperInterface<T> => {
  const { data, status, refetch } = useQuery<T>(key, func, opts);
  const result = data as T;
  const branchStatus = queryStatusToBranchStatus[status];
  return { result, branchStatus, refetch };
};


