        const snapshot = await futureMKRef.get();
        const data = snapshot.docs.map((doc) => doc.data());
        setFutureMKData(data);

        // Loop through the data and add a public HTTPS URL for each image
        const storageRef = getStorage().ref();
        const updatedData = await Promise.all(data.map(async (mkData) => {
          const imageUrl = mkData.imageUrl;
          const imageRef = ref(storageRef, imageUrl);
          const url = await getDownloadURL(imageRef);
          return { ...mkData, imageUrl: url };
        }));

        // Update the state with the new data that contains public HTTPS URLs for images
        setFutureMKData(updatedData);
