    hr = D3DXCreateTexture(pDevice, width, height, 1, D3DUSAGE_DYNAMIC, D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT, &g_pTexture);

    if (FAILED(hr))
    {
        return hr;
    }

    D3DLOCKED_RECT rect;
    ZeroMemory(&rect, sizeof(D3DLOCKED_RECT));

    hr = g_pTexture->LockRect(0, &rect, NULL, D3DLOCK_DISCARD);

    if (FAILED(hr))
    {
        g_pTexture->Release();
        g_pTexture = NULL;
        return hr;
    }

    for (UINT i = 0; i < height; ++i)
    {
        BYTE* pBits = (BYTE*)rect.pBits + i * rect.Pitch;
        for (UINT j = 0; j < width; ++j)
        {
            *pBits++ = (BYTE)(255 * i / height);     // 红色分量
            *pBits++ = (BYTE)(255 * j / width);      // 绿色分量
            *pBits++ = 255;                          // 蓝色分量
            *pBits++ = 255;                          // 透明度分量
        }
    }

    g_pTexture->UnlockRect(0);

    return hr;
}

void Cleanup()
{
    if (g_pTexture != NULL)
    {
        g_pTexture->Release();
        g_pTexture = NULL;
    }
}

int main()
{
    LPDIRECT3D9 pD3D = Direct3DCreate9(D3D_SDK_VERSION);
    if (pD3D == NULL)
    {
        return 1;
    }

    D3DPRESENT_PARAMETERS d3dpp;
    ZeroMemory(&d3dpp, sizeof(D3DPRESENT_PARAMETERS));

    d3dpp.Windowed = TRUE;
    d3dpp.SwapEffect = D3DSWAPEFFECT_DISCARD;
    d3dpp.BackBufferFormat = D3DFMT_UNKNOWN;

    LPDIRECT3DDEVICE9 pDevice = NULL;
    if (FAILED(pD3D->CreateDevice(D3DADAPTER_DEFAULT, D3DDEVTYPE_HAL, GetDesktopWindow(),
        D3DCREATE_SOFTWARE_VERTEXPROCESSING, &d3dpp, &pDevice)))
    {
        pD3D->Release();
        return 1;
    }

    if (FAILED(CreateTextureEx(pDevice, 256, 256)))
    {
        pDevice->Release();
        pD3D->Release();
        Cleanup();
        return 1;
    }

    // 渲染代码

    pDevice->Release();
    pD3D->Release();
    Cleanup();
    return 0;
}
```

