expo install expo-file-system
npm install react-native-ffmpeg --save
```

2. Import the required modules in your `App.js`:

```javascript
import * as MediaLibrary from 'expo-media-library';
import * as FileSystem from 'expo-file-system';
import { RNFFmpeg } from 'react-native-ffmpeg';
```

3. Add the following utility function that will help you resize a video file:

```javascript
const resizeVideo = async (input_uri, output_file, width, height) => {
  try {
    const command = `-i ${input_uri} -vf scale=${width}:${height} ${output_file}`;
    await RNFFmpeg.execute(command);

    const newVidAsset = await MediaLibrary.createAssetAsync(output_file);
    await MediaLibrary.createAlbumAsync('Your Album Name', newVidAsset, false);
    return newVidAsset;
  } catch (error) {
    console.error('Error resizing video:', error);
    return null;
  }
};
```

4. Now you can use `resizeVideo()` function to resize an existing video on storage. Here's an example usage:

```javascript
const videoExample = async () => {
  try {
    // Change this to the video's filename you want to resize
    const input_video_filename = 'your_input_video.mp4';
    const output_video_filename = 'your_resized_video.mp4';

    const input_video_uri = `${FileSystem.documentDirectory}${input_video_filename}`;
    const output_video_uri = `${FileSystem.documentDirectory}${output_video_filename}`;

    const resized_asset = await resizeVideo(input_video_uri, output_video_uri, 256, 512);
    console.log('Resized video:', resized_asset);
  } catch (error) {
    console.error('Error:', error);
  }
};
