以下是只使用reduction的代码：

```c
#include <stdio.h>
#include <omp.h>

int main()
{
    int i;
    double step;
    double x, pi, sum = 0.0;
    int num_steps = 100000000;
    step = 1.0 / (double) num_steps;

    #pragma omp parallel for reduction(+:sum)
    for (i = 0; i < num_steps; i++)
    {
        x = (i + 0.5) * step;
        sum += 4.0 / (1.0 + x*x);
    }

    pi = step * sum;
    printf("pi is approximately: %.16lf\n",pi);

    return 0;
}
```

