  res.redirect("/");
});

app.get('/search', (req, res) => {
  const query = req.query.query || '';
  const role = req.query.role || '';
  let musicians = [];

  if (query || role) {
    musicians = search(query, role);
  } else {
    const data = fs.readFileSync('./db/musicians.json');
