This app will use the Google Places API to fetch businesses near a location and check if they have a website. To use the Google Places API, you'll need an API key. You can obtain it from the Google Cloud Console.

First, install the required packages:

```bash
npm install axios readline
```

Create a new file called `app.js` and paste the following code:

```javascript
// app.js
const axios = require("axios");
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

// Replace with your Google Places API key
const apiKey = "YOUR_PLACES_API_KEY";

rl.question("Enter a location: ", async (location) => {
  const businessesWithoutWebsite = await findBusinessesWithoutWebsite(location);
  console.log("\nBusinesses without a website:");
  businessesWithoutWebsite.forEach((business) => {
    console.log(`- ${business.name}`);
  });
  rl.close();
});

async function findBusinessesWithoutWebsite(location) {
  try {
    const response = await axios.get(
      `https://maps.googleapis.com/maps/api/geocode/json`,
      {
        params: {
          address: location,
          key: apiKey,
        },
      }
    );

    const { lat, lng } = response.data.results[0].geometry.location;

    const placesResponse = await axios.get(
      `https://maps.googleapis.com/maps/api/place/nearbysearch/json`,
      {
        params: {
          location: `${lat},${lng}`,
          radius: 1500,
          type: "business",
          key: apiKey,
        },
      }
    );

    const businesses = placesResponse.data.results;
    const businessesWithoutWebsite = [];

    for (const business of businesses) {
      const placeDetails = await axios.get(
        `https://maps.googleapis.com/maps/api/place/details/json`,
        {
          params: {
            place_id: business.place_id,
            fields: "name,website",
            key: apiKey,
          },
        }
      );

      if (!placeDetails.data.result.website) {
        businessesWithoutWebsite.push(placeDetails.data.result);
      }
    }

    return businessesWithoutWebsite;
  } catch (error) {
    console.log("Error fetching data:", error);
  }
}
```

