Для улучшения поиска по городам (локациям) вы можете использовать более мощную библиотеку, такую как `geolib` для определения расстояния между двумя координатами (широтой и долготой), преобразованными из названий городов. Вместе с этим, вы можете использовать библиотеку `node-geocoder` для получения координат из названий городов. Изначально добавьте эти зависимости, выполнив команду:

```bash
npm install geolib node-geocoder
```

Теперь импортируйте и настройте `node-geocoder`, добавив следующий код в начале файла:

```javascript
const NodeGeocoder = require("node-geocoder");

const geocoder = NodeGeocoder({
  provider: "openstreetmap"
});
```

Также импортируйте `geolib`:

```javascript
const geolib = require("geolib");
```

Теперь обновите функцию `search()` для использования библиотеки `geolib` и добавления возможности фильтрации по расстоянию:

```javascript
async function search(query = '', role = '', location = '', distance = 100) {
  const data = fs.readFileSync('./db/musicians.json');
  const musicians = JSON.parse(data).musicians.map(musician => {
    return {
      name: musician.name,
      genre: musician.genre,
      originalName: musician.name,
      profileLink: `/profile/${musician.id}`,
      thumbnail: musician.thumbnail,
      soundcloud: musician.soundcloud,
      role: musician.role,
      location: musician.location
    };
  });

  let results = [];

  if (query || role || location) {
    if (location) {
      // Get the coordinates of the user's location
      const userLocationData = await geocoder.geocode(location);
      const userCoords = {
        latitude: userLocationData[0].latitude,
        longitude: userLocationData[0].longitude
      };

      for (const musician of musicians) {
        // Get the coordinates of the musician's location
        const musicianLocationData = await geocoder.geocode(musician.location);
        const musicianCoords = {
          latitude: musicianLocationData[0].latitude,
          longitude: musicianLocationData[0].longitude
        };

        // Calculate the distance between the user's location and the musician's location
        const calculatedDistance = geolib.getDistance(userCoords, musicianCoords);
        musician.distance = calculatedDistance;
      }
    }

    const lowerQuery = query.toLowerCase();
    results = musicians.filter(musician => {
      const nameScore = musician.name.toLowerCase().startsWith(lowerQuery) ? 2 : musician.name.toLowerCase().includes(lowerQuery) ? 1 : 0;
      const genreScore = musician.genre.toLowerCase().startsWith(lowerQuery) ? 2 : musician.genre.toLowerCase().includes(lowerQuery) ? 1 : 0;
      return nameScore + genreScore > 0 && (role === '' || musician.role === role) && (!location || musician.distance / 1000 <= distance);
    }).sort((a, b) => {
      const aNameScore = a.name.toLowerCase().startsWith(lowerQuery) ? 2 : a.name.toLowerCase().includes(lowerQuery) ? 1 : 0;
      const bNameScore = b.name.toLowerCase().startsWith(lowerQuery) ? 2 : b.name.toLowerCase().includes(lowerQuery) ? 1 : 0;
      const aGenreScore = a.genre.toLowerCase().startsWith(lowerQuery) ? 2 : a.genre.toLowerCase().includes(lowerQuery) ? 1 : 0;
      const bGenreScore = b.genre.toLowerCase().startsWith(lowerQuery) ? 2 : b.genre.toLowerCase().includes(lowerQuery) ? 1 : 0;
      return (bNameScore + bGenreScore) - (aNameScore + aGenreScore);
    });
  }

  return results;
}
```

Обратите внимание, что функция `search()` теперь асинхронная, поскольку используется `await` для ожидания результата геокодирования. Теперь вам нужно обновить соответствующий маршрут, чтобы сделать его асинхронным:

```javascript
app.get('/search', async (req, res) => {
  const query = req.query.query || '';
  const role = req.query.role || '';
  const location = req.query.location || '';
  const distance = req.query.distance || 100; // Add distance variable
  let musicians = [];

  if (query || role || location) {
    musicians = await search(query, role, location, distance);
  } else {
    const data = fs.readFileSync('./db/musicians.json');
    musicians = JSON.parse(data).musicians.map(musician => {
      return {
        name: musician.name,
