        location: musician.location
      };
    });
  }

  res.locals.predefinedGenres = predefinedGenres;
  res.render('search', { musicians, query, role, location, distance });

});
```

Теперь, когда пользователь осуществляет поиск, можно указать расстояние (в километрах) для фильтрации результатов. По умолчанию используется значение 100 км. Вы можете отрегулировать это значение или добавить настройку расстояния на странице поиска, чтобы пользователь мог выбрать желаемое значение.

Осталось обновить шаблон поиска (search.ejs), чтобы отобразить расстояние:

```html
<% for (const musician of musicians) { %>
<div class="col-lg-3 col-md-6">
