<script>
import PageHeader from 'components/PageHeader'
import CardRow from 'containers/general/CardRow'

import { OFFSET_LEFT } from 'helpers/oneliners'
import { emitKeyPress } from 'helpers/keyHold'
import { mapState, mapGetters, mapActions, mapMutations } from 'vuex'
import { selectItem } from './helpers/vodLandingActions.helper'

const INITIAL_CARD_INDEX = 0

export default {
  name: 'LandingPage',
  components: { CardRow, PageHeader },
  data () {
    return {
      fasterAnimation: false
    }
  },
  props: {
    landingPageData: {
      type: Array
    },
    displayCount: Boolean,
    headerTitle: String,
    updateSelectedRow: {
      type: Function,
      default: () => null,
      required: false
    },
    updateSelectedCard: {
      type: Function,
      default: () => null,
      required: false
    },
    setActiveRow: {
      type: Number,
      default: 0,
      required: false
    },
    prevSelectedrow: {
      type: Number,
      default: null,
      required: false
    },
    prevSelectedcard: {
      type: Number,
      default: null,
      required: false
    }
  },
  computed: {
    ...mapState({
      navigationActive: state => state.navigation.active,
      activeSection: state => state.landingVod.activeSection,
      activeRow: state => state.landingVod.activeRow,
      activeCards: state => state.landingVod.activeCards,
      disableActiveCard: state => state.landingVod.disableActiveCard,
      themeVariation: state => state.settings.themeVariation,
      coLogoImages: state => state.settings.providerSupportDataCoLogoImages,
      currentTheme: state => state.settings.themeVariation
    }),
    ...mapGetters({
      activeCard: 'landingVod/getActiveCard'
    }),
    rowTransforms () {
      const SMALLER_SCALE_NUMBER = 0.809
      const scale = this.navigationActive ? SMALLER_SCALE_NUMBER : 1
      const heightKey = this.navigationActive ? 'closed' : 'open'

      return this.landingPageData.map((row, index) => {
        const start = Math.min(this.activeRow, index)
        const end = Math.max(this.activeRow, index)
        const direction = this.activeRow > index ? -1 : 1

        const translateY = this.landingPageData
          .slice(start, end)
          .reduce((sum, item) => sum + item.height[heightKey], 0)

        const transform2dRow = `translate(${this.translateX}rem,
          ${translateY * direction}rem) scaleX(${scale}) scaleY(${scale})`

        return {
          transform: transform2dRow
        }
      })
    },
    headerTransform () {
      const TRANSLATE_Y_VALUE = -170
      const translateY = this.activeRow > 0 ? TRANSLATE_Y_VALUE : 0
      const transform2d = `translate(${this.translateX}rem, ${translateY}rem)`
      return {
        transform: transform2d
      }
    },
    translateX () {
      return OFFSET_LEFT[!this.navigationActive ? 'active' : 'inactive']
    }
  },
  methods: {
    ...mapActions({
      toggleNavigation: 'navigation/toggle',
      updateActiveCard: 'landingVod/updateActiveCard'
    }),
    ...mapMutations({
      updateActiveRow: 'landingVod/UPDATE_ACTIVE_ROW',
      updateActiveSection: 'landingVod/UPDATE_ACTIVE_SECTION',
      updateActiveCards: 'landingVod/UPDATE_ACTIVE_CARDS'
    }),
    handleKey (key) {
      if (key === 'BACK') {
        this.toggleNavigation(true)
        return
      }
      if (this.landingPageData.length === 0) {
        this.handleKeyNoStripes(key)
        return
      }
      if (this.activeSection === 'header') {
        this.handleKeyHeader(key)
        return
      }
      if (this.activeSection === 'rows') {
        this.handleKeyStripes(key)
      }
    },
    handleKeyNoStripes (key) {
      const keyFunctions = {
        LEFT: () => {
          this.toggleNavigation(true)
        },
        OK: () => {
          this.$router.push({ name: 'Search' })
        }
      }
      keyFunctions[key] && keyFunctions[key]()
    },
    handleKeyHeader (key) {
      const keyFunctions = {
        DOWN: () => {
          this.updateActiveSection('rows')
        },
        RIGHT: () => {
          this.updateActiveSection('rows')
        },
        LEFT: () => {
          this.toggleNavigation(true)
          this.updateActiveCards(this.landingPageData.map(() => 0))
        },
        OK: () => {
          this.$router.push({ name: 'Search' })
        }
      }
      keyFunctions[key] && keyFunctions[key]()
    },
    handleKeyStripes (key) {
      const keyFunctions = {
        LEFT: () => {
          if (this.activeCard === 0) {
            this.toggleNavigation(true)
            this.updateActiveCards(this.landingPageData.map(() => 0))
          } else {
            this.moveRow(key)
          }
        },
        RIGHT: () => {
          this.moveRow(key)
        },
        UP: () => {
          if (this.activeRow === 0) {
            this.updateActiveSection('header')
          } else {
            this.changeRows(key)
          }
        },
        DOWN: () => {
          this.changeRows(key)
        },
        OK: () => {
          this.selectCard()
        },
        HOLD_STOP: () => {
          this.fasterAnimation = false
        },
        LEFT_HOLD: () => {
          this.handleLeftRightKeyHold(key)
        },
        RIGHT_HOLD: () => {
          this.handleLeftRightKeyHold(key)
        },
        UP_HOLD: () => {
          this.handleUpDownKeyHold(key)
        },
        DOWN_HOLD: () => {
          this.handleUpDownKeyHold(key)
        }
      }
      keyFunctions[key] && keyFunctions[key]()
    },
    handleLeftRightKeyHold (key) {
      if (emitKeyPress({ delay: 150 })) {
        this.moveRow(key === 'LEFT_HOLD' ? 'LEFT' : 'RIGHT')
        this.fasterAnimation = true
      }
    },
    handleUpDownKeyHold (key) {
      if (emitKeyPress({ delay: 250 })) {
        this.changeRows(key === 'UP_HOLD' ? 'UP' : 'DOWN')
        this.fasterAnimation = true
      }
    },
    handleClickBack () {
      this.$router.push({ name: 'Search' })
    },
    moveRow (direction) {
      const offset = direction === 'LEFT' ? -1 : 1
      const currentRow = this.landingPageData[this.activeRow]
      this.updateActiveCard(Math.min(Math.max(this.activeCard + offset, 0), currentRow.cards.length - 1))
    },
    changeRows (direction) {
      const offset = direction === 'UP' ? -1 : 1
      this.updateActiveRow(Math.min(Math.max(this.activeRow + offset, 0), this.landingPageData.length - 1))
    },
    sendRowId (row) {
      const rowRegex = str => str && str.replace(/ +/g, '-').toLowerCase()
      return rowRegex(row.type)
    },
    coLogoImagePath () {
      return this.coLogoImages[this.currentTheme] && this.coLogoImages[this.currentTheme].path
    },
    coLogoImageHeight () {
      return this.coLogoImages[this.currentTheme] && this.coLogoImages[this.currentTheme].height
    },
    handleClick () {
      // console.log('Clicked on item ', param)
    },
    updateSelections (rows) {
      const NUMBER_TWO = 2
      if (!this.landingPageData || this.landingPageData.length === 0) {
        this.updateActiveSection('header')
      } else if (this.$route.meta.fromRoute !== 'Search') {
        this.updateActiveSection('rows')
      } else {
        // no action is needed
      }
      if (this.activeCards.length < NUMBER_TWO) {
        this.updateActiveCards(rows.map(() => 0))
      } else {
        this.updateActiveCards(rows.map(
          (row, index) => this.activeCards[index] && row.cards.length >= this.activeCards[index]
            ? this.activeCards[index]
            : 0))
      }
    },
    selectCard () {
      const item = this.landingPageData[this.activeRow].cards[this.activeCards[this.activeRow]]

      const config = {
        isPlayPause: false,
        shouldPlay: false,
        page: 'VodLanding', // for playPause
        vodDetailData: {}, // for playPause
        imageUrl: '' // for playPause
      }
      selectItem(config, this.$router, item)
    }
  },
  watch: {
    landingPageData (newRows) {
      this.updateSelections(newRows)
      // this.updateActiveCards(newRows)
      if (!newRows || newRows.length === 0) {
        this.showNoItems = true
      } else {
        this.showNoItems = false
      }
    },
    activeRow (newValue) {
      this.updateSelectedRow(newValue)
    },
    activeCard (newValue) {
      this.updateSelectedCard(newValue)
    }
  },
  created () {
    this.updateSelections(this.landingPageData)
    this.updateActiveRow(this.setActiveRow)
    if (this.$route.params && this.$route.params.toggleNavigation) {
      this.toggleNavigation(true)
    }
    if (this.$route.params.rememberSelections !== undefined && this.$route.params.rememberSelections === false) {
      this.updateActiveRow(INITIAL_CARD_INDEX)
      this.updateActiveCards(this.landingPageData.map(() => INITIAL_CARD_INDEX))
    } else {
      this.prevSelectedrow !== null && this.updateActiveRow(this.prevSelectedrow)
      this.prevSelectedcard !== null && this.updateActiveCard(this.prevSelectedcard)
    }
    if (this.$route.meta.fromRoute === 'Search') {
      this.updateActiveSection('header')
    }
  }
}
</script>

