Here's a basic example of using GetRawInputBuffer and NEXTRAWINPUTBLOCK macro for retrieving keyboard events in a game loop. This example is a minimal version and may require further optimization and exception handling for real application use.

1. Include required header files and initialize variables:

```cpp
#include <iostream>
#include <windows.h>
#include <winuser.h>

#define RAW_INPUT_BUFFER_SIZE 64
BYTE rawInputBuffer[RAW_INPUT_BUFFER_SIZE];
UINT rawInputBufferSize = RAW_INPUT_BUFFER_SIZE;
UINT numBytes = 0;
UINT numEvents = 0;
RAWINPUT *rawInput;
```

2. Register for receiving raw input messages for keyboard events:

```cpp
void RegisterRawInput(HWND hWnd)
{
    RAWINPUTDEVICE rid;

    rid.usUsagePage = 0x01; // Generic Desktop Controls
    rid.usUsage = 0x06;     // Keyboard
    rid.dwFlags = 0;
    rid.hwndTarget = hWnd;

    if (RegisterRawInputDevices(&rid, 1, sizeof(rid)) == FALSE)
    {
        std::cerr << "Failed to register raw input" << std::endl;
        exit(1);
    }
}
```

3. In your game loop or callback function, call GetRawInputBuffer to process raw input events:

```cpp
void ProcessRawInput()
{
    numBytes = GetRawInputBuffer((PRAWINPUT)rawInputBuffer, &rawInputBufferSize, sizeof(RAWINPUTHEADER));

    if (numBytes == (UINT)-1)
    {
        return;
    }

    rawInput = (RAWINPUT *)rawInputBuffer;
    while (numEvents < numBytes)
    {
        if (rawInput->header.dwType == RIM_TYPEKEYBOARD)
        {
            UINT keyCode = rawInput->data.keyboard.VKey;
            UINT flags = rawInput->data.keyboard.Flags;

            if (flags & RI_KEY_BREAK)
            {
                std::cout << "Key released: " << keyCode << std::endl;
            }
            else
            {
                std::cout << "Key pressed: " << keyCode << std::endl;
            }
        }

        numEvents += rawInput->header.dwSize;
        rawInput = NEXTRAWINPUTBLOCK(rawInput);
    }

    numEvents = 0;
}
```

