struct Tree {
    double l, r;
} trees[MAXN];

int cmp(const void *a, const void *b) {
    struct Tree *t1 = (struct Tree *)a, *t2 = (struct Tree *)b;
    return (t1->l < t2->l) ? -1 : 1;
}

double visible_trees(double diameter, double x, double y) {
    int cnt = 0, i, j;
    double ang, half_ang;
    for (i = (int)ceil(-x); i < (int)floor(1.0 - x); i++) {
        for (j = (int)ceil(-y); j < (int)floor(1.0 - y); j++) {
            if (i == 0 && j == 0) continue;
            ang = atan2((double)j, (double)i);
            half_ang = asin(diameter / (2 * hypot((double)i - x, (double)j - y)));
            trees[cnt].l = ang - half_ang;
            trees[cnt].r = ang + half_ang;
            cnt++;
        }
    }

    qsort(trees, cnt, sizeof(struct Tree), cmp);

    double max_ang = -1.0;
    int visible = 0;
    for (i = 0; i < cnt; i++) {
        if (trees[i].r - trees[i].l > EPS && trees[i].l > max_ang + EPS) {
            max_ang = trees[i].r;
            visible++;
        } else if (trees[i].r > max_ang + EPS) {
            max_ang = trees[i].r;
        }
    }

    return visible;
}

int main() {
    double diameter, x, y;
    while (scanf("%lf %lf %lf", &diameter, &x, &y) == 3 && (diameter > EPS || x > EPS || y > EPS)) {
        printf("%d\n", (int)visible_trees(diameter, x, y));
    }
    return 0;
}
