#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char op;
    int x, y;
    int inputs[2];
    int num_inputs;
} Operation;

Operation circuit[10];
bool test_values[10];

void parse_operation(const char *line, Operation *op) {
    op->x = line[0] - '0';
    op->y = line[1] - '0';
    op->op = line[2];

    op->num_inputs = 0;
    for (int i = 3; line[i] != '.'; i += 2) {
        op->inputs[op->num_inputs++] = (line[i] - '0') * 10 + (line[i + 1] - '0');
    }
}

bool execute_operation(const Operation *op) {
    switch (op->op) {
    case 'i':
        return test_values[op->x];
    case '!':
        return !execute_operation(&circuit[op->inputs[0]]);
    case '&':
        return execute_operation(&circuit[op->inputs[0]]) & execute_operation(&circuit[op->inputs[1]]);
    case '|':
        return execute_operation(&circuit[op->inputs[0]]) | execute_operation(&circuit[op->inputs[1]]);
    case 'o':
    default:
        return execute_operation(&circuit[op->inputs[0]]);
    }
}

int main() {
    int n;
    scanf("%d", &n);

    char line[32];
    fgets(line, sizeof(line), stdin);  // Consume newline

    for (int i = 0; i < n; ++i) {
        int num_operations = 0;

        while (fgets(line, sizeof(line), stdin) && strncmp(line, "end", 3) != 0) {
            parse_operation(line, &circuit[num_operations]);
            num_operations++;
        }

        int t;
        scanf("%d", &t);
        fgets(line, sizeof(line), stdin);  // Consume newline

        for (int j = 0; j < t; ++j) {
            fgets(line, sizeof(line), stdin);

            for (int k = 0; k < num_operations; ++k) {
                if (circuit[k].op == 'i') {
                    test_values[circuit[k].x] = line[k] == '1';
                }
            }

            for (int k = 0; k < num_operations; ++k) {
                if (circuit[k].op == 'o') {
                    printf("%d", execute_operation(&circuit[k]));
                }
            }
            putchar('\n');
        }
        putchar('\n');
    }

    return 0;
}
```

