```csharp
public static string BuildPostData(string content, params FieldData[] fields)
{
    var ids = GetVisibleIdsByCss(content);
    var postData = new StringBuilder();

    if (ids == null || ids.Length == 0)
    {
        foreach (var field in fields)
            postData.Append($"{field.Name}={field.Value}&");
    }
    else
    {
        foreach (var field in fields)
        {
            var fieldId = ids.FirstOrDefault(i => i.StartsWith(field.Name, StringComparison.OrdinalIgnoreCase));
            if (string.IsNullOrEmpty(fieldId) || !int.TryParse(fieldId.Remove(0, field.Name.Length), out var num))
            {
                postData.Append($"{field.Name}={field.Value}&");
            }
            else
            {
                AppendFieldValues(postData, field, num);
            }
        }
    }

    var scriptData = Regex.Match(content, "name=\"ScriptData\" type=\"hidden\" value=\"([^\"]+)\"").Groups[1].Value;
    if (!string.IsNullOrEmpty(scriptData))
        postData.Append($"{WebUtility.UrlEncode(WebUtility.HtmlDecode(scriptData))}&");

    return postData.ToString().TrimEnd('&');
}

private static void AppendFieldValues(StringBuilder postData, FieldData field, int targetNum)
{
    for (var i = 1; i <= field.MaxNum; i++)
    {
        postData.Append(field.Name);
        postData.Append(i);
        if (i == targetNum)
            postData.Append($"={field.Value}&");
        else
            postData.Append("=&");
    }
}

public sealed class FieldData
{
    public string Name { get; set; }
    public string Value { get; set; }
    public int MaxNum { get; set; }
    public FieldData(string name, string value, int maxNum = 10)
    {
        Name = name;
        Value = value;
        MaxNum = maxNum;
    }
}
