// 播放歌曲函数
void play_song(u16* freq_list, u16* time_list) {
    unsigned char i = 0;
    unsigned int val;
    song_playing = 1;

    while (freq_list[i]) {
        val = Clk / (freq_list[i]);
        val = 0xFFFF - val;
        val_H = (val >> 8) & 0xff;
        val_L = val & 0xff;
        TH0 = val_H;
        TL0 = val_L;
        Delay(time_list[i]);
        i++;

        if (key_scan(0) != KEY_UNPRESS) {
            break;
        }
    }

    song_playing = 0;
}

void main()
{
    u8 key = 0;
    u8 current_song = 0;

    TMOD = 0x01;
    IE = 0x82;
    TR0 = 1;

    while (1)
    {
        key = key_scan(0);

        if (key == KEY1_PRESS) {
            current_song = 1;
        } else if (key == KEY2_PRESS) {
            current_song = 2;
        } else if (key == KEY3_PRESS) {
            current_song = 3;
        }

        if (current_song == 1) {
            play_song(freq_list1, time_list1);
        } else if (current_song == 2) {
            play_song(freq_list2, time_list2);
        } else if (current_song == 3) {
            play_song(freq_list3, time_list3);
        }
    }
}
```

