```c
#include "public.h"
#include "key.h"
#include "beep.h"
#include "songdata.h"
#define Clk 0x070000
unsigned char data val_H; //计数器高字节
unsigned char data val_L; //计数器低字节
sbit P00 = P2^5; //扬声器控制引脚
bit song_playing = 0; // 添加歌曲播放标志

void t0_isr() interrupt 1 //定时器 0 中断处理程序
{
    if (song_playing) { // 当歌曲播放标志为真时，产生方波
        P00 = ~P00;
    } else {
        P00 = 1; // 不产生方波，关闭蜂鸣器
    }
    TH0 = val_H; //重新装入计数值
    TL0 = val_L;
}
void Delay(unsigned char cnt) //单位延时
{
    unsigned char i;
    unsigned int j;
    for(i=0; i<cnt; i++)
    {
        for(j=0; j<0x3600; j++);
    }
}

void main()
{
    u8 key;
    u8 beep_flag = 0;
    unsigned int val;
    unsigned char i = 0;
    TMOD = 0x01; //初始化
    IE = 0x82;
    TR0 = 1;
    while (1)
    {
        key = key_scan(0);

        if (key == KEY1_PRESS || key == KEY2_PRESS || key == KEY3_PRESS) {
            if (beep_flag == key) {
                beep_flag = 0;
            } else {
                beep_flag = key;
                i = 0;
            }
        }

        if (beep_flag == KEY1_PRESS) {
            song_playing = 1;
            while (freq_list1[i]) {
                val = Clk / (freq_list1[i]);
                val = 0xFFFF - val;
                val_H = (val >> 8) & 0xff;
                val_L = val & 0xff;
                TH0 = val_H;
                TL0 = val_L;
                Delay(time_list1[i]);
                i++;

                u8 temp_key = key_scan(0);
                if (temp_key == KEY1_PRESS || temp_key == KEY2_PRESS || temp_key == KEY3_PRESS) {
                    break;
                }
            }
        }
        else if (beep_flag == KEY2_PRESS) {
            song_playing = 1;
            while (freq_list2[i]) {
                val = Clk / (freq_list2[i]);
                val = 0xFFFF - val;
                val_H = (val >> 8) & 0xff;
                val_L = val & 0xff;
                TH0 = val_H;
                TL0 = val_L;
                Delay(time_list2[i]);
                i++;

                u8 temp_key = key_scan(0);
                if (temp_key == KEY1_PRESS || temp_key == KEY2_PRESS || temp_key == KEY3_PRESS) {
                    break;
                }
            }
        }
        else if (beep_flag == KEY3_PRESS) {
            song_playing = 1;
            while (freq_list3[i]) {
                val = Clk / (freq_list3[i]);
                val = 0xFFFF - val;
                val_H = (val >> 8) & 0xff;
                val_L = val & 0xff;
                TH0 = val_H;
                TL0 = val_L;
                Delay(time_list3[i]);
                i++;

                u8 temp_key = key_scan(0);
                if (temp_key == KEY1_PRESS || temp_key == KEY2_PRESS || temp_key == KEY3_PRESS) {
                    break;
                }
            }
        }
        else {
            song_playing = 0;
        }
    }
}

