我们可以在歌曲播放的循环里面，当检测到按键时，进入一个子循环，一直等待按键释放。这样在按下按键时，歌曲就会暂停播放。修改后的代码如下：

```c
void main()
{
    u8 key = 0;
    u8 beep_flag1 = 0; //蜂鸣器状态标志
    u8 beep_flag2 = 0;
    u8 beep_flag3 = 0;
    unsigned int val;
    unsigned char i = 0;
    TMOD = 0x01; //初始化
    IE = 0x82;
    TR0 = 1;
    while (1)
    {
        key = key_scan(0); //检测按键
        if (key == KEY1_PRESS) //K1按下，放第一首歌
        {
            beep_flag1 = !beep_flag1;
            beep_flag2 = 0;
            beep_flag3 = 0;
            i = 0;
        }
        else if (key == KEY2_PRESS) //K2按下放第二首歌
        {
            beep_flag2 = !beep_flag2;
            beep_flag1 = 0;
            beep_flag3 = 0;
            i = 0;
        }
        else if (key == KEY3_PRESS) //K3按下放第三首歌
        {
            beep_flag3 = !beep_flag3;
            beep_flag1 = 0;
            beep_flag2 = 0;
            i = 0;
        }

        if (beep_flag1) {
            song_playing = 1;
            while (freq_list1[i]) // 频率为 0 重新开始
            {
                val = Clk / (freq_list1[i]);
                val = 0xFFFF - val; // 计算计数值
                val_H = (val >> 8) & 0xff;
                val_L = val & 0xff;
                TH0 = val_H;
                TL0 = val_L;
                Delay(time_list1[i]);
                i++;
                while (key_scan(0) != KEY_UNPRESS) Delay(1); // 如果按键按下，暂停播放
            }
        }
        else if (beep_flag2) {
            song_playing = 1;
            while (freq_list2[i]) // 频率为 0 重新开始
            {
                val = Clk / (freq_list2[i]);
                val = 0xFFFF - val; // 计算计数值
                val_H = (val >> 8) & 0xff;
                val_L = val & 0xff;
                TH0 = val_H;
                TL0 = val_L;
                Delay(time_list2[i]);
                i++;
                while (key_scan(0) != KEY_UNPRESS) Delay(1); // 如果按键按下，暂停播放
            }
        }
        else if (beep_flag3) {
            song_playing = 1;
            while (freq_list3[i]) // 频率为 0 重新开始
            {
                val = Clk / (freq_list3[i]);
                val = 0xFFFF - val; // 计算计数值
                val_H = (val >> 8) & 0xff;
                val_L = val & 0xff;
                TH0 = val_H;
                TL0 = val_L;
                Delay(time_list3[i]);
                i++;
                while (key_scan(0) != KEY_UNPRESS) Delay(1); // 如果按键按下，暂停播放
            }
        }
        else {
            song_playing = 0; // 没有歌曲在播放，设置歌曲播放标志为假
        }
    }
}
```

在每个播放循环里面，`while (key_scan(0) != KEY_UNPRESS) Delay(1)` 这一行是新加的代码。功能为：当按键按下时，进入一个子循环一直等待按键释放。这样在按下按键时，歌曲就会暂停播放。

