1. Для начала, установите `typeahead.js`: 

```
npm install typeahead.js
```

2. Добавьте ссылку на скрипт в ваш файл `search.ejs`:

```html
<script src="/node_modules/typeahead.js/dist/typeahead.bundle.min.js"></script>
```

3. Замените код `jquery-autocomplete` на следующий код для инициализации `typeahead.js`:

```javascript
document.addEventListener("DOMContentLoaded", function () {
    const cities = <%= JSON.stringify(citiesAndRegions.map(item => item.city)) %>;

    const cityInput = document.querySelector("#city");
    const citiesDataset = {
        name: "cities",
        limit: 10,
        source: function (query, syncResults, asyncResults) {
            const matches = [];
            const regex = new RegExp(query, "i");
            for (let i = 0; i < cities.length; i++) {
                if (regex.test(cities[i])) {
                    matches.push(cities[i]);
                    if (matches.length >= 10) break;
                }
            }
            asyncResults(matches);
        }
    };

    const cityTypeahead = new Bloodhound({
        datumTokenizer: Bloodhound.tokenizers.whitespace,
        queryTokenizer: Bloodhound.tokenizers.whitespace,
        local: cities
    });

    $("#city").typeahead({
        hint: true,
        highlight: true,
        minLength: 1
    },
    {
        name: "cities",
        source: cityTypeahead
    });

    const queryInput = document.querySelector("#query");
    const roleInput = document.querySelector("#role");

    queryInput.value = "<%= query %>";
    roleInput.value = "<%= role %>";
    cityInput.value = cityInput.getAttribute('data-value');

    const query = queryInput.value;
    const role = roleInput.value;
    const city = cityInput.value;
});
```

