#include "udf.h"

#define DIAMETER 0.02 // circle diameter in meters
#define RADIUS (DIAMETER * 0.5)
#define RPM 30 // rounds per minute
#define OMEGA (2.0*3.14159265*RPM/60.0) // Angular velocity (rad/s)

real calculate_tangential_velocity(real x, real y, real x_center, real y_center)
{
    real r = sqrt((x-x_center)*(x-x_center) + (y-y_center)*(y-y_center));
    real v_tan = OMEGA * r;
    return v_tan;
}

DEFINE_PROFILE(tangential_velocity, thread, position)
{
    real x[ND_ND];         // coordinates
