为了实现这个功能，我们可以对代码进行如下修改：

1. 在主循环中调用matrix_keypad_scan()函数检测矩阵键盘的按键，根据按键来选择需要演奏的音符，并保存至music_buffer数组；
2. 添加一个功能选择标志位（play_record_flag），如1表示演奏功能，2表示自动播放保存的音乐；
3. 根据play_record_flag的值判断是进行演奏功能还是自动播放；
4. 在自动播放功能中，读取music_buffer数组的内容，根据保存的音符播放相应的声音；

下面是实现这个功能的具体代码：

```c
#include "public.h"
#include "key.h"
#include "beep.h"
#include "songdata.h"
#define Clk 0x070000


unsigned char data val_H; //计数器高字节
unsigned char data val_L; //计数器低字节


#define ROWS 4
#define COLS 4


sbit P00 = P2^5; //扬声器控制引脚


// 定义矩阵键盘的行列对应的引脚
sbit row1 = P1^7;
sbit row2 = P1^6;
sbit row3 = P1^5;
sbit row4 = P1^4;
sbit col1 = P1^3;
sbit col2 = P1^2;
sbit col3 = P1^1;
sbit col4 = P1^0;


// 音符频率数组
unsigned int freq[] = {262, 294, 330, 349, 392, 440, 494, 523, 0, 587, 659, 698, 784};

// 音乐保存缓冲区，最多可以保存32个音符
unsigned char music_buffer[32];
unsigned char music_length = 0;

// 定义矩阵键盘的键值
const unsigned char keymap[ROWS][COLS] = {
    {'1', '2', '3', 'A'},
    {'4', '5', '6', 'B'},
    {'7', '8', '9', 'C'},
    {'*', '0', '#', 'D'}
};


bit song_playing = 0; // 添加歌曲播放标志

void t0_isr() interrupt 1 //定时器 0 中断处理程序
{
    if (song_playing) { // 当歌曲播放标志为真时，产生方波
        P00 = ~P00;
    } else {
        P00 = 1; // 不产生方波，关闭蜂鸣器
    }
    TH0 = val_H; //重新装入计数值
    TL0 = val_L;
}



void Delay(unsigned char cnt) //单位延时
{
  unsigned char i;
   unsigned int j;
   for(i=0; i<cnt; i++)
{
    for(j=0; j<0x3600; j++);
}
}



char matrix_keypad_scan() 
{
    char key = 0;
    int i, j;

    // 将所有行置为高电平，所有列置为输入模式
    row1 = 1; row2 = 1; row3 = 1; row4 = 1;
    col1 = 0; col2 = 0; col3 = 0; col4 = 0;

    // 检测每一行的状态
    for (i = 0; i < ROWS; i++) {
        switch (i) {
            case 0: row1 = 0; break;
            case 1: row2 = 0; break;
            case 2: row3 = 0; break;
            case 3: row4 = 0; break;
        }
        delay_10us(1000);

        // 检测每一列的状态
        for (j = 0; j < COLS; j++) {
            if (col1 == 0) {
                key = keymap[i][j];
                break;
            }
            if (col2 == 0) {
                key = keymap[i][j+1];
                break;
            }
            if (col3 == 0) {
                key = keymap[i][j+2];
                break;
            }
            if (col4 == 0) {
                key = keymap[i][j+3];
                break;
            }
        }

        // 如果检测到按键，跳出循环
        if (key != 0) {
            break;
        }

        // 恢复所有列的状态为输入模式
        col1 = 1; col2 = 1; col3 = 1; col4 = 1;
    }

    // 等待按键释放
    while (col1==0 || col2==0 || col3==0 || col4==0);

    return key;
}




void main()
{
    u8 key = 0;
    u8 play_record_flag = 0; //功能选择标志，1表示演奏功能，2表示自动播放
    unsigned int val;
    unsigned char i = 0;
    TMOD = 0x01; //初始化
    IE = 0x82;
    TR0 = 1;
    while (1)
    {
        key = matrix_keypad_scan(); //检测矩阵键盘按键

        if (key == 'A') // 按下A键, 进入演奏功能模式
        {
            play_record_flag = 1;
            music_length = 0; // 清零音乐长度，准备录制新的音乐
        }
        else if (key == 'B') // 按下B键, 进入自动播放功能模式
        {
            play_record_flag = 2;
        }

        if (play_record_flag == 1) //进行演奏功能
        {
            if (key >= '1' && key <= '9') { // 当前按键为1-9时，播放相应的声音
                val = Clk / (freq[key - '1']);
                val = 0xFFFF - val;
                val_H = (val >> 8) & 0xff;
                val_L = val & 0xff;
                TH0 = val_H;
                TL0 = val_L;
                Delay(100); // 延时100ms

                // 将音符保存至music_buffer数组
                if (music_length < 32) {
                    music_buffer[music_length++] = key - '1';
                }
            }
        }
        else if (play_record_flag == 2) //进行自动播放功能
        {
            song_playing = 1;
            for (i = 0; i < music_length; i++) {
                val = Clk / (freq[music_buffer[i]]);
                val = 0xFFFF - val;
                val_H = (val >> 8) & 0xff;
                val_L = val & 0xff;
                TH0 = val_H;
                TL0 = val_L;
                Delay(100); // 延时100ms
            }
        }
        else {
            song_playing = 0;
        }



    }
}

```
