#include <stdio.h>

int main() {
    int N, k;

    while (1) {
        scanf("%d %d", &N, &k);
        if (N == 0 && k == 0) break;

        int students[N];
        for (int i = 0; i < N; i++) students[i] = 0;

        int queue[N], qhead = 0, qtail = N;
        for (int i = 0; i < N; i++) queue[i] = i;

        int outputStore = 0, storeLimit = 1;
        while (qhead != qtail) {
            int student = queue[qhead++];
            qhead %= N;

            if (outputStore == 0) {
                outputStore = storeLimit++;
                if (storeLimit > k) storeLimit = 1;
            }

            if (students[student] + outputStore <= 40) {
                students[student] += outputStore;
                outputStore = 0;
            } else {
                outputStore -= (40 - students[student]);
                students[student] = 40;
            }

            if (students[student] < 40) {
                queue[qtail++] = student;
                qtail %= N;
            } else {
                printf("%3d", student + 1);
            }
        }
        printf("\n");
    }

    return 0;
}
