    int digits[9] = {0};
    bool valid = false;
    bool ambiguous = false;

    for (int i = 0; i < 9; i++)
    {
        int candidates = 0;
        int candidate_digit = 0;
        for (int j = 0; j < 10; j++)
        {
            if (matchPattern(j, account[0] + i * 3) && matchPattern(j, account[1] + i * 3) &&
