    x.reset_notifier(); // Resets the notifier
    x = 5;
    REQUIRE(notified_value == 10); // Should still be 10, because notifier was reset

    auto change_handler = [&](int value) { x = value * 2; };
    x.set_setter(change_handler);
    x.request_change(7);
    REQUIRE(x.value() == 14);

    x.reset_setter(); // Resets the setter
    x.request_change(9);
    REQUIRE(x.value() == 9); // Should be 9, because the setter was reset
