Absolutely! Here's an example implementation of a draggable window using C++ in UE5. In this example, we'll use the Actor component as a base class for our draggable window.

1. Create a new C++ class that inherits from AActor, and name it "DraggableWindow". Here's the header file (DraggableWindow.h):

```cpp
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "DraggableWindow.generated.h"

UCLASS()
class YOURPROJECT_API ADraggableWindow : public AActor
{
    GENERATED_BODY()

public:    
    ADraggableWindow();

    virtual void Tick(float DeltaTime) override;

    virtual void BeginPlay() override;

protected:
    UPROPERTY(VisibleAnywhere, Category = "Components")
    class UWidgetComponent* WidgetComponent;

    UPROPERTY()
    bool bIsDragging;

    UPROPERTY()
    FVector DragOffset;

public:
    virtual void NotifyHit(UPrimitiveComponent* MyComp, AActor* Other, UPrimitiveComponent* OtherComp, bool bSelfMoved, FVector HitLocation, FVector HitNormal, FVector NormalImpulse, const FHitResult& Hit) override;

};
```

2. Implement the new C++ class in the source file (DraggableWindow.cpp):

```cpp
#include "DraggableWindow.h"
#include "Components/WidgetComponent.h"
#include "GameFramework/PlayerController.h"
#include "Blueprint/UserWidget.h"

ADraggableWindow::ADraggableWindow()
{
    PrimaryActorTick.bCanEverTick = true;

    WidgetComponent = CreateDefaultSubobject<UWidgetComponent>(TEXT("WidgetComponent"));
    WidgetComponent->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
    WidgetComponent->SetCollisionResponseToAllChannels(ECollisionResponse::ECR_Overlap);
    WidgetComponent->SetSimulatePhysics(false);
    WidgetComponent->SetupAttachment(RootComponent);

    bIsDragging = false;
}

void ADraggableWindow::BeginPlay()
{
    Super::BeginPlay();
}

void ADraggableWindow::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);

    if (bIsDragging)
    {
        // Perform dragging logic
        APlayerController* PC = Cast<APlayerController>(GetWorld()->GetFirstPlayerController());
        if (PC)
        {
            FVector MouseLocation, MouseDirection;
            PC->DeprojectMousePositionToWorld(MouseLocation, MouseDirection);

            FVector NewLocation = MouseLocation + (MouseDirection * DragOffset.Z);
            NewLocation.X = FMath::Clamp(NewLocation.X, -2000.0f, 2000.0f);
            NewLocation.Y = FMath::Clamp(NewLocation.Y, -2000.0f, 2000.0f);
            SetActorLocation(NewLocation);
        }
    }
}

void ADraggableWindow::NotifyHit(UPrimitiveComponent* MyComp, AActor* Other, UPrimitiveComponent* OtherComp, bool bSelfMoved, FVector HitLocation, FVector HitNormal, FVector NormalImpulse, const FHitResult& Hit)
{
    Super::NotifyHit(MyComp, Other, OtherComp, bSelfMoved, HitLocation, HitNormal, NormalImpulse, Hit);

    bIsDragging = !bIsDragging;

    if (bIsDragging)
    {
        FVector WidgetHitLocation = WidgetComponent->GetComponentLocation();
        float DistanceZ = FVector::DistXY(HitLocation, WidgetHitLocation);
        DragOffset = HitLocation - WidgetHitLocation;
        DragOffset.Z = DistanceZ;
    }
}
```

In this implementation, we use NotifyHit (instead of OnMouseButtonDown) to detect when mouse input begins and ends. The NotifyHit function is called when the actor is hit by something in the world, in this case, the mouse click.

Please don't forget to replace "YOURPROJECT" in the header file with your actual project title and include the necessary header files.

