public class CompareDWG {
   public static void main(String[] args) throws Exception {

      // Paths of the two DWG files to compare
      String path1 = "C:\\path\\to\\dwg1.dwg";
      String path2 = "C:\\path\\to\\dwg2.dwg";

      // Open the two DWG files
      Database db1 = new Database();
      FileInputStream fis1 = new FileInputStream(new File(path1));
      db1.readDwg(fis1, true);

      Database db2 = new Database();
      FileInputStream fis2 = new FileInputStream(new File(path2));
      db2.readDwg(fis2, true);

      // Compare the two DWG files
      boolean areEqual = Objects.deepEquals(db1, db2);

      // Print the comparison result
      if (areEqual) {
