int main(int argc, char *argv[])
{
    // Initialize SDL
    SDL_Init(SDL_INIT_VIDEO);

    // Create a window
    SDL_Window *window = SDL_CreateWindow("SDL2 Example", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, 640, 480, SDL_WINDOW_SHOWN);

    // Create a renderer
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    // Load the BMP image
    SDL_Surface* image = SDL_LoadBMP("example.bmp");
    SDL_Texture* texture = SDL_CreateTextureFromSurface(renderer, image);

    // Get the image dimensions
    int width = image->w;
    int height = image->h;

    // Calculate the center of the window
    int centerX = (640 - width) / 2;
    int centerY = (480 - height) / 2;

    // Clear the renderer
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
    SDL_RenderClear(renderer);

    // Display the image in the center of the window
    SDL_Rect dstRect = { centerX, centerY, width, height };
    SDL_RenderCopy(renderer, texture, NULL, &dstRect);

    // Render the frame
    SDL_RenderPresent(renderer);

    // Wait for 5 seconds
    SDL_Delay(5000);

    // Clean up resources
    SDL_DestroyTexture(texture);
    SDL_FreeSurface(image);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
