fn parse_group(input: &mut Peekable<std::vec::IntoIter<TokenTree>>, delimiter: Delimiter) -> Result<Group, Error> {
    let mut output = TokenStream::new();

    while let Some(token) = input.next() {
        match token {
            TokenTree::Group(group) => {
                if group.delimiter() == delimiter {
                    output.extend(group.stream());
                } else {
                    output.extend(std::iter::once(TokenTree::Group(group)));
                }
            }
            _ => output.extend(std::iter::once(token)),
        }
    }

    Ok(Group::new(delimiter, output))
}

