```c
#include "public.h"
#include "key.h"
#include "beep.h"
#include "songdata.h"
#define Clk 0x070000

bit music_pause = 0;  // 添加暂停标志
unsigned char music_play_count = 0; //当前正在播放的音符下标
bit music_rewind_flag = 0;  // 添加回退上一个位置的标志
unsigned char last_note = 0;  // 上一个音符下标，用于回退功能

void main(void) 
{

  unsigned char keyval;

  u8 key = 0;
  u8 beep_flag1 = 0; // 蜂鸣器状态标志
  u8 beep_flag2 = 0;
  u8 beep_flag3 = 0;
  u8 beep_flag4 = 0;
  unsigned int val;
  unsigned char i = 0;
  TMOD = 0x01; // 初始化
  IE = 0x82;
  TR0 = 1;

  while (1)
  {
        // 当 K4 按下时候，入读取音符状态
        if (key_scan(0) == KEY4_PRESS) {

            // 清除音乐缓冲区以及长度
            music_length = 0;
            memset(music_buffer, 0, 32);

            // 获取音符
            while (1) {
              keyval = matrix_keypad_scan();
              if (keyval == '*') {
                break; // 在键盘上按 '*' 退出功能
              } 
              Delay(100);
              if (keyval != 0) {
                  music_buffer[music_length++] = keyval;
              }
            }
        }

        // 当 K3 按下时候，播放或暂停音乐
        if (key_scan(0) == KEY3_PRESS) {
          music_pause = !music_pause;
        }


        // 当 K2 按下时，暂停播放, 前进到下一个音符
        if (key_scan(0) == KEY2_PRESS) {
          last_note = music_play_count;
          music_rewind_flag = 0; // 清除回退标志
          music_pause = 1;
          music_play_count++;
        }

        // 当 K1 按下时，暂停播放，回退到上一个音符
        if (key_scan(0) == KEY1_PRESS) {
          music_play_count = last_note;
          music_rewind_flag = 1;
          music_pause = 1;
        }

        if (!music_pause) {
            if (music_play_count < music_length) {
              keyval = music_buffer[music_play_count]++;
              switch (keyval) {
              case '1': val = Clk / (freq[0]); break;
              case '2': val = Clk / (freq[1]); break;
              case '3': val = Clk / (freq[2]); break;
              case '4': val = Clk / (freq[3]); break;
              case '5': val = Clk / (freq[4]); break;
              case '6': val = Clk / (freq[5]); break;
              case '7': val = Clk / (freq[6]); break;
              case '8': val = Clk / (freq[7]); break;
              case '9': val = Clk / (freq[8]); break;
              case 'A': val = Clk / (freq[9]); break;
              case 'B': val = Clk / (freq[10]); break;
              case 'C': val = Clk / (freq[11]); break;
              case 'D': val = Clk / (freq[12]); break;
              default: break;
              }

              // 设置碰撞器退出当前音符循环
              val = 0xFFFF - val; // 计算计数值
              val_H = (val >> 8) & 0xff;
              val_L = val & 0xff;
              TH0 = val_H;
              TL0 = val_L;

              // 同时设置音符播放标志为真
              song_playing = 1;
              delay(100); // 等待音符持续时间

              if (music_rewind_flag == 0) {
                  last_note = music_play_count - 1;
              } else {
                  music_rewind_flag = 0; // 清除回退标志
              }

            } else {
              song_playing = 0;
              music_pause = 1;
              music_play_count = 0;
            }
        }
  }

}
