use proc_macro2::TokenStream;
use syn::{Expr, parse::{Parse, ParseStream}};

struct CustomExpr {
    expr: Option<Expr>,
}

impl Parse for CustomExpr {
    fn parse(input: ParseStream) -> syn::Result<Self> {
        let expr = input.parse::<Expr>().ok();
        Ok(Self { expr })
