```

2. Instead of using raw Vulkan C API functions, you can now use the C++ functions provided by the Vulkan-hpp library:

Here's a modified version of "BufferUtils.cpp":

```cpp
#include "BufferUtils.h"

#include <stdexcept>

Buffer BufferUtils::createBuffer(
    const vk::Device& device, const vk::PhysicalDevice& physicalDevice,
    vk::DeviceSize size, vk::BufferUsageFlags usage, vk::MemoryPropertyFlags properties)
{
    Buffer result;

    vk::BufferCreateInfo bufferInfo{};
    bufferInfo.size = size;
    bufferInfo.usage = usage;
    bufferInfo.sharingMode = vk::SharingMode::eExclusive;

    result.buffer = device.createBufferUnique(bufferInfo);

    vk::MemoryRequirements memRequirements = device.getBufferMemoryRequirements(*result.buffer);

    vk::MemoryAllocateInfo allocInfo{};
    allocInfo.allocationSize = memRequirements.size;
    allocInfo.memoryTypeIndex = findMemoryType(physicalDevice, memRequirements.memoryTypeBits, properties);

    result.memory = device.allocateMemoryUnique(allocInfo);

    device.bindBufferMemory(*result.buffer, *result.memory, 0);

    return result;
}

uint32_t BufferUtils::findMemoryType(const vk::PhysicalDevice& physicalDevice, uint32_t typeFilter, vk::MemoryPropertyFlags properties)
{
    vk::PhysicalDeviceMemoryProperties memProperties = physicalDevice.getMemoryProperties();

    for (uint32_t i = 0; i < memProperties.memoryTypeCount; i++)
    {
        if ((typeFilter & (1 << i)) && (memProperties.memoryTypes[i].propertyFlags & properties) == properties)
        {
            return i;
        }
    }

    throw std::runtime_error("Failed to find suitable memory type!");
}

void BufferUtils::copyBuffer(
    const vk::Device& device, const vk::CommandPool& commandPool, const vk::Queue& graphicsQueue,
    const vk::Buffer& srcBuffer, const vk::Buffer& dstBuffer, vk::DeviceSize size)
{
    vk::CommandBufferAllocateInfo allocInfo{};
    allocInfo.level = vk::CommandBufferLevel::ePrimary;
    allocInfo.commandPool = commandPool;
    allocInfo.commandBufferCount = 1;

    vk::UniqueCommandBuffer commandBuffer = std::move(device.allocateCommandBuffersUnique(allocInfo).front());

    vk::CommandBufferBeginInfo beginInfo{};
    beginInfo.flags = vk::CommandBufferUsageFlagBits::eOneTimeSubmit;

    commandBuffer->begin(beginInfo);

    vk::BufferCopy copyRegion{};
    copyRegion.srcOffset = 0;
    copyRegion.dstOffset = 0;
    copyRegion.size = size;
    commandBuffer->copyBuffer(srcBuffer, dstBuffer, { copyRegion });

    commandBuffer->end();

    vk::SubmitInfo submitInfo{};
    submitInfo.commandBufferCount = 1;
    submitInfo.pCommandBuffers = &*commandBuffer;

    graphicsQueue.submit(submitInfo, nullptr);
    graphicsQueue.waitIdle();
}
```

Note: To use Vulkan-hpp library, make sure to include the "vulkan.hpp" header file instead of "vulkan/vulkan.h". Also, you may need to update other parts of your codebase to use Vulkan-hpp wrapper objects for better compatibility.

