Here's a simple example of a base class for a draggable window using the Unreal Engine 4 API:

```cpp
// DraggableWindow.h

#pragma once

#include "CoreMinimal.h"
#include "Components/Overlay.h"
#include "DraggableWindow.generated.h"

UCLASS()
class YOUR_PROJECT_API UDraggableWindow : public UOverlay
{
    GENERATED_BODY()

public:
    UDraggableWindow();

protected:
    UPROPERTY(BlueprintReadWrite, EditDefaultsOnly, Category = "Draggable Window")
    float TitleBarHeight;

    virtual void NativeConstruct() override;

private:
    UFUNCTION()
    void OnMouseDown(FGeometry MyGeometry, const FPointerEvent& MouseEvent);

    UFUNCTION()
    void OnMouseUp(FGeometry MyGeometry, const FPointerEvent& MouseEvent);

    UFUNCTION()
