```cpp
// DraggableWindow.cpp

#include "DraggableWindow.h"
#include "UMG.h"

UDraggableWindow::UDraggableWindow()
    : TitleBarHeight(30.0f), bIsMouseButtonDown(false)
{
    OnMouseMoveEvent.BindDynamic(this, &UDraggableWindow::OnMouseMove);
}

void UDraggableWindow::NativeConstruct()
{
    Super::NativeConstruct();

    if (UOverlaySlot* OverlaySlot = Cast<UOverlaySlot>(Slot))
    {
        OverlaySlot->SetVerticalAlignment(VAlign_Top);
    }
}

void UDraggableWindow::OnMouseDown(FGeometry MyGeometry, const FPointerEvent& MouseEvent)
{
    if (MouseEvent.GetScreenSpacePosition().Y - MyGeometry.AbsoluteToLocal(MouseEvent.GetScreenSpacePosition()).Y <= TitleBarHeight)
    {
        bIsMouseButtonDown = true;
        MouseButtonDownOffset = FVector2D(MyGeometry.AbsoluteToLocal(MouseEvent.GetScreenSpacePosition()));
        SetVisibility(ESlateVisibility::HitTestInvisible);
    }
}

void UDraggableWindow::OnMouseUp(FGeometry MyGeometry, const FPointerEvent& MouseEvent)
{
    bIsMouseButtonDown = false;
    SetVisibility(ESlateVisibility::Visible);
}

void UDraggableWindow::OnMouseMove(FGeometry MyGeometry, const FPointerEvent& MouseEvent)
{
    if (bIsMouseButtonDown)
    {
        FVector2D NewPosition = MyGeometry.AbsoluteToLocal(MouseEvent.GetScreenSpacePosition()) - MouseButtonDownOffset;

        if (UOverlaySlot* OverlaySlot = Cast<UOverlaySlot>(Slot))
        {
            OverlaySlot->SetPadding(FMargin(NewPosition.X, NewPosition.Y, 0, 0));
        }
    }
}
```

Since UE5 has adapted from UE4, most of the code will be compatible with UE5. However, you may need to adjust some aspects of the code to the latest API changes in UE5.2.

In your Blueprints, you can inherit this UDraggableWindow class for your windows, and they will have draggable behavior. Remember that the draggable area will be limited by the `TitleBarHeight` set in the class.

Here's a simple example of a draggable window base class with a `UserWidget` in Unreal Engine 4, which can be adapted to UE5:

```cpp
// DraggableWindow.h

#pragma once

#include "CoreMinimal.h"
#include "Blueprint/UserWidget.h"
