```cpp
// DraggableWindow.cpp

#include "DraggableWindow.h"

UDraggableWindow::UDraggableWindow()
    : TitleBarHeight(30.0f), bIsMouseButtonDown(false)
{
}

void UDraggableWindow::NativeConstruct()
{
    Super::NativeConstruct();
}

FReply UDraggableWindow::NativeOnMouseButtonDown(const FGeometry& InGeometry, const FPointerEvent& InMouseEvent)
{
    FVector2D MousePos = InGeometry.AbsoluteToLocal(InMouseEvent.GetScreenSpacePosition());

    if (MousePos.Y <= TitleBarHeight)
    {
        OnDragStart(MousePos.X, MousePos.Y);
        return FReply::Handled().CaptureMouse(SharedThis(this));
    }

    return FReply::Unhandled();
}

FReply UDraggableWindow::NativeOnMouseButtonUp(const FGeometry& InGeometry, const FPointerEvent& InMouseEvent)
{
    if (bIsMouseButtonDown)
    {
        OnDragStop();
        return FReply::Handled().ReleaseMouseCapture();
    }

    return FReply::Unhandled();
}

FReply UDraggableWindow::NativeOnMouseMove(const FGeometry& InGeometry, const FPointerEvent& InMouseEvent)
{
    if (bIsMouseButtonDown)
    {
        FVector2D CurrentMousePos = InGeometry.AbsoluteToLocal(InMouseEvent.GetScreenSpacePosition());
        FVector2D DragDelta = CurrentMousePos - MouseButtonDownOffset;

        SetRenderTranslation(DragDelta);
    }

    return FReply::Unhandled();
}

void UDraggableWindow::OnDragStart(float MouseX, float MouseY)
{
    bIsMouseButtonDown = true;
    MouseButtonDownOffset = FVector2D(MouseX, MouseY);
}

void UDraggableWindow::OnDragStop()
{
    bIsMouseButtonDown = false;
    MouseButtonDownOffset = FVector2D::ZeroVector;
}
```

