      `https://en.wikipedia.org/w/api.php?action=parse&page=${h1}&origin=*&format=json&formatversion=2`,
      {
        method: "GET",
      }
    );

    if (!response.ok) {
      throw new Error("Failed to fetch data from the API.");
    }

    const apiData = await response.json();
    const html = apiData.parse.text;

    const tempDiv = document.createElement("div");
    tempDiv.innerHTML = html;

    const listedData = tempDiv.querySelector("#conflicts10000");

    if (!listedData) {
      throw new Error("table data not found in the response.");
    }

    // Extract thead and tbody from the table
    const thead = listedData.querySelector('thead');
    const tbody = listedData.querySelector('tbody');

    // Get the table header keys
    const keys = Array.from(thead.querySelectorAll('th')).map(th => th.textContent.trim());

    // Prepare an empty array for storing the final data
    const data = [];

    // Loop through each row in tbody
    tbody.querySelectorAll('tr').forEach(tr => {
      // Get all the td elements in the row
      const tds = tr.querySelectorAll('td');

      // Create an object for the current row data
      const rowData = {};

      // Check if the number of cells matches the header keys
      if (tds.length === keys.length) {
        keys.forEach((key, index) => rowData[key] = tds[index].textContent.trim());
        data.push(rowData);
      }
    });

    // Return the final data
    console.log("data: ", data);
    return data;

  } catch (error) {
    console.log("Error occurred:", error);
    return null;
  }

}
```

