Here's a C++ code example that parses a vocabulary file containing words in the given formats and loads them into an array of strings. You can modify the `FILENAME` constant to the path of your vocabulary file.

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <regex>

const std::string FILENAME = "vocabulary.txt"; // Replace with your file path

int countWordsInFile() {
    std::ifstream inFile(FILENAME);
    if (!inFile) {
        std::cerr << "Error: cannot open the file." << std::endl;
        return 0;
    }

    int count = 0;
    std::string line;
    while (std::getline(inFile, line)) {
        count += std::count_if(line.begin(), line.end(), [](char c) { return c == ' ' || c == ','; }) + 1;
    }

    inFile.close();
    return count;
}

int main() {
    int wordCount = countWordsInFile();
    if (wordCount == 0) {
        return 1;
    }

    std::string *words = new std::string[wordCount];

    std::ifstream inFile(FILENAME);
    if (!inFile) {
        std::cerr << "Error: cannot open the file." << std::endl;
        return 1;
    }

    std::regex wordRegex(R"(\b\w+\b)");
    std::string line;
    int idx = 0;
    while (std::getline(inFile, line)) {
        auto words_begin = std::sregex_iterator(line.begin(), line.end(), wordRegex);
        auto words_end = std::sregex_iterator();
        for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
            std::smatch match = *i;
            words[idx] = match.str();
            ++idx;
        }
    }

    inFile.close();

    // print the words
    for (int i = 0; i < wordCount; ++i) {
        std::cout << words[i] << std::endl;
    }

    delete[] words;
    return 0;
}
```

