Here is a C++ code example to generate the text based on the given format and vocabulary:

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <ctime>
#include <cstdlib>
#include <string>
#include <sstream>

struct voc {
    std::string voc_name;
    std::vector<std::string> words;
};

std::vector<std::string> split(const std::string &s, char delimiter) {
    std::vector<std::string> tokens;
    std::string token;
    std::istringstream tokenStream(s);
    while (std::getline(tokenStream, token, delimiter)) {
        tokens.push_back(token);
    }
    return tokens;
}

int main() {
    std::ifstream inFile("vocabulary.txt");
    std::string format = "ALIVE %word_from_voc1% ALIVE %word_from_voc_2% %word_from_voc_3%";
    std::srand(static_cast<unsigned>(std::time(nullptr)));

    std::map<std::string, voc> vocabularies;

    if (inFile.is_open()) {
        std::string line;
        while (std::getline(inFile, line)) {
            std::vector<std::string> tokens = split(line, ' ');
            if (tokens.size() >= 2) {
                std::string vocName = tokens[0];
                tokens.erase(tokens.begin());
                vocabularies[vocName].voc_name = vocName;
                vocabularies[vocName].words = tokens;
            }
        }
    }
    inFile.close();

    std::istringstream formatStream(format);
    std::string output;
    std::string token;
    while (formatStream >> token) {
        if (token[0] == '%' && token[token.size()-1] == '%') {
            std::string vocName = token.substr(1, token.size()-2);
            if (vocabularies.count(vocName) > 0) {
                int randomIndex = std::rand() % vocabularies[vocName].words.size();
                output += vocabularies[vocName].words[randomIndex];
            } else {
                output += token;
            }
        } else if (token == "OR") {
            output = output.substr(0, output.size() - 1);
            int i;
            for (i = output.size() - 1; i >= 0 && output[i] != ' '; i--);
            std::string prevWord = output.substr(i + 1, output.size() - i - 1);
            std::string nextWord;
            formatStream >> nextWord;
            if (std::rand() % 2 == 1) {
                output = output.substr(0, i+1) + nextWord;
            } else {
                output += prevWord;
            }
        } else {
            output += token;
        }
        output += ' ';
    }

    output.erase(output.find_last_not_of(" \n\r\t")+1);

    std::cout << "Output: " << output << std::endl;

    return 0;
}
```

Replace the "vocabulary.txt" file name with your vocabulary file and ensure that the format variable contains the desired format.

This code assumes that the vocabulary file has the vocabulary identifier followed by a list of words separated by spaces for each line.

