const startScanning = async () => {
  scanning = true;
  codeReader = new ZXing.BrowserMultiFormatReader();

  try {
    const constraints = { video: { facingMode: "environment" } };
    await codeReader.decodeFromConstraints(constraints, videoElement, (result, error) => {
