```c
#include <stdio.h>

int main(void)
{
    int n, q;
    double sum = 0;

    printf("Enter the value of n: ");
    scanf("%d", &n);

    printf("Enter the value of q: ");
    scanf("%d", &q);

    for (int i = 1; i <= n; i++) {
        sum += (double)i / (i + q); // 计算每一项的值并累加到和 sum 中
    }

    printf("The value of the sum is %.6f\n", sum);
    return 0;
}
