```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

const User = require('../models/UserModel');
const router = express.Router();

router.post('/register', async (req, res) => {
  try {
    let newUser = new User(req.body);
    let savedUser = await newUser.save();
    res.json(savedUser);
  } catch (error) {
    res.status(400).json('Error: ' + error);
  }
});

router.post('/login', async (req, res) => {
  try {
    const user = await User.findOne({ $or: [{ email: req.body.usernameOrEmail }, { username: req.body.usernameOrEmail }] });
    if (!user) return res.status(400).json('Invalid email or username.');

    const validPassword = await bcrypt.compare(req.body.password, user.password);
    if (!validPassword) return res.status(400).json('Invalid password.');

    const token = jwt.sign({ _id: user._id }, process.env.JWT_SECRET || 'secret-key');
    res.header('auth-token', token).json(token);
  } catch (error) {
    res.status(400).json('Error: ' + error);
  }
});

router.get('/logout', (req, res) => {
  res.header('auth-token', '').json('Logged out.');
});

module.exports = router;
```

