```

Add the following code to the `Program.cs`:

```csharp
using System;
using Fleck;

class Program
{
    static void Main(string[] args)
    {
        FleckLog.Level = LogLevel.Info;
        var server = new WebSocketServer("ws://0.0.0.0:8181");
        server.Start(socket =>
        {
            socket.OnOpen = () => Console.WriteLine("Client connected");
            socket.OnClose = () => Console.WriteLine("Client disconnected");
            socket.OnMessage = async message =>
            {
                Console.WriteLine("Received message: " + message);
                if (message == "OpenBrowser")
                {
                    await socket.Send("GoToGoogle");
                }
            };
        });

        Console.ReadLine();
    }
}
```

### Client

Create a new C# console application and install the following package:

```bash
dotnet add package WebSocketSharp
```

Add the following code to the `Program.cs`:

```csharp
using System;
using PuppeteerSharp;
using WebSocketSharp;

class Program
{
    static void Main(string[] args)
    {
        var url = "ws://localhost:8181";
        using (var ws = new WebSocket(url))
        {
            ws.OnMessage += async (sender, e) =>
            {
                Console.WriteLine("Message received: " + e.Data);
                if (e.Data == "GoToGoogle")
                {
                    await RunPuppeteer();
                }
            };

            ws.Connect();

            ws.Send("OpenBrowser");

            Console.ReadKey(true);
        }
    }

    private static async Task RunPuppeteer()
    {
        await new BrowserFetcher().DownloadAsync(BrowserFetcher.DefaultRevision);
        using var browser = await Puppeteer.LaunchAsync(new LaunchOptions { Headless = false });
        using var page = await browser.NewPageAsync();
        await page.GoToAsync("https://www.google.com");

        // Send the response back to the server
        Console.WriteLine("Google opened");
    }
}
```

Now run the server, then run one or more client instances. Each client will open a new Puppeteer browser and go to google.com when it receives a message from the server.

To trigger an event once a week in FiveM, you can use a combination of a server-side script and a timer. Here's an example of how you can achieve this using JavaScript (Node.js):

1. Create a new server-side script file (e.g., `weekly_event.js`) in your FiveM resource.

2. Write the following code in your `weekly_event.js` file:

```javascript
let eventInterval;

// Function to trigger a weekly event
function triggerWeeklyEvent() {
    console.log('Triggering the weekly event...');

    // Trigger an event here. For example:
    emitNet('weeklyEventTriggered'); // Feel free to replace this with your desired event
}

// Function to set up the event timer
function setUpEventTimer() {
    clearInterval(eventInterval);

    // Set the time until the next event (interval in milliseconds)
    const currentDate = new Date();
    const nextEventDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), currentDate.getDate(), 23, 59, 59, 999); // Set time of next event
    const timeUntilNextEvent = nextEventDate.getTime() - currentDate.getTime();

    eventInterval = setTimeout(() => {
        triggerWeeklyEvent();
        setUpEventTimer();
    }, timeUntilNextEvent);
}

// Start the timer when the server starts
setUpEventTimer();
```

Replace the `23, 59, 59, 999` with the hours, minutes, seconds, and milliseconds when you want the weekly event to occur.

3. In your `fxmanifest.lua`, make sure to include the server-side script file you created:

```lua
fx_version 'cerulean'
game 'gta5'

-- Replace this with your existing information
author 'Your Name'
description 'Trigger Weekly Event Example'
version '1.0.0'

-- Add the following line to include the server-side script
server_script 'weekly_event.js'
```

4. Restart your FiveM server, and your specified event will now trigger once a week.

Ensure to adapt this example as necessary for your specific resource and event requirements.

To account for server restarts, you can store the last event trigger time in a file and read it upon server start. This way, you can determine when the next event should occur, regardless of any server restarts.

1. Modify your `weekly_event.js` file to include file reading and writing:

```javascript
const fs = require('fs');
const eventFile = 'lastEventTime.txt';

let eventInterval;

function triggerWeeklyEvent() {
    console.log('Triggering the weekly event...');
    emitNet('weeklyEventTriggered');
    saveLastEventTime();
}

function saveLastEventTime() {
    const now = new Date();
    fs.writeFile(eventFile, now.toISOString(), (err) => {
        if (err) {
            console.error('Error saving last event time:', err);
        } else {
            console.log('Last event time saved successfully');
        }
    });
}

function getLastEventTime() {
    if (!fs.existsSync(eventFile)) {
        return new Date(0); // Default to the earliest possible date
    }

    const fileContent = fs.readFileSync(eventFile, 'utf8');
    return new Date(fileContent);
}

function setUpEventTimer() {
    clearInterval(eventInterval);

    const currentDate = new Date();
    const lastEventTime = getLastEventTime();
    const timeSinceLastEvent = currentDate.getTime() - lastEventTime.getTime();
    const oneWeekInMs = 7 * 24 * 60 * 60 * 1000;

    if (timeSinceLastEvent >= oneWeekInMs) {
        triggerWeeklyEvent();
    }

    const nextEventDate = new Date(Math.ceil(currentDate.getTime() / oneWeekInMs) * oneWeekInMs);
    const timeUntilNextEvent = nextEventDate.getTime() - currentDate.getTime();

    eventInterval = setTimeout(() => {
        triggerWeeklyEvent();
        setUpEventTimer();
    }, timeUntilNextEvent);
}

setUpEventTimer();
```

This code will use the `lastEventTime.txt` file to store the last trigger time. When the server starts, it will read the file to calculate when the next event should occur, taking into account server restarts.

2. Ensure you have installed the `fs` package if you are using a custom Node.js server for your FiveM server. You can install it with the following command:

```
npm install fs
```

This update to the script will store the last event trigger time in a file, allowing the script to account for server restarts, even if they happen multiple times a day.

