									checker = true
									break
								}
							case "lower-than":
								conv, _ := strconv.ParseFloat(parValue["value"].(string), 64)
								if conv > convRaw {
									checker = true
									break
								}
							case "between":
								splitVal := strings.Split(parValue["value"].(string), "-")
								fConv, _ := strconv.ParseFloat(splitVal[0], 64)
								sConv, _ := strconv.ParseFloat(splitVal[1], 64)
								if fConv <= convRaw && sConv >= convRaw {
									checker = true
									break
								}
							}
						}
					}
				}
			}
		}

		if statusDataOld != statusDataNew {
			split[keyIndex] = "false"
		}
	}

	join := strings.Join(split, ",")
	userReadStatus = join
	return userReadStatus
}
