```javascript
function getLastNRegisteredMusicians(N) {
  return new Promise((resolve, reject) => {
    connection.query(
      'SELECT * FROM musicians ORDER BY id DESC LIMIT ?',
      [N],
      (error, results, fields) => {
        if (error) {
          reject(error);
        } else {
          resolve(results);
        }
      }
    );
  });
}

function getMusicianById(id) {
  return new Promise((resolve, reject) => {
    connection.query(
      'SELECT * FROM musicians WHERE id = ?',
      [id],
      (error, results, fields) => {
        if (error) {
          reject(error);
        } else {
          resolve(results[0]);
        }
      }
    );
  });
}

async function search(query = '', role = '', city = '', genre = '') {
  const wildcardQuery = `%${query}%`;
  const results = await new Promise((resolve, reject) => {
    connection.query(
      'SELECT * FROM musicians WHERE (name LIKE ? OR genre LIKE ?) AND (role = ? OR ? = "") AND (city = ? OR ? = "") AND (genre = ? OR ? = "")',
      [wildcardQuery, wildcardQuery, role, role, city, city, genre, genre],
      (error, results, fields) => {
        if (error) {
          reject(error);
        } else {
          resolve(results);
        }
      }
    );
  });

  return results.map(musician => {
    return {
      ...musician,
      profileLink: `/profile/${musician.id}`,
    };
  });
