```cpp
#pragma once

#include <functional>
#include <memory>
#include <iostream>

#include "EventBus.h"

template<typename... Events>
class EventSystem {
public:
    using EventBusPtr = std::shared_ptr<EventBus>;
    using EventQueueManagerPtr = std::shared_ptr<EventQueueManager>;
    using EventHandler = std::function<void(EventType&)>;

    EventSystem(EventBusPtr bus, EventQueueManagerPtr manager)
        : bus_(bus), manager_(manager) {}

    EventSystem()
        : bus_(std::make_shared<EventBus>()), manager_(std::make_shared<EventQueueManager>()) {}

    template<typename EventType>
    void Subscribe(EventHandler handler) {
        static_assert(IsSupportedEvent<EventType>(), "Event type not supported by this EventSystem.");
        bus_->Subscribe(handler);
    }

    template<typename EventType>
    void Publish(EventType event_data) {
        static_assert(IsSupportedEvent<EventType>(), "Event type not supported by this EventSystem.");
        bus_->Publish(event_data);
    }

    template<typename EventType>
    void ResolveEvent(EventType event_data) const {
        std::cout << event_data.entityId << " Entity-------------------" << std::endl;
        std::cout << "Position: ( " << *(event_data.x) << ", " << *(event_data.y) << ")" << std::endl;
        *(event_data.x) = 0;
        *(event_data.y) = 0;
    }

    void Update() const {
        (PullEvent<Events>(), ...);
    }

    template<typename EventType>
    void PullEvent() const {
        static_assert(IsSupportedEvent<EventType>(), "Event type not supported by this EventSystem.");
        auto test = manager_->Dequeue<EventType>();
    }

private:
    template<typename EventType>
    static constexpr bool IsSupportedEvent() {
        return (... || std::is_same_v<EventType, Events>);
    }

    EventQueueManagerPtr manager_;
    EventBusPtr bus_;
};
```

With this, we have simplified the class by using predefined types for shared pointers and handler functions. The class now uses `EventBusPtr`, `EventQueueManagerPtr`, and `EventHandler` for improved readability and maintenance.

