using System.Collections;
using System.Collections.Generic;
using UnityEngine;
public class AI : MonoBehaviour
{
[SerializeField] private AIStatsSO aiStats;
[SerializeField] private Transform BallPos;
[SerializeField] private Rigidbody2D _aiRigidbody;
[SerializeField] private Transform Bottom;
[SerializeField] private float MovRange;
[SerializeField] private Ball ballScript;
[SerializeField] private AIWalkingAnim AIWalkingAnim;
////////////////////////////////////////////////////////

private float distanceToBall;
private float jumpPower;
[SerializeField] private bool canHead;

private float hor_mov;
public float Hor_mov
{
    get { return hor_mov; }
    set { hor_mov = value; }
}

private void Start()
{
    MovRange = aiStats.MoveRange;
    jumpPower = aiStats.jumpPower;
    hor_mov = 0f;

}




private void FixedUpdate()
{
    // canHead değerini güncelle
    Jump();
    if (IsGrounded())
    {
        Move();
    }
}



private void Jump()
{
    canHead = ballScript.CanHead;
    if (IsGrounded() && canHead)
    {
        _aiRigidbody.velocity = Vector2.zero;
        _aiRigidbody.AddForce(new Vector2(0, jumpPower), ForceMode2D.Impulse);
    }
}

private void Move()
{
    distanceToBall = BallPos.position.x - transform.position.x; // Calculate horizontal distance to ball

    if (Mathf.Abs(distanceToBall) < MovRange)
    {
        hor_mov = Mathf.Sign(distanceToBall); // Set movement direction towards the ball
        AIWalkingAnim.AIWalkingAnimation();
    }
    else
    {
        // Gradually decrease hor_mov until it reaches 0
        float decelerationRate = aiStats.speed / MovRange;
        if (hor_mov > 0f)
            hor_mov -= decelerationRate * Time.deltaTime;
        else if (hor_mov < 0f)
            hor_mov += decelerationRate * Time.deltaTime;

        // Clamp hor_mov between -1 and +1
        hor_mov = Mathf.Clamp(hor_mov, -1f, +1f);

        if (Mathf.Approximately(hor_mov, 0))
            _aiRigidbody.velocity = new Vector2(_aiRigidbody.velocity.x * aiStats.decelerationMultiplier, _aiRigidbody.velocity.y);

    }

    _aiRigidbody.velocity = new Vector2(hor_mov * aiStats.speed, _aiRigidbody.velocity.y);
}


private bool IsGrounded()
{

    if (Physics2D.OverlapCircle(Bottom.position, 0.01f, LayerMask.GetMask("Ground")))
    {
        return true;
    }
    else
    {
        return false;
    }
}
}

