{
	uint32_t mvpBufferIndex = currentMvpBufferIndex;
	VkBuffer mvpBuffer = mvpBuffers[mvpBufferIndex];
	VkDeviceMemory& requestedMvpBufferMemory = mvpBufferMemory[mvpBufferIndex]; // Changed the variable name

	currentMvpBufferIndex = (currentMvpBufferIndex + 1) % kMvpBufferCount;

	return std::make_pair(mvpBuffer, requestedMvpBufferMemory);
}

