This issue is caused by the Cross-Origin Resource Sharing (CORS) policy. When you try to make a request from your Angular app to the backend, the browser blocks the request due to the missing 'Access-Control-Allow-Origin' header in the response.

To fix the issue, you need to enable CORS in your backend (getaway). Here's how you can do it:

1. If your backend is developed using Express.js:
First, install the 'cors' package by executing this command:
```bash
npm install cors
```

Then, add the following code to your `app.js` or `server.js` file:
```javascript
const cors = require('cors');
app.use(cors());
```

Now, restart your server, and the issue should be resolved.

2. If your backend is developed using Spring Boot:
Add the following code to your main application class or create a separate configuration class:

```java
import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.CorsRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

@Configuration
public class CorsConfig implements WebMvcConfigurer {

    @Override
    public void addCorsMappings(CorsRegistry registry) {
        registry.addMapping("/**")
                .allowedOrigins("*") // You can replace '*' with 'http://localhost:4200' for added security
                .allowedMethods("GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS")
                .allowedHeaders("*")
                .allowCredentials(true);
    }
}
```

After making these changes, restart your backend server, and the CORS error should be resolved.

It seems like you've already configured CORS for your Spring Boot backend using the application.yml file. However, if you still face the CORS issue, the configuration might not be applied correctly.

Try this alternative approach by creating a separate configuration class for CORS:

1. Create a new class called `CorsConfig.java` in your project.

2. Add the following code to `CorsConfig.java`:

```java
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
import org.springframework.web.filter.CorsFilter;

@Configuration
public class CorsConfig {

    @Bean
    public CorsFilter corsFilter() {
        CorsConfiguration corsConfiguration = new CorsConfiguration();
        corsConfiguration.setAllowCredentials(true);
        corsConfiguration.addAllowedOrigin("http://localhost:4200");
        corsConfiguration.addAllowedHeader("*");
        corsConfiguration.addAllowedMethod("GET");
        corsConfiguration.addAllowedMethod("POST");
        corsConfiguration.addAllowedMethod("PUT");
        corsConfiguration.addAllowedMethod("DELETE");
        corsConfiguration.addAllowedMethod("OPTIONS");

        UrlBasedCorsConfigurationSource urlBasedCorsConfigurationSource = new UrlBasedCorsConfigurationSource();
        urlBasedCorsConfigurationSource.registerCorsConfiguration("/**", corsConfiguration);

        return new CorsFilter(urlBasedCorsConfigurationSource);
    }
}
```

After adding this class, recompile and restart your backend server. This should resolve the CORS error.

If the issue still persists, please double-check that your backend server is running with the updated configuration and that your Angular app is making requests to the correct endpoint.

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

class Entity {
protected:
    int ID;
    int type;
    int x;
    int y;

public:
    Entity(int ID, int type, int x, int y) : ID(ID), type(type), x(x), y(y) {}

    int getType() const {
        return type;
    }

    int getX() const {
        return x;
    }

    int getY() const {
        return y;
    }

    void setX(int newX) {
        x = newX;
    }

    void setY(int newY) {
        y = newY;
    }

    virtual void move(vector<Entity*>& entities) = 0;

    virtual bool attack(vector<Entity*>& entities) {
        return false;
    }
};

class Soldier : public Entity {
private:
    int level;
    int range;

public:
    Soldier(int ID, int x, int y, int level, int range) : Entity(ID, 1, x, y), level(level), range(range) {}

    void move(vector<Entity*>& entities) override {
    }

    bool attack(vector<Entity*>& entities) override {
        int attacked = 0;

        for (Entity* e : entities) {
            if (e->getType() == 3) {
                int dist = abs(e->getX() - getX()) + abs(e->getY() - getY());

                if (dist <= range && attacked < level) {
                    attacked++;

                    Zombie* z = new Zombie(entities.size() + 1, getX(), getY(), 1);
                    entities.push_back(z);
                }
            }
        }

        return attacked > 0;
    }
};

class Civilian : public Entity {
private:
    int speed;
    int vision;

public:
    Civilian(int ID, int x, int y, int speed, int vision) : Entity(ID, 2, x, y), speed(speed), vision(vision) {}

    void move(vector<Entity*>& entities) override {
        int minDist = vision + 1;
        Entity* nearestZombie = nullptr;

        for (Entity* e : entities) {
            if (e->getType() == 3) {
                int dist = abs(e->getX() - getX()) + abs(e->getY() - getY());

                if (dist < minDist) {
                    minDist = dist;
                    nearestZombie = e;
                }
            }
        }

        if (nearestZombie != nullptr) {
            int dx = getX() - nearestZombie->getX();
            int dy = getY() - nearestZombie->getY();

            setX(getX() + dx * speed / minDist);
            setY(getY() + dy * speed / minDist);
        }
    }
};

class Zombie : public Entity {
private:
    int speed;

public:
    Zombie(int ID, int x, int y, int speed) : Entity(ID, 3, x, y), speed(speed) {}

    void move(vector<Entity*>& entities) override {
        int minDist = 2000;
        Entity* nearestTarget = nullptr;

        for (Entity* e : entities) {
            if (e->getType() != 3) {
                int dist = abs(e->getX() - getX()) + abs(e->getY() - getY());

                if (dist < minDist) {
                    minDist = dist;
                    nearestTarget = e;
                }
            }
        }

        if (nearestTarget != nullptr) {
            int dx = nearestTarget->getX() - getX();
            int dy = nearestTarget->getY() - getY();

            setX(getX() + dx * speed / minDist);
            setY(getY() + dy * speed / minDist);
        }
    }
};

int main() {
    int n, m;
    cin >> n >> m;

    vector<Entity*> entities;

    for (int i = 0; i < n; i++) {
        int ID, type, x, y;
        cin >> ID >> type >> x >> y;

        if (type == 1) {
            int level, range;
            cin >> level >> range;

            entities.push_back(new Soldier(ID, x, y, level, range));
        }
        else if (type == 2) {
            int speed, vision;
            cin >> speed >> vision;

            entities.push_back(new Civilian(ID, x, y, speed, vision));
        }
