let mic;

function preload() {
  image1 = loadImage('loudao.jpg');
  image2 = loadImage('fangjian4.jpg');
  image3 = loadImage('datu4.jpg');
  pingzi = loadImage('pingzi.png');
  image4 = loadImage('kaichuang.jpg');
  smashSound = loadSound('glass_smash.mp3');

  // 声音文件需要先加载
  soundFormats('mp3', 'ogg');
  smashSound = loadSound('assets/glass_smash.mp3');
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  mic = new p5.AudioIn();
  mic.start();
}

function draw() {
  // 画面按照索引值显示不同的图片
  if (currentImageIndex === 0) {
    background(0);
    imageMode(CENTER);
    image(image1, windowWidth / 2, windowHeight / 2);
    imageMode(CORNER);
  } else if (currentImageIndex === 1) {
    background(10, 24, 37);
    imageMode(CENTER);
    image(image2, windowWidth / 2, windowHeight / 2);
    imageMode(CORNER);
  } else if (currentImageIndex == 2) {
    background(10, 24, 37);
    imageMode(CENTER);
    image(image3, windowWidth / 2, windowHeight / 2);
    imageMode(CORNER);
  }

  if (currentImageIndex == 2 && falling) { 
    // image3是窗户
    imageMode(CENTER);
    if (broken == false) {
      // 绘制瓶子
      image(pingzi, px, py);
      py += acc * 0.1;
      acc++; // 加速度增加一定值

      // 如果瓶子坠落到窗户下部，播放声音并且标记为碎掉状态
      if (abs(py - windowHeight * 7 / 8) < 20) {
        smashSound.play();
        broken = true;
      }
    } else {
      // 碎掉的瓶子可以一直绘制在窗户下面
      image(pingzi, px, py);
    }
    imageMode(CORNER);
  }
}

function keyPressed() {
  if (key === 'd' || key === 'D') {
    // 切换索引值用来控制显示不同的图片
    currentImageIndex = (currentImageIndex + 1) % 3;

    // 重置瓶子状态
    if (broken) {
      falling = false;
      broken = false;
      px = oriPostionX;
      py = oriPostionY;
      acc = 0;
    }
  } else if (key === 'q' || key === 'Q') {
    // 按下“q”键开始让瓶子往下掉
    falling = true;
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function mouseClicked() {
  mic.getLevel(1, function(level) {
    console.log(level);
    // 当声音大于0.05时播放一个声音
    if (level > 0.05) {
      imageMode(CENTER);
      background(255);
      image(image4, windowWidth / 2, windowHeight / 2);
      imageMode(CORNER);
      smashSound.stop();
    }
  });
}
