// 向二叉排序树中添加节点
void add_node(Node **root, const char *word) {
    if (*root == NULL) {
        *root = (Node *)malloc(sizeof(Node));
        strcpy((*root)->word, word);
        (*root)->left = (*root)->right = NULL;
        return;
    }
    int cmp_res = strcmp(word, (*root)->word);
    if (cmp_res < 0) {
        add_node(&((*root)->left), word);
    } else if (cmp_res > 0) {
        add_node(&((*root)->right), word);
    }
}

// 判断两个单词是否只相差一个字符（插入、删除、替换）
int whether_diff(const char *word1,const char *word2) {
    int len1 = strlen(word1);
    int len2 = strlen(word2);
    int i=0,j=0;
    if (len1 + 1 == len2) { // 删除字符
        for (; i < len1 && j < len2; ) {
            if (word1[i]==word2[j]) {
                i++; j++;
            } else j++;
        }
        return i==len1;
    } else if (len1 == len2 + 1) { // 插入字符
        for (; i < len1 && j < len2; ) {
            if (word1[i]==word2[j]) {
                i++; j++;
            } else i++;
        }
        return j==len2;
    } else if (len1 == len2) { // 替换字符
        int diff_count = 0;
        for (; i < len1; i++) {
            if (word1[i]!=word2[i]) {
                diff_count++;
            }
        }
        return diff_count==1;
    } else {
        return 0;
    }
}

// 中序遍历字典二叉排序树，输出建议修改单词
void traverse_post_order(Node *root) {
    if (root == NULL) return;
    traverse_post_order(root->left);
    if (whether_diff(root->word, query[query_size-1].word)) {
        printf(" %s", root->word);
    }
    traverse_post_order(root->right);
}

// 在二叉排序树中查找单词
int find_word_in_dict(Node *root, const char *word) {
    if (root == NULL) {
        return -1;
    }
    int cmp_res = strcmp(word, root->word);
    if (cmp_res < 0) {
        return find_word_in_dict(root->left, word);
    } else if (cmp_res > 0) {
        return find_word_in_dict(root->right, word);
    } else {
        return 1;
    }
}

