        printf("Failed to set size for shared memory!\n");
        return NULL;
    }

    // get pointer to shared memory
    void* ptr = mmap(NULL, sizeof(chunk_t), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (ptr == MAP_FAILED) {
        printf("Failed to map shared memory!\n");
        return NULL;
    }

    // initialize chunk in shared memory
    chunk_t* chunk = (chunk_t*)ptr;
    memset(chunk, 0, sizeof(chunk_t));
    chunk->size = CHUNK_SIZE;

    return chunk;
}

