        // add reference count to shared chunk
        chunk->ref_count++;
        printf("Child process: Chunk reference count: %d\n", chunk->ref_count);

        // wait for parent process to terminate
        sleep(5);

        // remove shared memory
        munmap(chunk->vaddr, chunk->size);
        munmap(chunk, sizeof(chunk_t));
    } else { // parent process
        // map shared memory into virtual address space
        chunk_t* chunk = (chunk_t*)mmap(NULL, sizeof(chunk_t), PROT_READ | PROT_WRITE, MAP_SHARED, shm_open(SHM_NAME, O_RDWR, 0666), 0);
        if (chunk == MAP_FAILED) {
            printf("Failed to map shared memory into parent process!\n");
            return -1;
        }

        printf("Parent process: Chunk created at address 0x%08X with size %d bytes\n", chunk->addr, chunk->size);
        printf("Parent process: Chunk mapped to virtual address 0x%08X\n", chunk->vaddr);

        // add reference count to shared chunk
        chunk->ref_count++;
        printf("Parent process: Chunk reference count: %d\n", chunk->ref_count);

        // wait for child process to terminate
        int status;
        wait(&status);

        // remove shared memory
        munmap(chunk->vaddr, chunk->size);
        munmap(chunk, sizeof(chunk_t));
        shm_unlink(SHM_NAME);
