  const sportWatch = watch('sport');
  const competitionsWatch = watch('competitions');
  const toDateWatch = watch('toDate');
  const fromDateWatch = watch('fromDate');

  React.useEffect(() => {
    if (typeof eventDateWatch !== 'undefined' && eventDateWatch) {
      const { fromDate, toDate } = getDatesFromRange(
        new Date(Date.now()),
