                    disabled={disableEventStatus}
                    name={name}
                    className="event-search-form__blocked-checkbox"
                    data-testid="event-search-form-blocked-checkbox"
                    color="primary"
                    onChange={(event) => {
                      onChange(event.target.checked);
                    }}
                  />
                  <p className="event-search-form__blocked-label">
                    {t('form.blockedLabel')}
                  </p>
                </div>
              </>
            )}
          />
        ) : (
          <>
            <Label testId="event-status-label" label={t('form.eventStatus')} />
            <FormGroup>
              {checkBoxes.map(({ labelName, formName }, index) => (
                <FormControlLabel
                  label={t(`form.${labelName}`)}
                  key={labelName}
                  control={
                    <Controller
                      name={formName}
                      control={control}
                      defaultValue={!!selectedSearchValues[formName]}
                      render={({ onChange, value }) => (
                        <Checkbox
                          checked={!!value}
                          name={formName}
                          className="event-search-form__event-status-checkbox"
                          data-testid={
                            index === 0
                              ? 'event-search-form-blocked-checkbox'
                              : undefined
                          }
                          color="primary"
                          onChange={(event) => onChange(event.target.checked)}
                        />
                      )}
                    />
                  }
                />
              ))}
            </FormGroup>
          </>
        )}
