    .region_name = REGION_NAME,
    .len = CHUNK_SIZE,
    .align = chunk_align,
};

// initialize SMR
ot_s32 ret = ot_smr_init(&smr_attr);
if (ret != 0) {
    printf(“SMR init error[%d]!\n”, ret);
    return -1;
}

// allocate memory for chunk
chunk_t chunk;
chunk.size = CHUNK_SIZE;

alloc_attr.len = CHUNK_SIZE;
alloc_attr.region_name = REGION_NAME;
alloc_attr.align = chunk_align;
ret = ot_smr_alloc(&alloc_attr, (phys_addr*)&chunk.addr);
if (ret != 0) {
    printf(“SMR alloc error[%d]!\n”, ret);
    ot_smr_deinit();
    return -1;
}

printf(“Chunk allocated at physical address 0x%08X with size %d bytes\n”, chunk.addr, chunk.size);
```

首先定义了 SMR 区域和 SMR 属性，然后初始化 SMR。接着使用 `ot_smr_alloc()` 分配一块内存，将其物理地址存储在 `chunk.addr` 中。若分配失败，则释放 SMR 并退出。

5. 创建子进程：

```c
pid_t child_pid = fork();
