}
```

使用 `fork()` 创建一个子进程。若创建失败，则释放内存块，释放 SMR 并退出。

6. 在子进程和父进程之间通信：

```c
if (child_pid == 0) { // child process
    // receive physical address from parent process
    uint8_t* phys_addr;
    read(STDIN_FILENO, &phys_addr, sizeof(phys_addr));

    // map physical address to virtual address
    void* vaddr = mmap(NULL, CHUNK_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fileno(stdin), 0);
    if (vaddr == MAP_FAILED) {
        printf(“Failed to map physical address to virtual address!\n”);
        return -1;
    }

    printf(“Child process: Chunk mapped to virtual address 0x%08X\n”, vaddr);

    // add reference count to chunk
    ret = ot_smr_add_ref(vaddr);
    if (ret != 0) {
        printf(“SMR add reference error[%d]!\n”, ret);
        return -1;
    }

    // wait for parent process to terminate
    sleep(5);

    // remove chunk
    munmap(vaddr, CHUNK_SIZE);
} else { // parent process
    // map physical address to virtual address
    void* vaddr = mmap(NULL, CHUNK_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fileno(stdin), 0);
    if (vaddr == MAP_FAILED) {
        printf(“Failed to map physical address to virtual address!\n”);
        return -1;
    }

    printf(“Parent process: Chunk mapped to virtual address 0x%08X\n”, vaddr);

    // add reference count to chunk
    ret = ot_smr_add_ref(vaddr);
    if (ret != 0) {
        printf(“SMR add reference error[%d]!\n”, ret);
        munmap(vaddr, CHUNK_SIZE);
        ot_smr_munmap(chunk.addr, CHUNK_SIZE);
        ot_smr_deinit();
        return -1;
    }

    // send physical address to child process
    write(STDOUT_FILENO, &chunk.addr, sizeof(chunk.addr));

    // wait for child process to terminate
    int status;
    wait(&status);

    // remove chunk
    munmap(vaddr, CHUNK_SIZE);
    ot_smr_munmap(chunk.addr, CHUNK_SIZE);
    ot_smr_deinit();
}
```

