    function countResponses($conn, $dateStart, $dateEnd, $quality) {
        $sql = "SELECT COUNT(*) as count, $quality FROM responses WHERE date_time BETWEEN '$dateStart' AND '$dateEnd' GROUP BY $quality";
        $result = mysqli_query($conn, $sql);

        $counts = array();
        if (mysqli_num_rows($result) > 0) {
            while($row = mysqli_fetch_assoc($result)) {
                $counts[$row[$quality]] = $row['count'];
            }
        }

        return $counts;
