package serverUtils;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.HashMap;
import java.util.Iterator;

class ConnectionContext {
    enum FileTransferStep {
        NAME_LENGTH,
        FILE_NAME,
        FILE_LENGTH,
        FILE_CONTENT,
        SEPARATOR
    }

    String fileName;
    FileTransferStep currentStep;
    ByteBuffer buffer;
    FileOutputStream fileOutputStream;

    public ConnectionContext() {
        currentStep = FileTransferStep.NAME_LENGTH;
        buffer = ByteBuffer.allocate(1024 * 1024);
    }
}

public class ConnectionManager {
    private static final String ACK_MESSAGE_PREFIX = "<%s>Ack";
    private static final int NAME_LENGTH_SIZE = 4;
    private static final int CONTENT_LENGTH_SIZE = 4;
    private static final long SEPARATOR = 0;

    ServerSocketChannel serverSocketChannel;
    int port;

    public ConnectionManager(int port) {
        this.port = port;
    }

    public void initialize() throws IOException {
        serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.socket().bind(new InetSocketAddress(port));
        serverSocketChannel.configureBlocking(false);
        System.out.println("Server started on port " + port);
        System.out.println("============ * ============");
    }

    public void registerSelector(Selector selector) throws ClosedChannelException {
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);
    }

    public void processQuery(Selector selector, SelectionKey key) throws IOException {
        if (!key.isValid()) {
            return;
        }
        if (key.isAcceptable()) {
            acceptConnection(key, selector);
        } else if (key.isReadable()) {
            handleRead(key);
        }
    }

    private void acceptConnection(SelectionKey key, Selector selector) throws IOException {
        ServerSocketChannel serverSocketChannel = (ServerSocketChannel) key.channel();
        SocketChannel clientSocketChannel = serverSocketChannel.accept();
        clientSocketChannel.configureBlocking(false);
        clientSocketChannel.register(selector, SelectionKey.OP_READ, new ConnectionContext());

        System.out.println("Accepted connection from " + clientSocketChannel.getRemoteAddress());
    }

    private void handleRead(SelectionKey key) throws IOException {
        SocketChannel clientSocketChannel = (SocketChannel) key.channel();
        ConnectionContext context = (ConnectionContext) key.attachment();
        ByteBuffer buffer = context.buffer;
        int bytesRead;

        try {
            bytesRead = clientSocketChannel.read(buffer);
        } catch (IOException e) {
            System.out.println("Error reading data, closing connection");
            clientSocketChannel.close();
            return;
        }

        if (bytesRead == -1) {
            System.out.println("Closed connection with " + clientSocketChannel.getRemoteAddress());
            clientSocketChannel.close();
            key.cancel();
            System.out.println("============ * ============");
            return;
        }

        buffer.flip();

        while (buffer.hasRemaining()) {
            switch (context.currentStep) {
                case NAME_LENGTH:
                    if (buffer.remaining() >= NAME_LENGTH_SIZE) {
                        int nameLength = buffer.getInt();
                        context.buffer = ByteBuffer.allocate(nameLength);
                        context.currentStep = ConnectionContext.FileTransferStep.FILE_NAME;
                    } else {
                        buffer.compact();
                        return;
                    }
                    break;

                case FILE_NAME:
                    int fileNameBytesToRead = Math.min(buffer.remaining(), context.buffer.remaining());
                    buffer.get(context.buffer.array(), context.buffer.position(), fileNameBytesToRead);
                    context.buffer.position(context.buffer.position() + fileNameBytesToRead);

                    if (!context.buffer.hasRemaining()) {
                        context.fileName = new String(context.buffer.array(), StandardCharsets.UTF_8);
                        context.buffer = ByteBuffer.allocate(CONTENT_LENGTH_SIZE);
                        context.currentStep = FileTransferStep.FILE_LENGTH;
                    }
                    break;

                case FILE_LENGTH:
                    if (buffer.remaining() >= CONTENT_LENGTH_SIZE) {
                        int fileLength = buffer.getInt();
                        context.fileOutputStream = new FileOutputStream("files\\" + context.fileName);
                        context.buffer = ByteBuffer.allocateDirect(Math.min(fileLength, 8192));
                        context.currentStep = ConnectionContext.FileTransferStep.FILE_CONTENT;
                    } else {
                        buffer.compact();
                        return;
                    }
                    break;

                case FILE_CONTENT:
                    int contentBytesToRead = Math.min(buffer.remaining(), context.buffer.remaining());
                    buffer.get(context.buffer.array(), context.buffer.position(), contentBytesToRead);
                    context.buffer.position(context.buffer.position() + contentBytesToRead);

                    if (!context.buffer.hasRemaining()) {
                        context.fileOutputStream.write(context.buffer.array());
                        context.buffer.clear();
                        context.currentStep = ConnectionContext.FileTransferStep.SEPARATOR;
                    }
                    break;

                case SEPARATOR:
                    if (buffer.remaining() >= Long.BYTES) {
                        long separator = buffer.getLong();
                        if (separator != SEPARATOR) {
                            throw new RuntimeException("Invalid separator");
                        }
                        context.fileOutputStream.close();
                        sendAck(clientSocketChannel, context.fileName);
                        context.currentStep = ConnectionContext.FileTransferStep.NAME_LENGTH;
                        context.buffer = ByteBuffer.allocate(NAME_LENGTH_SIZE);
                    } else {
                        buffer.compact();
                        return;
                    }
                    break;
            }
        }

        buffer.compact();
    }

    private void sendAck(SocketChannel clientSocketChannel, String fileName) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(1024 * 1024);
        String ackMessage = String.format(ACK_MESSAGE_PREFIX, fileName);
        byte[] ackMessageBytes = ackMessage.getBytes(StandardCharsets.UTF_8);

        buffer.putInt(ackMessageBytes.length);
        buffer.put(ackMessageBytes);
        buffer.flip();

        while (buffer.hasRemaining()) {
            clientSocketChannel.write(buffer);
        }

        System.out.println("Sent acknowledgement for " + fileName);
    }
}
