```java
public class Connection {
    private String fileName;
    private ByteBuffer buffer;
    private SocketChannel socketChannel;

    public Connection(String fileName, ByteBuffer buffer, SocketChannel socketChannel) {
        this.fileName = fileName;
        this.buffer = buffer;
        this.socketChannel = socketChannel;
    }

    public String getFileName() {
        return fileName;
    }

    public ByteBuffer getBuffer() {
        return buffer;
    }

    public SocketChannel getSocketChannel() {
        return socketChannel;
    }
}

public class ConnectionManager {
    private final Selector selector;
    private final ServerSocketChannel serverChannel;
    private final Map<SelectionKey, Connection> connections = new ConcurrentHashMap<>();
    private static final int BUFFER_SIZE = 1024 * 1024;

    public ConnectionManager(int port) throws IOException {
        selector = Selector.open();
        serverChannel = ServerSocketChannel.open();
        serverChannel.socket().bind(new InetSocketAddress(port));
        serverChannel.configureBlocking(false);
        serverChannel.register(selector, SelectionKey.OP_ACCEPT);
        System.out.println("Server started on port " + port);
        System.out.println("============ * ============");
    }

    public void start() throws IOException {
        while (true) {
            int keyCount = selector.select();
            if (keyCount == 0) {
                continue;
            }
            Set<SelectionKey> keys = selector.selectedKeys();
            Iterator<SelectionKey> iterator = keys.iterator();
            while (iterator.hasNext()) {
                SelectionKey key = iterator.next();
                iterator.remove();
                try {
                    if (!key.isValid()) {
                        continue;
                    }
                    if (key.isAcceptable()) {
                        handleAccept(key);
                    } else if (key.isWritable()) {
                        handleWrite(key);
                    } else if (key.isReadable()) {
                        handleRead(key);
                    }
                } catch (IOException e) {
                    System.err.println("Error processing key: " + e.getMessage());
                    key.cancel();
                }
            }
        }
    }

    private void handleAccept(SelectionKey key) throws IOException {
        ServerSocketChannel serverSocketChannel = (ServerSocketChannel) key.channel();
        SocketChannel clientChannel = serverSocketChannel.accept();
        clientChannel.configureBlocking(false);
        clientChannel.register(selector, SelectionKey.OP_READ);
    }

    private void handleRead(SelectionKey key) throws IOException {
        SocketChannel clientChannel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(BUFFER_SIZE);
        int bytesRead = clientChannel.read(buffer);
        if (bytesRead == -1) {
            key.cancel();
            clientChannel.close();
            return;
        }
        Connection connection = connections.get(key);
        if (connection == null) {
            // новый контекст для нового соединения
            buffer.flip();
            int nameLength = buffer.getInt();
            byte[] nameBytes = new byte[nameLength];
            buffer.get(nameBytes);
            String fileName = new String(nameBytes, StandardCharsets.UTF_8);
            int fileLength = buffer.getInt();
            ByteBuffer fileBuffer = ByteBuffer.allocate(fileLength);
            int remaining = buffer.remaining();
            if (remaining > 0) {
                fileBuffer.put(buffer.array(), buffer.position(), remaining);
            }
            connections.put(key, new Connection(fileName, fileBuffer, clientChannel));
            if (fileBuffer.remaining() == 0) {
                // отправить подтверждение, если файл полностью получен
                selectionKey.interestOps(SelectionKey.OP_WRITE);
            }
        } else {
            // продолжить получение файла
            connection.getBuffer().put(buffer);
            if (!buffer.hasRemaining()) {
                // отправить подтверждение, если файл полностью получен
                key.interestOps(SelectionKey.OP_WRITE);
            }
        }
    }

    private void handleWrite(SelectionKey key) throws IOException {
        Connection connection = connections.get(key);
        String fileName = connection.getFileName();
        ByteBuffer ackBuffer = StandardCharsets.UTF_8.encode(String.format("<%s>Ack", fileName));
        ackBuffer.rewind();
        connection.getSocketChannel().write(ackBuffer);
        connection.getSocketChannel().close();
        key.cancel(); // закрыть соединение
        connections.remove(key); // удалить контекст соединения
    }
}
