    private ByteBuffer buffer;
    private ConnectionState state;

    public ConnectionContext() {
        buffer = ByteBuffer.allocate(ConnectionManager.BUFFER_SIZE);
        state = ConnectionState.FILE_NAME_LENGTH;
    }

    public enum ConnectionState {
        FILE_NAME_LENGTH,
        FILE_NAME,
        FILE_LENGTH,
        FILE_CONTENT,
