И в методе `handleRead` обрабатываем запись файла по частям:

```java
private void handleRead(SelectionKey key) throws IOException {
    SocketChannel clientSocketChannel = (SocketChannel) key.channel();
    ConnectionContext context = (ConnectionContext) key.attachment();
    ByteBuffer buffer = context.getBuffer();

    int bytesRead = clientSocketChannel.read(buffer);
    if (bytesRead < 0) {
        System.out.println("Closed connection with " + clientSocketChannel.getRemoteAddress());
        clientSocketChannel.close();
        key.cancel();
        System.out.println("============ * ============");
        return;
    }

    buffer.flip();

    while (buffer.hasRemaining()) {
        switch (context.getState()) {
            // ... предыдущие состояния

            case FILE_CONTENT:
                File file = new File("files\\" + context.getFileName());
                context.setFileOutputStream(new FileOutputStream(file));
                context.setState(ConnectionState.FILE_BATCH_CONTENT);
                context.setRemainingFileBytes(context.getFileLength());
                // не использовать здесь 'break' - перейдем к следующему состоянию

            case FILE_BATCH_CONTENT:
                int batchSize = Math.min(buffer.remaining(), context.getRemainingFileBytes());
                if (batchSize > 0) {
                    byte[] batch = new byte[batchSize];
                    buffer.get(batch);
                    context.getFileOutputStream().write(batch);
                    context.setRemainingFileBytes(context.getRemainingFileBytes() - batchSize);
                }

                if (context.getRemainingFileBytes() == 0) {
                    context.getFileOutputStream().close();
                    context.setState(ConnectionState.SEPARATOR);
                } else {
                    buffer.compact();
                    return;
                }
                break;

            // ... последующие состояния
}
}
