                char byte_neighbor = temp[index_neighbor];
                shifted_byte |= (byte_neighbor << (8 - bitShift));
            }
        }

        buff[i] = shifted_byte;
    }

    writeToFile(ctx->tempFile, buff);
    free(temp);
