  openOrders: {},
  filledCanceledId: [],
};

export const openOrdersSlice = createSlice({
  name: "openOrdersSlice",
  initialState,
  reducers: {
    setOpenOrders: (state, action: PayloadAction<Record<string, AccountOpenOrder>>) => {
      state.openOrders = action.payload;
    },
    addFilledCanceledId: (state, action: PayloadAction<string>) => {
      const orderId = action.payload;
      state.filledCanceledId.push(orderId);
