      const orderId = action.payload;
      delete state.openOrders[orderId];
    },
  },
  extraReducers: {
    [HYDRATE]: (state, action) => {
      return {
        ...state,
        ...action.payload,
      };
    },
  },
});

export const {
  setOpenOrders,
  addFilledCanceledId,
  deleteOrderById,
} = openOrdersSlice.actions;

export default openOrdersSlice.reducer;


