Yes, you can utilize Yup validation inside the resolver for the react-hook-form while using the `yupResolver`. To avoid the `disabled` attribute logic, you can update the Yup validation schema and include necessary custom validations.

Here's an example of how you can update Yup validation for `fromDate` and `toDate`:

```javascript
import * as Yup from 'yup';

Yup.addMethod(Yup.date, 'minDate', function(min, message) {
  return this.test('minDate', message, function(value) {
    return isValid(value) && !isBefore(value, new Date(min));
  });
});

Yup.addMethod(Yup.date, 'maxDate', function(max, message) {
  return this.test('maxDate', message, function(value) {
    return isValid(value) && !isAfter(value, new Date(max));
  });
});

Yup.addMethod(Yup.date, 'isBeforeDate', function(name, message) {
  return this.test('isBeforeDate', message, function(value) {
    const toDate = this.resolve(Yup.ref(name));
    return toDate && value && !isBefore(value, toDate);
  });
});

Yup.addMethod(Yup.date, 'isAfterDate', function(name, message) {
  return this.test('isAfterDate', message, function(value) {
    const fromDate = this.resolve(Yup.ref(name));
    return fromDate && value && !isAfter(value, fromDate);
  });
});

