```java
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.TopicPartition;

import java.util.*;

public class KafkaConsumerExample {

    public static void main(String[] args) {
        // Create properties for Kafka consumer
        Properties props = new Properties();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("group.id", "test-group");
        props.put("enable.auto.commit", "false");
        props.put("auto.offset.reset", "earliest");
        props.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        props.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");

        // Create Kafka consumer
        KafkaConsumer<String, String> consumer = new KafkaConsumer<>(props);

        // Assign initial topics to consumer
        List<String> topics = Arrays.asList("topic1", "topic2");
        consumer.subscribe(topics);

        try {
            while (true) {
                // Poll for new messages
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
                for (ConsumerRecord<String, String> record : records) {
                    System.out.printf("Topic: %s, Partition: %d, Offset: %d, Key: %s, Value: %s%n",
                            record.topic(), record.partition(), record.offset(), record.key(), record.value());
                }

                // Check if there are any messages left to process in the previous assigned topics
                if (records.isEmpty()) {
                    // Assign new topic to consumer
                    TopicPartition newTopicPartition = new TopicPartition("topic3", 0);
                    Set<TopicPartition> topicPartitionSet = new HashSet<>();
                    topicPartitionSet.add(newTopicPartition);
                    consumer.assign(topicPartitionSet);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            consumer.close();
        }
    }
}
```

In this example, we first create a Kafka consumer and subscribe it to two topics - "topic1" and "topic2". We then enter into an infinite loop where we continuously poll for new messages using the `poll()` method. After processing all the messages in the current assigned topics, we check if there are any messages left to process. If there are no more messages, we assign a new topic to the consumer using the `assign()` method. In this case, we assign "topic3" with a single partition 0 to the consumer.

It's important to note that assigning a new topic will result in the loss of any unprocessed messages from the previous assigned topics, so it's important to do this only when necessary.

