        if (cellValue === "") {
          e.source.getActiveSheet().getRange(timestampCol.cell).setValue(currentDate);
          const dayOfWeek = getDayOfWeek(currentDate);
          e.source.getActiveSheet().getRange(timestampCol.cell).setNote(dayOfWeek);
