        if (buffer.remaining() < Integer.BYTES) {
            buffer.compact();
            return;
        }
        int nameLength = buffer.getInt();
        connectionContext.nameBuffer = ByteBuffer.allocate(nameLength);
    }

    // Читаем имя файла
    if (connectionContext.fileName == null) {
        if (buffer.remaining() < connectionContext.nameBuffer.remaining()) {
            connectionContext.nameBuffer.put(buffer);
            buffer.compact();
            return;
        }
        connectionContext.nameBuffer.put(buffer.array(), buffer.position(), connectionContext.nameBuffer.remaining());
        buffer.position(buffer.position() + connectionContext.nameBuffer.remaining());
        connectionContext.fileName = new String(connectionContext.nameBuffer.array(), StandardCharsets.UTF_8);
    }

    // Читаем размер файла
    if (connectionContext.fileLength < 0) {
        if (buffer.remaining() < Long.BYTES) {
            buffer.compact();
            return;
        }
        connectionContext.fileLength = buffer.getLong();
        connectionContext.fileBuffer = ByteBuffer.allocate((int) connectionContext.fileLength);
    }

    // Читаем содержимое файла и сохраняем его
    if (buffer.remaining() >= connectionContext.fileBuffer.remaining()) {
        connectionContext.fileBuffer.put(buffer.array(), buffer.position(), connectionContext.fileBuffer.remaining());
        buffer.position(buffer.position() + connectionContext.fileBuffer.remaining());
    } else {
        connectionContext.fileBuffer.put(buffer);
        buffer.compact();
        return;
    }

    saveFile(connectionContext.fileName, connectionContext.fileBuffer.array());
    sendAck(clientSocketChannel, connectionContext.fileName);

    // Обнуляем контекст для следующей передачи файла
    connectionContext.reset();

    // Если есть еще данные в буфере, продолжаем обработку
    if (buffer.remaining() > 0) {
        handleRead(key);
    } else {
        buffer.compact();
    }
