4. Create a function that loads the JSON file into a RapidJSON `Document` instance:

```cpp
rapidjson::Document load_json(const std::string &filename) {
    using namespace rapidjson;
    FILE *file = std::fopen(filename.c_str(), "r");

    char buffer[65536];
    FileReadStream is(file, buffer, sizeof(buffer));
    Document document;
    document.ParseStream(is);
    fclose(file);

    return document;
}
```
5. Create a `load_scene` function that iterates through component names for each object:

```cpp
void load_scene(const std::string &filename) {
    using namespace rapidjson;

    auto document = load_json(filename);
    assert(document.IsObject());

    assert(document.HasMember("objects"));
    const auto &objects = document["objects"];
    assert(objects.IsArray());

    for (SizeType i = 0; i < objects.Size(); i++) {
        const auto &object = objects[i];
        int objectId = object["id"].GetInt(); // Assuming each object has a unique "id"

        // Iterate through all possible component types
