In this case, you must create a generic function to load component data from the JSON values according to the component type. You can use template specialization and create a load function for each specific type of component you have. Then, you can adjust the `load_scene` function to use these new load functions when loading the components.

First, let's create a template function `load_component_data` and specialize it for each component type:

```cpp
#include <stdexcept>

template <class C>
void load_component_data(const rapidjson::Value &componentData, unsigned char *data);

template <>
void load_component_data<Position>(const rapidjson::Value &componentData, unsigned char *data) {
    Position *positionComponent = std::launder(reinterpret_cast<Position *>(data));
    if (componentData.HasMember("x") && componentData["x"].IsFloat() &&
        componentData.HasMember("y") && componentData["y"].IsFloat()) {
        positionComponent->x = componentData["x"].GetFloat();
        positionComponent->y = componentData["y"].GetFloat();
    } else {
        throw std::runtime_error("Invalid component data for Position");
    }
}

template <>
void load_component_data<Name>(const rapidjson::Value &componentData, unsigned char *data) {
    Name *nameComponent = std::launder(reinterpret_cast<Name *>(data));
    if (componentData.HasMember("name") && componentData["name"].IsString()) {
        nameComponent->name = componentData["name"].GetString();
    } else {
        throw std::runtime_error("Invalid component data for Name");
    }
}

template <>
void load_component_data<Size>(const rapidjson::Value &componentData, unsigned char *data) {
    Size *sizeComponent = std::launder(reinterpret_cast<Size *>(data));
    if (componentData.HasMember("width") && componentData["width"].IsInt() &&
        componentData.HasMember("height") && componentData["height"].IsInt()) {
        sizeComponent->width = componentData["width"].GetInt();
        sizeComponent->height = componentData["height"].GetInt();
    } else {
        throw std::runtime_error("Invalid component data for Size");
    }
}

template <>
void load_component_data<Velocity>(const rapidjson::Value &componentData, unsigned char *data) {
    Velocity *velocityComponent = std::launder(reinterpret_cast<Velocity *>(data));
    if (componentData.HasMember("vel") && componentData["vel"].IsInt()) {
        velocityComponent->vel = componentData["vel"].GetInt();
    } else {
        throw std::runtime_error("Invalid component data for Velocity");
    }
}
```

Now, modify the `load_scene` function to use these new functions for loading components.

```cpp
void load_scene_object(const rapidjson::Value &object) {
    using namespace rapidjson;

    int objectId = object["id"].GetInt(); // Assuming each object has a unique "id"

    // A mapping between your component names and component types
    const std::map<std::string, std::size_t> allComponentTypes = {
        {"Position", GetTypeID<Position>()},
        {"Name", GetTypeID<Name>()},
        {"Size", GetTypeID<Size>()},
        {"Velocity", GetTypeID<Velocity>()},
    };

    // Iterate through all possible component types
    for (const auto &[componentName, componentType] : allComponentTypes) {
        if (object.HasMember(componentName.c_str())) {
            const auto &componentData = object[componentName.c_str()];
            unsigned char data[1024]; // Allocate enough buffer space for component data

            // Depending on the component type, call the appropriate load_component_data function
            switch (componentType) {
                case GetTypeID<Position>():
                    load_component_data<Position>(componentData, data);
                    break;
                case GetTypeID<Name>():
                    load_component_data<Name>(componentData, data);
                    break;
                case GetTypeID<Size>():
                    load_component_data<Size>(componentData, data);
