// typeIdGenerator takes code of componentBaseClass
template <class TBase>
class TypeIdGenerator
{
public:
    template <class TDerived>
    static std::size_t GetNewID()
    {
        static const std::size_t id = m_nextId++;

        return id;
    }

private:
    static std::size_t m_nextId;
};

template <class TBase>
std::size_t TypeIdGenerator<TBase>::m_nextId = 0;

// Continue with the ComponentBase, Component, Position, Name, Size and Velocity definitions

class Factory
{
public:
    template <class C>
    void RegisterComponent()
    {
        size_t typeId = GetTypeID<C>();
        m_componentFactories[typeId] = std::make_shared<Component<C>>();
    }

    template <class C>
    std::shared_ptr<ComponentBase> GetComponentFactory()
    {
        size_t typeId = GetTypeID<C>();
        return m_componentFactories[typeId];
    }

    std::unique_ptr<ComponentBase> CreateComponentFromJson(const std::string& componentName, const rapidjson::Value& json)
    {
        std::size_t typeId = m_nameToTypeMap.at(componentName);

        auto factory = m_componentFactories[typeId];
        auto data = factory->ConstructData(json);

        return data;
    }

    template <class C>
    void RegisterName(const std::string& componentName)
    {
        size_t typeId = GetTypeID<C>();
        m_nameToTypeMap.insert({componentName, typeId});
    }

private:
    std::unordered_map<std::size_t, std::shared_ptr<ComponentBase>> m_componentFactories;
    std::unordered_map<std::string, std::size_t> m_nameToTypeMap;
};

int main()
{
    std::ifstream file("components.json");
    rapidjson::IStreamWrapper isw(file);
    rapidjson::Document document;
    document.ParseStream(isw);

    Factory factory;
    factory.RegisterComponent<Position>();
    factory.RegisterComponent<Name>();
    factory.RegisterComponent<Size>();
    factory.RegisterComponent<Velocity>();
    factory.RegisterName<Position>("Position");
    factory.RegisterName<Name>("Name");
    factory.RegisterName<Size>("Size");
    factory.RegisterName<Velocity>("Velocity");

    for (auto iter = document.Begin(); iter != document.End(); ++iter)
    {
