// ...

// задаем ширину таблицы
com::sun::star::uno::Sequence<com::sun::star::table::TableColumnSeparator> separators(1);
separators[0].Position = 0;
separators[0].IsVisible = true;
separators[0].IsAutoSeparating = false;
separators[0].SeparatorType = com::sun::star::table::TableColumnSeparatorType_NONE;
separators[0].SeparatorStyle = com::sun::star::table::TableColumnSeparatorStyle_LINE;
separators[0].LineColor = 0;
