using BC = BCrypt.Net.BCrypt;


[Route("api/auth")]
[ApiController]
public class AuthController : Controller
{
    private readonly UserDbContext _context;
    private readonly IConfiguration _configuration;

    public AuthController(UserDbContext context, IConfiguration configuration)
    {
        _context = context;
        _configuration = configuration;
    }

    [HttpPost("register")]
    public async Task<IActionResult> Register([FromBody] RegisterModel model)
    {
        var userExists = await _context.Users.SingleOrDefaultAsync(x => x.Email == model.Email);
        if (userExists != null) return BadRequest(new { message = "Email is already in use." });

        var hashedPassword = BC.HashPassword(model.Password);
        var user = new User { Email = model.Email, Password = hashedPassword };

        _context.Users.Add(user);
        await _context.SaveChangesAsync();

        return Ok(new { Token = GenerateJwtToken(model.Email, user) });
    }

    [HttpPost("login")]
    public async Task<IActionResult> Login([FromBody] LoginModel model)
    {
        var user = await _context.Users.SingleOrDefaultAsync(x => x.Email == model.Email);
        if (user == null || !BC.Verify(model.Password, user.Password)) return BadRequest(new { message = "Invalid Email or Password" });

        return Ok(new { Token = GenerateJwtToken(model.Email, user) });
    }

    [HttpPost("logout")]
    public IActionResult Logout()
    {
        return Ok(new { message = "User logged out successfully." });
    }

    private object GenerateJwtToken(string email, User user)
    {
        var claims = new List<Claim>
        {
            new Claim(JwtRegisteredClaimNames.Sub, email),
            new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
            new Claim(ClaimTypes.NameIdentifier, user.Id.ToString())
        };

        var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_configuration["JwtKey"]));
        var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);
        var expires = DateTime.Now.AddDays(Convert.ToDouble(_configuration["JwtExpireDays"]));

        var token = new JwtSecurityToken(
            _configuration["JwtIssuer"],
            _configuration["JwtIssuer"],
            claims,
            expires: expires,
            signingCredentials: creds
        );

        return new JwtSecurityTokenHandler().WriteToken(token);
    }
}
