To do this, we will implement the multisignature logic inside the EOAController. Here's the solidity code:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

contract EOAController {
    using SafeMath for uint256;
    using ECDSA for bytes32;

    address[] public owners;
    uint256 public required;
    mapping(address => bool) public isOwner;

    uint256 public nextNonce = 1;

    struct Transaction {
        address to;
        uint256 value;
        bytes data;
    }

    modifier onlyOwner() {
        require(isOwner[msg.sender], "Not an owner");
        _;
    }

    event Execute(address indexed sender, uint256 indexed nonce, Transaction tx);

    constructor(address[] memory _signers, uint256 _required) {
        require(_signers.length >= _required && _required != 0 && _signers.length != 0, "Invalid parameters");

        for (uint256 i = 0; i < _signers.length; i++) {
            require(!isOwner[_signers[i]] && _signers[i] != address(0), "Invalid signer");
            isOwner[_signers[i]] = true;
        }

        owners = _signers;
        required = _required;
    }

    function executeMultiSig-ERC4337(uint256 nonce, address to, uint256 value, bytes calldata data, uint8[] calldata sigV, bytes32[] calldata sigR, bytes32[] calldata sigS) external onlyOwner {
        require(nextNonce == nonce, "Invalid nonce");
        require(sigR.length == required && sigR.length == sigS.length && sigR.length == sigV.length, "Invalid signatures");

        bytes32 transactionHash = keccak256(abi.encodePacked(address(this), nonce, to, value, data));

        address[] memory seenAddresses = new address[](required);

        for (uint256 i = 0; i < required; i++) {
            address recoveredAddress = transactionHash.toEthSignedMessageHash().recover(sigV[i], sigR[i], sigS[i]);
            require(isOwner[recoveredAddress], "Invalid signature, signer must be an owner");

            // Avoid duplicate signer
            for (uint256 j = 0; j < i; j++) {
                require(recoveredAddress != seenAddresses[j], "Duplicate signer");
            }
            seenAddresses[i] = recoveredAddress;
        }

        nextNonce += 1;
        (bool status,) = to.call{value: value}(data);
        require(status, "Transaction failed");

        emit Execute(msg.sender, nonce, Transaction(to, value, data));
    }
}
```

