  return a + b + c;
}

const sum = addThreeNumbers(2, 4, 6);

console.log(sum); // Output: 12
```

4. Using the `arguments` object to add any number of arguments:

```javascript
function addNumbers() {
  let sum = 0;
  for (let i = 0; i < arguments.length; i++) {
    sum += arguments[i];
  }
  return sum;
}

const sum = addNumbers(2, 4, 6);

console.log(sum); // Output: 12
```

5. Using the `spread` operator to add three arguments passed through an array:

```javascript
const numbers = [2, 4, 6];

const sum = addNumbers(...numbers);

console.log(sum); // Output: 12

function addNumbers(a, b, c) {
  return a + b + c;
}
```

