    clients.delete(client);
  });

  socket.on('error', (error) => {
    console.error(`Client error: ${client.id}`, error);
  });
});

function brodcast(eventData, senderId) {
  clients.forEach((client) => {
    if (client.id === senderId) {
      return;
    }

    try {
      client.socket.write(JSON.stringify(eventData));
    } catch (error) {
      console.error(`Error sending message to ${client.id}`, error);
    }
  });
}

const port = 8080;
server.listen(port, () => {
