```rust
use axum::{
    extract::{Extension, FromRequest, RequestParts},
    handler::get,
    http::StatusCode,
    response::{Html, IntoResponse},
    AddExtensionLayer, Router,
};
use std::sync::Arc;
use tower_http::{trace::{DefaultMakeSpan, TraceLayer},TraceMiddleware};
use tower::extract::Extract;

struct RequestIdGenerator;

impl RequestIdGenerator {
    fn new() -> Self {
        Self
    }

    fn generate_id(&self) -> String {
        uuid::Uuid::new_v4().to_string()
    }
}

async fn handler(request_id: Extension<Arc<String>>) -> impl IntoResponse {
    Html(format!(
        "<h1>Hello, world!</h1><p>Request ID: {}</p>",
        request_id.as_ref()
    ))
    .with_status(StatusCode::OK)
    .into_response()
}

#[tokio::main]
async fn main() {
    let app = Router::new().route("/", get(handler));
    let request_id_generator = Arc::new(RequestIdGenerator::new());
    let trace_layer =
        TraceLayer::<_, _, _, DefaultMakeSpan>::new().make_span_with(move |req| {
            tracing::info_span!(
                "span",
                method = %req.method(),
                path = %req.uri(),
                request_id = %request_id_generator.generate_id(),
            )
        });

    let middleware = TraceMiddleware::new(trace_layer).app_data(request_id_generator).untagged();

    let app = middleware.combine(app)
        .layer(AddExtensionLayer::new(Arc::new(RequestIdGenerator::new())));
    let app = Extract::<(Extension<Arc<RequestIdGenerator>>,), error::Error>::extract_from(&app).boxed();

    axum::Server::bind(&"0.0.0.0:3000".parse().unwrap())
        .serve(app.into_make_service())
        .await
        .unwrap();
}
```

