2. Для написания плагина создайте новый текстовый файл с расширением `.sp` (например, "LuaBlocker.sp") в папке с плагинами SourcePawn (например, `addons/sourcemod/scripting/`).
3. В новом файле напишите следующий код (данный код является примером и не гарантирует полную защиту от скриптов Lua):

```C
#include <sourcemod>

public Plugin myinfo =
{
	name = "Lua Blocker",
	author = "YourName",
	description = "A simple Lua script blocker for CSS v34",
	version = "1.0",
	url = "https://www.example.com"
};

public void OnPluginStart()
{
	RegConsoleCmd("sm_blocklua", CmdBlockLua, "Blocks a client that is suspected of using Lua scripts");
}

public Action CmdBlockLua(int client, int argc)
{
	if (!IsClientInGame(client))
	{
		return Plugin_Handled;
	}

	int target = GetCmdArgInt(1);

	if (target <= 0 || target > MaxClients)
	{
		ReplyToCommand(client, "[Lua Blocker] Invalid client index!");
		return Plugin_Handled;
	}

	if (!IsClientInGame(target))
	{
		ReplyToCommand(client, "[Lua Blocker] Specified client is not in the game!");
		return Plugin_Handled;
	}

	ServerCommand("sm_kick #%d %s", GetClientUserId(target), "Kicked for suspected Lua scripting");
	ReplyToCommand(client, "[Lua Blocker] Client %d has been kicked for suspected Lua scripting.", target);

	return Plugin_Handled;
}
```

Этот базовый плагин предоставляет команду `sm_blocklua`, которая используется для кика игроков, подозреваемых в использовании Lua-скриптов. Вы можете добавить более сложную логику для обнаружения и предотвращения использования Lua-скриптов.

4. После написания плагина скомпилируйте его в исполняемый файл SourcePawn (`.smx`) с помощью компилятора SourcePawn (`spcomp.exe`), расположенного в папке `addons/sourcemod/scripting/`.
5. Скопируйте скомпилированный файл `.smx` в папку `addons/sourcemod/plugins/` на вашем сервере и перезагрузите/запустите сервер.

Пожалуйста, имейте в виду, что этот плагин является лишь примером и покрывает только один аспект защиты от Lua-скриптов. Вам придется провести исследования и написать дополнительный код для усиления защиты, а также поддерживать его актуальность.

