                        Debug.Log("Collider contacto: " + overlappingCollider.name);
                        OnCollisionEnter(collider, overlappingCollider);
                    }
                }
            }
        }

        if (inventory_hover)
        {
            Scene_to_inventory(scene_element_select);
        }
    }

    private void OnCollisionEnter(Collider collider1, Collider collider2)
    {
        // Evitar que objetos se muevan a través de otros objetos
        Vector3 direction = collider1.transform.position - collider2.transform.position;
        collider1.attachedRigidbody.AddForce(direction.normalized * 10);
    }
