Puedes lograr el comportamiento deseado utilizando Physics.ComputePenetration para calcular la penetración entre colliders involucrados en una colisión y evitar que los objetos se superpongan. Aquí está la función SceneDrag modificada, sin el uso de Rigidbodies:

```csharp
public void SceneDrag()
{
    Vector3 mousePosition = Input.mousePosition;
    Ray ray = Camera.main.ScreenPointToRay(mousePosition);
    Plane plane = new Plane(Vector3.up, scene_element_select.transform.position);

    float distance;
    if (plane.Raycast(ray, out distance))
    {
        Vector3 clickPos = ray.GetPoint(distance);
        Vector3 objectPos = scene_element_select.transform.position;
        Vector3 orientacion = objectPos - clickPos;
        setreference(orientacion);

        float distanciaInicial = orientacion.magnitude;

        Vector3 direccion = orientacion.normalized;
        Vector3 newObjectPos = objectPos - (direccion * distanciaInicial);

        scene_element_select.transform.position = reference + clickPos;

        // Mostrar en debug los objetos que hacen contacto con el Collider
        LayerMask layerMask = LayerMask.GetMask("Furniture", "RoomComponents");
        Collider[] colliders = scene_element_select.GetComponentsInChildren<Collider>();
        foreach (Collider collider in colliders)
        {
            if (collider.gameObject.layer == LayerMask.NameToLayer("Furniture") || collider.gameObject.layer == LayerMask.NameToLayer("RoomComponents"))
            {
                Collider[] overlappingColliders = Physics.OverlapBox(collider.bounds.center, collider.bounds.extents, Quaternion.identity, layerMask);
                foreach (Collider overlappingCollider in overlappingColliders)
                {
                    if (overlappingCollider.transform.IsChildOf(scene_element_select.transform))
                        continue;

                    Debug.Log("Collider contacto: " + overlappingCollider.name);

                    // Calcular la penetración entre los colliders en colisión
                    Vector3 direction;
                    float distancePenetration;
                    if (Physics.ComputePenetration(collider, collider.transform.position, collider.transform.rotation, overlappingCollider, overlappingCollider.transform.position, overlappingCollider.transform.rotation, out direction, out distancePenetration))
                    {
                        scene_element_select.transform.position += direction * distancePenetration;
                    }
                }
            }
        }
    }

    if (inventory_hover)
    {
        Scene_to_inventory(scene_element_select);
    }
}
```

Esta solución implica calcular la penetración entre los colliders en colisión y mover el objeto "scene_element_select" en la dirección opuesta a la penetración para evitar la superposición.

