    #pragma omp parallel for private(i,j,found) shared(wordcount, count)
    for(i=0; i<count; i++)
    {
        int found = 0;
        for(j=0; j<i; j++)
        {
            if(strcmp(wordcount[i].word, wordcount[j].word)==0) //判断是否找到了已经处理过的单词
            {
                found = 1;
