```javascript
drawCell: (
  ctx: CanvasRenderingContext2D,
  cupItem: CupItem,
  maxVolume: number,
  isBestPrice: boolean,
  yPosition: number,
  cellHeight: number,
  fullWidth: number,
  dpiScale: number,
  darkMode: boolean,
) => {
