    while (1) {
        for (col = 0; col < 3; col++) {
            IO0CLR = 0x0000000F;
            IO0SET= 0x00000001 << col;

            for (row = 0; row < 4; row++) {
                if ((IO0PIN >> (4 + row)) & 0x01) {
                    while ((IO0PIN >> (4 + row)) & 0x01);

                    return keypadKeys[row][col];
                }
            }
        }
