   struct node *temp1 = list1, *temp2 = list2, *new_list = NULL, *temp = NULL;
   while(temp1 != NULL && temp2 != NULL) {
      if(temp1->data < temp2->data) {
         if(new_list == NULL) {
            new_list = temp1;
            temp = new_list;
         }
         else {
            temp->next = temp1;
            temp1->prev = temp;
            temp = temp->next;
         }
         temp1 = temp1->next;
      }
      else {
         if(new_list == NULL) {
            new_list = temp2;
            temp = new_list;
         }
         else {
            temp->next = temp2;
            temp2->prev = temp;
            temp = temp->next;
         }
         temp2 = temp2->next;
      }
   }
   if(temp1 != NULL) {
      temp->next = temp1;
      temp1->prev = temp;
   }
   if(temp2 != NULL) {
      temp->next = temp2;
      temp2->prev = temp;
   }
