// Get the drop target element
var dropTarget = document.getElementById("drop-target");

// Add a drop event listener to the drop target
dropTarget.addEventListener("drop", function(event) {
  // Get the source element
  var sourceElement = event.dataTransfer.getData("text/plain");

  // Compare the source element with the drop target element
  if (sourceElement === dropTarget.id) {
    console.log("Drop is on the same div");
  } else {
    console.log("Drop is not on the same div");
  }
});

// Add a drag start event listener to the source element
