Here is a simple Sudoku game in JavaScript:

HTML:

```html
<!DOCTYPE html>
<html>
  <head>
    <meta charset="UTF-8">
    <title>Sudoku Game</title>
    <style>
        .sudoku-row {
            display: flex;
            justify-content: center;
        }
        .sudoku-cell {
            width: 50px;
            height: 50px;
            text-align: center;
            line-height: 50px;
            border: 1px solid black;
        }
        .sudoku-bold {
            font-weight: bold;
            background-color: #EEE;
        }
    </style>
  </head>
  <body>
    <h1>Sudoku Game</h1>
    <div id="sudoku-board"></div>
    <button onclick="checkSolution()">Check Solution</button>
    <script src="sudoku.js"></script>
  </body>
</html>
```

JavaScript:

```javascript
// Define the Sudoku grid
let board = [
  [0,0,0,0,0,9,2,0,0],
  [0,0,0,5,0,0,0,9,0],
  [6,0,7,0,0,2,0,0,5],
  [0,0,0,0,3,0,0,0,0],
  [0,2,0,0,0,0,0,7,0],
  [0,0,0,9,0,0,0,0,0],
  [9,0,3,0,0,0,0,8,0],
  [0,5,0,0,0,0,0,3,0],
  [0,0,1,8,0,0,0,0,0]
];

// Display the Sudoku grid
let sudokuBoard = document.getElementById("sudoku-board");
for (let i = 0; i < board.length; i++) {
  let row = document.createElement("div");
  row.classList.add("sudoku-row");
  for (let j = 0; j < board[i].length; j++) {
    let cell = document.createElement("div");
    cell.classList.add("sudoku-cell");
    if (j % 3 === 0 && j !== 0) {
      cell.style.borderLeft = "3px solid black";
    }
    if (i % 3 === 0 && i !== 0) {
      cell.style.borderTop = "3px solid black";
    }
    if (board[i][j] !== 0) {
      cell.textContent = board[i][j];
      cell.classList.add("sudoku-bold");
    }
    row.appendChild(cell);
  }
  sudokuBoard.appendChild(row);
}

// Check if solution is correct
function checkSolution() {
  for (let i = 0; i < board.length; i++) {
    // Check each row for duplicates
    let rowValues = [];
    for (let j = 0; j < board[i].length; j++) {
      if (board[i][j] !== 0 && rowValues.includes(board[i][j])) {
        alert("Solution is incorrect!");
        return;
      }
      rowValues.push(board[i][j]);
    }
    // Check each column for duplicates
    let colValues = [];
    for (let j = 0; j < board[i].length; j++) {
      if (board[j][i] !== 0 && colValues.includes(board[j][i])) {
        alert("Solution is incorrect!");
        return;
      }
      colValues.push(board[j][i]);
    }
    // Check each 3x3 box for duplicates
    let boxValues = [];
    let boxRow = Math.floor(i / 3) * 3;
    let boxCol = (i % 3) * 3;
    for (let j = boxRow; j < boxRow + 3; j++) {
      for (let k = boxCol; k < boxCol + 3; k++) {
        if (board[j][k] !== 0 && boxValues.includes(board[j][k])) {
          alert("Solution is incorrect!");
          return;
        }
        boxValues.push(board[j][k]);
      }
    }
  }
  alert("Solution is correct!");
}
```

This code displays the Sudoku board on a web page and checks if the solution is correct when the "Check Solution" button is clicked. It checks each row, column, and 3x3 box for duplicates and alerts the user if the solution is incorrect.

