    const newList = [...oldList];

    const newBlock1 = { ...newList[index], content: content }; // update content
    const newBlock2 = { ...newList[index - 1], content: newList[index - 1].content }; // update content

    [newList[index - 1], newList[index]] = [newBlock1, newBlock2];

    return newList;
  });
};

const handleDown = (x) => {
  props.setList((oldList) => {
    const index = oldList.indexOf(x);
    const newList = [...oldList];

    const newBlock1 = { ...newList[index], content: content }; // update content
    const newBlock2 = { ...newList[index + 1], content: newList[index + 1].content }; // update content

    [newList[index], newList[index + 1]] = [newBlock2, newBlock1];

    return newList;
  });
};
```

Now, when you change the order of the blocks, the content changes will be reflected for both blocks that are being swapped. This approach will ensure that the parent component's state is updated accurately.

