                printf("%c ", board[i][j]);
            }
        }
        printf("\n");
    }
    printf("\n");
}

int check_adjacent_mines(char** board, int x, int y) {
    int count = 0;

    for (int i = -1; i <= 1; i++) {
        for (int j = -1; j <= 1; j++) {
            int newX = x + i;
            int newY = y + j;

            if (newX >= 0 && newX < BOARD_SIZE && newY >= 0 && newY < BOARD_SIZE) {
                if (board[newX][newY] == MINE) {
                    count++;
                }
            }
        }
    }

    return count;
}

void generate_mines(char** board) {
    for (int i = 0; i < NUM_MINES; i++) {
        int x = rand() % BOARD_SIZE;
        int y = rand() % BOARD_SIZE;

        if (board[x][y] == MINE) {
            i--;
            continue;
        }

        board[x][y] = MINE;
    }
}

void uncover_board(char** board, char** visible_board, int x, int y, int* covered_spaces) {
    if (x >= 0 && x < BOARD_SIZE && y >= 0 && y < BOARD_SIZE && visible_board[x][y] == HIDDEN_SPACE) {
