#dapenversion 1.0.0

#define OAS_MAX_TOTAL_USERS 4294967296
#define MAX_PROPOSALS_PER_USER 262144

struct VoteStatus {
  yesVotes: uint,
  noVotes: uint,
}

struct ProposalContent{
  endTime: uint,
  minVotesToPass: uint,
  actionHash: ghash,
}

struct TestC{
  a: uint,
  b: uint[1],
  c: ghash[3],
  d: uint[100],
}

contract ExampleDAO {

  // declare events
  event ProposalCreated {
    proposer: uint,
    proposalId: uint,
    endTime: uint,
    minVotesToPass: uint,
    actionHash: ghash,
  }

  event UserVoted {
    userId: uint,
    proposer: uint,
    proposalId: uint,
    isYesVote: bool,
  }

  // declare global state variables
  gvar proposalVoteStatuses VoteStatus[OAS_MAX_TOTAL_USERS][MAX_PROPOSALS_PER_USER]; 

  // declare user state variables
  var userProposals ProposalContent[MAX_PROPOSALS_PER_USER];
  var userVoteRecord uint[OAS_MAX_TOTAL_USERS][MAX_PROPOSALS_PER_USER];
  var proposalCount uint;
  var testA uint[123];
  var testB uint[1];
  var testC TestC;
  var testD TestC[100];
  var testE TestC[1];


  // declare contract functions
  fn createProposal(endTime: uint, minVotesToPass: uint, actionHash: TestC);
  fn vote(proposer: uint, proposalId: uint, isYesVote: bool);

  // declare contract view functions (read only functions)
  view hasPassed(proposer: uint, proposalId: uint): bool;
}
