package main

import (
	"fmt"
	"math"
	"strings"
)

type TokenType int

const (
	Number TokenType = iota
	Operator
	Variable
	Function
	ArgumentSeparator
)

type Token struct {
	Type  TokenType
	Value string
}

var variables = make(map[string]float64)

func parseExpression(expression string) ([]Token, error) {
	tokens := []Token{}
	var buffer strings.Builder

	for _, ch := range expression {
		if ch == ' ' {
			continue
		}

		if strings.ContainsRune("+-/^()!", ch) {
			if buffer.Len() > 0 {
				token, err := createToken(buffer.String())
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, token)
				buffer.Reset()
			}
			tokens = append(tokens, Token{Type: Operator, Value: string(ch)})
		} else if ch == ',' {
			if buffer.Len() > 0 {
				token, err := createToken(buffer.String())
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, token)
				buffer.Reset()
			}
			tokens = append(tokens, Token{Type: ArgumentSeparator, Value: string(ch)})
		} else {
			buffer.WriteRune(ch)
		}
	}

	if buffer.Len() > 0 {
		token, err := createToken(buffer.String())
		if err != nil {
			return nil, err
		}
		tokens = append(tokens, token)
	}

