void diagonalPreorderTraversalHelper(Node *root, int currdiagonal, map<int, vector<int>> &mp) {
    if (!root) return;

    mp[currdiagonal].push_back(root->data);

    if (root->left) {
        diagonalPreorderTraversalHelper(root->left, currdiagonal + 1, mp);
    }
    if (root->right) {
        diagonalPreorderTraversalHelper(root->right, currdiagonal, mp);
    }
}

vector<int> diagonal(Node *root)
{
    vector<int> v;
    if (!root) return v;

    map<int, vector<int>> mp;
    diagonalPreorderTraversalHelper(root, 0, mp);

