import { useNavigate } from 'react-router-dom';
import API from '../API';
import dayjs from 'dayjs';
import '../style.css';


//Can't get it from database because it is not saved.
//This number is used only for triggering the re-render of the content of the Forms of each block showed at video. (ex when handleUp or handleDown)
function generatelocalId() {
    return Math.random().toString(36).substring(2) + Date.now().toString(36);
}

function BlockList(props) {

    function headerBlock() {
        this.blockType = "Header";
        this.content = "";
    }

    function paragraphBlock() {
        this.blockType = "Paragraph";
        this.content = "";
    }
    function imageBlock() {
        this.blockType = "Image";
        this.content = "";
    }

    const addToList = (x) => {
        props.setList((oldList) => [...oldList, x]);
    };

    return (
        <>
            <h5 style={{ textAlign: "center" }}>Components</h5>
            <p></p>
            <Card>
                <ListGroup>
                    <ListGroup.Item >
                        Header
                        <Button className="float-end addbutton" variant="outline-success"
                            onClick={() => {
                                addToList(new headerBlock());
                            }}>
                            <i className="bi bi-plus"></i>
                        </Button>
                    </ListGroup.Item>
                    <ListGroup.Item >
                        Paragraph
                        <Button className="float-end addbutton" variant="outline-success"
                            onClick={() => {
                                addToList(new paragraphBlock());
                            }}>
                            <i className="bi bi-plus"></i>
                        </Button>
                    </ListGroup.Item>
                    <ListGroup.Item >
                        Image
                        <Button className="float-end addbutton" variant="outline-success"
                            onClick={() => {
                                addToList(new imageBlock());
                            }}>
                            <i className="bi bi-plus"></i>
                        </Button>
                    </ListGroup.Item>
                </ListGroup>
            </Card>
        </>
    );
}

function CreatePageBody(props) {

    return (
        <Accordion>
            {props.list.map((x,i) => <MyBlock x={x} i={i} key={generatelocalId()} list={props.list} setList={props.setList} images={props.images} />)}
        </Accordion>
    );
}

function MyBlock(props) {

    const x = props.x;
    const images = props.images;
    const [content, setContent] = useState(props.list[props.i].content);
    const inputEl = useRef(null);

    const removeFromList = (x) => {
        props.setList((oldlist) => oldlist.filter((item) => item != x));
    };

    const handleUp = (x) => {
        props.setList(oldList => {
            const index = oldList.indexOf(x);
            const newList = [...oldList];
            [newList[index - 1], newList[index]] = [newList[index], newList[index - 1]];
            return newList;
        });
    };

    const handleDown = (x) => {
        props.setList(oldList => {
            const index = oldList.indexOf(x);
            const newList = [...oldList];
            [newList[index], newList[index + 1]] = [newList[index + 1], newList[index]];
            return newList;
        });
    };

    const handlechange = (ev) => {
        props.setList(oldList => {
            const newList = [...oldList];
            newList[props.i].content=ev.target.value;
            return newList;
        });
    };


    useEffect(() => {
        inputEl.current?.focus();
    }, [inputEl.current?.value]);

    return (
        <Accordion.Item eventKey={props.list.indexOf(x)}>
            <Accordion.Header >
                <div className="accordion-style">
                    {x.blockType}
                    <ButtonGroup style={{ paddingRight: "2%" }} >
                        {props.list.indexOf(x) != 0 && ( //button as div avoid nested buttons error validateDOMnesting - since accordion header is a button itself!
                            <Button as='div' style={{ fontSize: "0.8rem", padding: "0.25rem 0.5rem" }} variant="outline-secondary"
                                onClick={(ev) => { ev.stopPropagation(); handleUp(x) }}>
                                <i className="bi bi-arrow-up"></i>
                            </Button>)}
                        {props.list.indexOf(x) != (props.list.length - 1) && (
                            <Button as='div' style={{ fontSize: "0.8rem", padding: "0.25rem 0.5rem" }} variant="outline-secondary"
                                onClick={(ev) => { ev.stopPropagation(); handleDown(x) }}>
                                <i className="bi bi-arrow-down"></i>
                            </Button>)}
                        <Button as='div' size="sm" variant="outline-danger"
                            onClick={(ev) => { ev.stopPropagation(); removeFromList(x) }}>
                            <i className="bi bi-x-lg"></i>
                        </Button>
                    </ButtonGroup>
                </div>
            </Accordion.Header>
            <Accordion.Body>
                {x.blockType != "Image" ? (
                    <Form.Control as="textarea" ref={inputEl} onFocus={(e)=>e.currentTarget.setSelectionRange(e.currentTarget.value.length, e.currentTarget.value.length)} value={content} onChange={(ev) => { handlechange(ev) }}></Form.Control>
                ) : (
                    <div>
                        {images.map((image) => (
                            <label key={generatelocalId()} style={{ paddingRight: "20px" }}>
                                <input value={image.url} onChange={(ev) => { handlechange(ev); }} checked={x.content == image.url} type="radio" />
                                <img className="img-box" src={image.url} alt={image.alt} />
                            </label>
                        ))}
                    </div>
                )}
            </Accordion.Body>
        </Accordion.Item>
    );


}



function ActionList(props) {

    // Placed here because otherwise handleAction couldn't call navigate.
    // Uncaught Error: Invalid hook call. Hooks can only be called inside of the body of a function component.
    const navigate = useNavigate();

    const [date, setDate] = useState(""); // Used to publish programmed pages

    const list = props.list;
    const title = props.title;

    return (
        <Col className="pt-4">
            <Button variant="warning" style={{ marginBottom: "2%", width: "100%" }} onClick={() => handleAction("draft")}>Save as Draft</Button>
            <Button variant="success" style={{ marginBottom: "10%", width: "100%" }} onClick={() => handleAction("publish")}>Publish</Button>
            <Form.Control type="date" name="date" value={date} onChange={(ev) => setDate(ev.target.value)} />
            <Button variant="secondary" style={{ marginTop: "2%", width: "100%" }} onClick={() => handleAction("programmed")}>Schedule Publication</Button>
        </Col>
    );

    function handleAction(action) {

        let valid = true;
        let data = {};

        if (title.trim() == "") {
            valid = false;
            props.handleError("You have to choose a title for the page.");
        }
        else if (!(list.some(item => item.blockType == 'Header')) ||
            (!(list.some(item => item.blockType == 'Paragraph') || list.some(item => item.blockType == 'Image')))
        ) {
            valid = false;
            props.handleError("You have to insert at least a Header and a Paragraph/Image.");
        }
        else if (list.some(item => (item.content.trim() == ""))) {
            valid = false;
            props.handleError("At least one block without content!");
        }

        if (valid) {
            data = { // Data formatted. Ready to send it to the server for Page Creation.
                title: title,
                blocks: JSON.stringify(list) // Saved directly as json in db
            };

            switch (action) {
                case "draft":
                    Object.assign(data, { publishDate: null });
                    break;
                case "publish":
                    Object.assign(data, { publishDate: dayjs().format("YYYY-MM-DD") });
                    break;
                case "programmed":
                    const Date = dayjs(date);
                    if (!Date.isValid() || Date.isBefore(dayjs())) { //dayjs() returns today date
                        props.handleError("Select a valid date.");
                        return;
                    }
                    Object.assign(data, { publishDate: Date.format("YYYY-MM-DD") });
                    break;
                default:
                    break;

            }

            API.createPage(data)
                .then(() => {
                    navigate("/backoffice")
                })
                .catch((err) => props.handleError(err));
        }
    }

}




function Title(props) {
    return (
        <Form.Control type="text" name="text" value={props.title} placeholder="Page Title" onChange={ev => props.setTitle(ev.target.value)} />
    );
}

export { Title, ActionList, BlockList, CreatePageBody, MyBlock };


When I write one character in the title form then it will change focus to the form of an open accordion

It seems that the focus is being set to the input element inside the `MyBlock` component whenever a re-render occurs, due to the `useEffect` hook in that component. This hook re-focuses the input element whenever there is a change in the value of any input field (including the title form field) and causes the input element to gain focus. To prevent this refocusing issue, you can update the dependency array for the `useEffect` hook in the `MyBlock` component.

Change the following piece of code in the `MyBlock` component:

```javascript
useEffect(() => {
    inputEl.current?.focus();
}, [inputEl.current?.value]);
```

to:

```javascript
useEffect(() => {
    inputEl.current?.focus();
}, []);
```

By setting the dependency array to an empty array (`[]`), the `useEffect` hook will only execute once, when the component mounts. This will make sure that the input element gains focus only when the component is initially mounted and not whenever the value of any input field changes, preventing the issue you're facing.

I see, in that case, you can add a local state variable for the `MyBlock` component to track if the input field within that component should receive focus. When the inner content of the component is changed, we'll set the state variable to true, and use this value to conditionally apply the focus in the `useEffect` hook. Afterwards, set the state variable back to false to persist the focus. 

Here's how you can modify the `MyBlock` component:

```javascript
function MyBlock(props) {
  // ...all other code...

  // Add a new state variable to keep track of whether to apply focus
  const [shouldFocus, setShouldFocus] = useState(false);

  // Update the handleChange function
  const handlechange = (ev) => {
    props.setList((oldList) => {
      const newList = [...oldList];
      newList[props.i].content = ev.target.value;
      return newList;
    });
    setShouldFocus(true); // Set shouldFocus to true when the content changes
  };

  // Update the useEffect hook to conditionally apply focus
  useEffect(() => {
    if (shouldFocus) {
      inputEl.current?.focus();
      setShouldFocus(false); // Set shouldFocus back to false once the input has received focus
    }
  }, [content]);

  return (
    // ...rest of the component code...
  );
}
```

This will ensure that the focus is applied to the input field within the `MyBlock` component every time its content is changed, while not affecting the focus on other input fields, such as the title field.

You can use this condition inside a custom event handler that listens for an outside click event. This event handler will be responsible for checking if the event target element is contained within the specific input element or not.

You'll want to register and unregister this event handler with the `useEffect` hook. Here's an example of how you can implement this behavior:

```javascript
function MyBlock(props) {
  // ...All previous code...

  // Create a custom event handler for the outside click event
  const handleClickOutside = (event) => {
    if (!inputEl.current.contains(event.target)) {
      // If the event target element is not contained within the input element,
      // perform the desired action here, like closing the field or removing the focus.
    }
  };

  // Register the event handler in the useEffect hook
  useEffect(() => {
    // Registering the handleClickOutside event handler
    document.addEventListener("mousedown", handleClickOutside);

    // Clean up function which unregisters the handleClickOutside event handler
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // ...All previous code...
}
```

This will listen for the mousedown event on the document and call the `handleClickOutside` function whenever a mouse click occurs outside the input element. Inside the `handleClickOutside` function, you can perform any actions that need to happen when the user clicks outside of the input element. Make sure to clean up the event listener once the component is unmounted.

