function addOptions() {
  var select = document.getElementById("my-select");
  select.innerHTML = ""; // 先清空下拉框中的所有选项
  var startIndex = (pageNum - 1) * pageSize; // 计算开始索引
  var endIndex = startIndex + pageSize; // 计算结束索引
  for (var i = startIndex; i < endIndex; i++) {
    if (i >= data.length) {
      break; // 数据已经全部显示完毕，退出循环
    }
