import javafx.scene.layout.BorderPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.stage.FileChooser;
import javafx.stage.Stage;

public class MusicPlayer extends Application {

    private MediaPlayer mediaPlayer;
    private Label statusLabel;
    private ListView<String> playlistView;
    private ObservableList<String> playlist;
    private FileChooser fileChooser;

    @Override
    public void start(Stage primaryStage) throws Exception {
        BorderPane root = new BorderPane();
        Scene scene = new Scene(root, 800, 600);

        // Create menu bar
        MenuBar menuBar = new MenuBar();
        Menu fileMenu = new Menu("File");
        MenuItem openMenuItem = new MenuItem("Open");
        MenuItem exitMenuItem = new MenuItem("Exit");
        fileMenu.getItems().addAll(openMenuItem, exitMenuItem);
        menuBar.getMenus().addAll(fileMenu);

        // Create toolbar
        ToolBar toolBar = new ToolBar();
        Button playButton = new Button(">");
        Button pauseButton = new Button("||");
        Button stopButton = new Button("[]");
        toolBar.getItems().addAll(playButton, pauseButton, stopButton);

        // Attach media player to media view
        MediaView mediaView = new MediaView();
        mediaView.setFitHeight(400);
        mediaView.setFitWidth(600);

        // Create playlist view
        playlistView = new ListView<String>();
        playlist = playlistView.getItems();

        // Create status label
        statusLabel = new Label();

        // Create file chooser
        fileChooser = new FileChooser();

        // Create pane for music player controls
        HBox controlPane = new HBox();
        controlPane.setSpacing(10);
        controlPane.setPadding(new Insets(10, 10, 10, 10));
        controlPane.setStyle("-fx-background-color: #336699;");
        controlPane.getChildren().addAll(menuBar, toolBar);

        // Create pane for playlist and status label
        VBox playlistPane = new VBox();
        playlistPane.setPadding(new Insets(10, 10, 10, 10));
        playlistPane.setSpacing(10);
        playlistPane.getChildren().addAll(playlistView, statusLabel);

        // Attach panes to root pane
        root.setTop(controlPane);
        root.setCenter(mediaView);
        root.setRight(playlistPane);

        // Add event handlers
        playButton.setOnAction(e -> playMedia());
        pauseButton.setOnAction(e -> pauseMedia());
        stopButton.setOnAction(e -> stopMedia());
        openMenuItem.setOnAction(e -> openFile(primaryStage));
        exitMenuItem.setOnAction(e -> System.exit(0));
        playlistView.setOnMouseClicked(e -> {
            if (e.getClickCount() == 2) {
                int index = playlistView.getSelectionModel().getSelectedIndex();
                playMedia(new File(playlist.get(index)).toURI().toString());
            }
        });
        mediaView.setOnMouseClicked(e -> {
            if (e.getClickCount() == 2) {
                if (mediaPlayer.getStatus() == Status.PLAYING) {
                    mediaPlayer.pause();
                } else {
                    mediaPlayer.play();
                }
            }
        });

        primaryStage.setScene(scene);
        primaryStage.show();
    }

    private void openFile(Stage primaryStage) {
        File file = fileChooser.showOpenDialog(primaryStage);
        if (file != null) {
            String filePath = file.toURI().toString();
            playlist.add(file.getPath());
        }
    }

    private void playMedia() {
        if (mediaPlayer != null && mediaPlayer.getStatus() == Status.PAUSED) {
            mediaPlayer.play();
        } else {
            int index = playlistView.getSelectionModel().getSelectedIndex();
            if (index >= 0 && index < playlist.size()) {
                String filePath = new File(playlist.get(index)).toURI().toString();
                playMedia(filePath);
            }
        }
    }

    private void playMedia(String filePath) {
        if (mediaPlayer != null) {
            mediaPlayer.stop();
        }
        Media media = new Media(filePath);
        mediaPlayer = new MediaPlayer(media);
        mediaPlayer.play();
    }

    private void pauseMedia() {
        if (mediaPlayer != null && mediaPlayer.getStatus() == Status.PLAYING) {
            mediaPlayer.pause();
        }
    }

    private void stopMedia() {
        if (mediaPlayer != null) {
            mediaPlayer.stop();
        }
    }

    public static void main(String[] args) {
        launch(args);
    }
}
```

