        Button searchButton = new Button("Search");
        toolbar.setSpacing(10);
        toolbar.setPadding(new Insets(10, 10, 10, 10));
        toolbar.getChildren().addAll(prevButton, nextButton, deleteButton, editButton, searchField, searchButton);

        // Create pane for images
        imagePane = new VBox();
        imagePane.setSpacing(10);
        imagePane.setPadding(new Insets(10, 10, 10, 10));
        imagePane.setAlignment(Pos.CENTER);

        // Create pane for status message
        Label statusLabel = new Label();
        statusLabel.setTextFill(Color.RED);

        // Create progress bar
        progressBar = new ProgressBar(0);
        progressBar.setVisible(false);

        // Add panes to root pane
        root.setTop(menuBar);
        root.setCenter(imagePane);
        root.setBottom(new VBox(statusLabel, progressBar));
        root.setRight(toolbar);

        // Add event handlers
        openMenuItem.setOnAction(e -> openDirectory(primaryStage));
        saveMenuItem.setOnAction(e -> saveImages());
        exitMenuItem.setOnAction(e -> System.exit(0));
        prevButton.setOnAction(e -> prevImage());
        nextButton.setOnAction(e -> nextImage());
        deleteButton.setOnAction(e -> deleteImage());
        editButton.setOnAction(e -> editImage());
        searchButton.setOnAction(e -> searchImages(searchField.getText()));

        primaryStage.setScene(scene);
        primaryStage.show();
    }

    private void openDirectory(Stage primaryStage) {
        DirectoryChooser directoryChooser = new DirectoryChooser();
        directoryChooser.setTitle("Open Directory");
        selectedDirectory = directoryChooser.showDialog(primaryStage);
        if (selectedDirectory != null) {
            imageList = new ArrayList<File>();
            File[] files = selectedDirectory.listFiles();
            for (File file : files) {
                if (file.isFile() && isImage(file)) {
                    imageList.add(file);
                }
            }
            if (imageList.size() > 0) {
                displayImage(imageList.get(0));
            }
        }
    }

    private boolean isImage(File file) {
        String name = file.getName().toLowerCase();
        return name.endsWith(".jpg") || name.endsWith(".jpeg") || name.endsWith(".png");
    }

    private void displayImage(File file) {
        currentImage = file;
        Image image = new Image(file.toURI().toString());
        ImageView imageView = new ImageView(image);
        imageView.setFitWidth(600);
        imageView.setFitHeight(400);
        imagePane.getChildren().clear();
        imagePane.getChildren().addAll(imageView, new Label(file.getName()));
        progressBar.setVisible(false);
    }

    private void prevImage() {
        if (imageList != null && imageList.size() > 1) {
            imageIndex--;
            if (imageIndex < 0) {
                imageIndex = imageList.size() - 1;
            }
            displayImage(imageList.get(imageIndex));
        }
    }

    private void nextImage() {
        if (imageList != null && imageList.size() > 1) {
            imageIndex++;
            if (imageIndex >= imageList.size()) {
                imageIndex = 0;
            }
            displayImage(imageList.get(imageIndex));
        }
    }

    private void deleteImage() {
        if (imageList != null && currentImage != null) {
            imageList.remove(currentImage);
            currentImage.delete();
            if (imageList.size() > 0) {
                nextImage();
            } else {
                imagePane.getChildren().clear();
                currentImage = null;
            }
        }
    }

    private void editImage() {
        if (currentImage != null) {
            // TODO: Implement image editor
        }
    }

    private void searchImages(String keyword) {
        if (imageList != null && keyword != null && keyword.length() > 0) {
            List<File> result = new ArrayList<File>();
            for (File image : imageList) {
                if (image.getName().toLowerCase().contains(keyword.toLowerCase())) {
                    result.add(image);
                }
            }
            if (result.size() > 0) {
                imageList = result;
                imageIndex = 0;
                displayImage(imageList.get(imageIndex));
            } else {
                imagePane.getChildren().clear();
                currentImage = null;
            }
        }
    }

    private void saveImages() {
        if (selectedDirectory != null && imageList != null && imageList.size() > 0) {
            FileChooser fileChooser = new FileChooser();
            fileChooser.setTitle("Save File");
            fileChooser.setInitialFileName("gallery.zip");
            File file = fileChooser.showSaveDialog(null);
            if (file != null) {
                progressBar.setProgress(0);
                progressBar.setVisible(true);
                ZipTask zipTask = new ZipTask(selectedDirectory, imageList, file);
                zipTask.setOnSucceeded(e -> {
                    progressBar.setVisible(false);
                    displayStatus("Images saved to " + file.getAbsolutePath());
                });
                zipTask.setOnFailed(e -> {
                    progressBar.setVisible(false);
                    displayStatus("Error saving images.");
                });
                progressBar.progressProperty().bind(zipTask.progressProperty());
                Thread th = new Thread(zipTask);
                th.setDaemon(true);
                th.start();
            }
        }
    }

    private void displayStatus(String message) {
        progressMessage(message);
        Thread messageThread = new Thread(() -> {
            try {
                Thread.sleep(3000);
                progressMessage("");
            } catch (InterruptedException e) {
                // Ignore
            }
        });
        messageThread.setDaemon(true);
        messageThread.start();
    }

    private void progressMessage(String message) {
        progressBar.setVisible(false);
        if (message != null && message.length() > 0) {
            progressBar.setVisible(true);
            progressBar.setProgress(ProgressBar.INDETERMINATE_PROGRESS);
        }
    }

    private class ZipTask extends javafx.concurrent.Task<Boolean> {
        private File sourceDirectory;
        private List<File> fileList;
        private File outputFile;

        public ZipTask(File sourceDirectory, List<File> fileList, File outputFile) {
            this.sourceDirectory = sourceDirectory;
            this.fileList = fileList;
            this.outputFile = outputFile;
        }

        @Override
        protected Boolean call() throws Exception {
            ZipUtils.zipDirectory(sourceDirectory, fileList, outputFile, this);
            return true;
        }
    }

    public static void main(String[] args) {
        launch(args);
    }
}
