const char* device_topic = "devices/arduino_1";


WiFiClient espClient;
PubSubClient client(espClient);

// Function to connect to MQTT Broker
void connectToMQTTBroker() {
  while (!client.connected()) {
    Serial.println("Connecting to MQTT broker...");
    if (client.connect(device_id, mqtt_username, mqtt_password)) {
      Serial.println("Connected to MQTT broker successfully!");

      // Subscribe to messages from other device
      client.subscribe("devices/arduino_2");
    } else {
      Serial.print("Failed to connect to MQTT broker. Retry in 5 seconds...");
      delay(5000);
    }
  }
}

void setup() {
  Serial.begin(115200);

  // Connect to Wi-Fi network
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Connecting to Wi-Fi...");
  }

  // Connect to MQTT Broker
  client.setServer(mqtt_server, mqtt_port);
  connectToMQTTBroker();
}

void loop() {
  // Handle MQTT messages
  client.loop();

  // Send message to other device
  if (client.connected()) {
    client.publish("devices/arduino_2", "Hello from arduino_1");
  }
}

// Callback function for receiving messages from other device
void callback(char* topic, byte* payload, unsigned int length) {
  Serial.println("Message received: ");
  for (int i = 0; i < length; i++) {
    Serial.print((char)payload[i]);
  }

  // Send response to other device
  if (client.connected()) {
    client.publish("devices/arduino_2", "Hello back from arduino_1");
  }
}

```

The above code uses the PubSubClient library to connect to an MQTT broker. The Arduino device subscribes to messages from the other device by subscribing to a topic, and it sends messages to the other device by publishing to another topic. The callback function is used to handle messages received from the other device and to send a response back.

In this example, the topic used includes the identifier of the device. To make this example work with Matter communication, you would only need to replace the MQTT Broker details with the Matter communicator details. Also, in the actual implementation, you would need to implement the relevant Matter application layers, including discovery, commissioning, and application data exchange.

