    private Bucket bucket;

    @Autowired
    private RedisTemplate<String, String> redisTemplate;

    @GetMapping("/api")
    public String apiEndpoint() {
        if (this.bucket.tryConsume(1)) {
            // Allow the request as the rate limit is not exceeded
            return "API response";
        } else {
            // Return an error response when rate limit is exceeded
            return "Rate limit exceeded";
        }
    }

    @PostConstruct
    public void init() {
