        // Define the rate limit rules (e.g., 10 requests per minute)
        Bandwidth limit = Bandwidth.classic(10, Refill.intervally(10, Duration.ofMinutes(1)));

        // Build the rate limiter bucket
        String rateLimitKey = "api-rate-limit";
        Bucket bucket = Bucket4j.extension(RedisBucketBuilder.class)
                .wrap(redisTemplate, rateLimitKey, limit);

        // Store the bucket in a class field for further usage
        this.bucket = bucket;

        // Initialize the bucket with the maximum number of tokens
        valueOperations.set(rateLimitKey, String.valueOf(limit.getCapacity()));
    }
}
