import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bucket4j;
import io.github.bucket4j.Refill;

import java.time.Duration;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class RateLimiter {

    private final Map<String, Bucket> buckets;

    public RateLimiter(Map<String, RateLimitConfig> rateLimitConfigs) {
        this.buckets = createBuckets(rateLimitConfigs);
    }

    private Map<String, Bucket> createBuckets(Map<String, RateLimitConfig> rateLimitConfigs) {
        Map<String, Bucket> buckets = new ConcurrentHashMap<>();

        for (Map.Entry<String, RateLimitConfig> entry : rateLimitConfigs.entrySet()) {
            String key = entry.getKey();
            RateLimitConfig config = entry.getValue();

            Refill refill = Refill.intervally(config.getLimit(), config.getDuration());
            Bandwidth limit = Bandwidth.classic(config.getLimit(), refill);
            Bucket bucket = Bucket4j.builder().addLimit(limit).build();

            buckets.put(key, bucket);
        }

        return buckets;
    }

    public boolean allowed(String apiKey, String apiPath) {
        String key = apiKey + ":" + apiPath;
        Bucket bucket = buckets.getOrDefault(key, null);

        if (bucket != null) {
            return bucket.tryConsume(1);
        }

        // Handle the case where no rate limit configuration is available for the API
        return true;
    }

}
```

