  res.send(`
    <html>
      <head>
        <title>React SSR</title>
      </head>
      <body>
        <div id="root">${html}</div>
        <script src="bundle.js"></script> <!-- Optional: If you have client-side JavaScript -->
      </body>
    </html>
  `);
});

// Start the server
