import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.BlockingBucket;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bucket4j;
import io.github.bucket4j.Refill;
import io.github.bucket4j.grid.ProxyManager;
import io.github.bucket4j.grid.RecoveryStrategy;
import io.github.bucket4j.grid.ProxyBucketBuilder;
import io.github.bucket4j.grid.jcache.JCache;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

import javax.annotation.PostConstruct;
import java.time.Duration;

@Service
public class RateLimiterService {

    private static final long LIMIT = 10; // Number of API calls allowed
    private static final long DURATION_SECONDS = 1; // Seconds

    private final ProxyManager<String> buckets;

    @Autowired
    private StringRedisTemplate redisTemplate;

    @Autowired
    private RedisConnectionFactory redisConnectionFactory;

    public RateLimiterService() {
        Bandwidth limit = Bandwidth.simple(LIMIT, Refill.intervally(LIMIT, Duration.ofSeconds(DURATION_SECONDS)));
        Bucket bucket = Bucket4j.builder()
                .addLimit(limit)
                .build();
        buckets = new ProxyBucketBuilder<String>()
                .withRedis(redisTemplate, redisConnectionFactory)
                .buildProxyManager();
        buckets.addBucketIfAbsent("api-limits", bucket);
    }

    @PostConstruct
    public void recovery() {
        JCache<String> cache = JCache.create(
                redisConnectionFactory.getConnection().getNativeConnection(),
                "bucket-cache"
        );
        buckets.setProxyFactory(cache, RecoveryStrategy.RECONSTRUCT);
    }

    public boolean allowRequest(String apiKey) {
        BlockingBucket bucket = buckets.getProxy("api-limits", apiKey);
        return bucket.tryConsume(1);
    }
}
```

