using System.Windows.Controls;
using Microsoft.Win32;
using System.Windows.Media;

namespace MusicPlayer
{
    public partial class MainWindow : Window
    {
        private MediaPlayer mediaPlayer;
        private List<string> playlist;
        private int currentSongIndex;

        public MainWindow()
        {
            InitializeComponent();
            playlist = new List<string>();
            currentSongIndex = 0;
            mediaPlayer = new MediaPlayer();
            mediaPlayer.MediaEnded += MediaPlayer_MediaEnded;
        }

        private void OpenButton_Click(object sender, RoutedEventArgs e)
        {
            var openFileDialog = new OpenFileDialog();
            openFileDialog.Filter = "MP3 files (*.mp3)|*.mp3";
            openFileDialog.Multiselect = true;

            if (openFileDialog.ShowDialog() == true)
            {
                foreach (var file in openFileDialog.FileNames)
                {
                    playlist.Add(file);
                    PlaylistListBox.Items.Add(Path.GetFileName(file));
                }
            }
        }

        private void PlaylistListBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            currentSongIndex = PlaylistListBox.SelectedIndex;
        }

        private void PlayButton_Click(object sender, RoutedEventArgs e)
        {
            if (playlist.Count == 0)
            {
                return;
            }

            if (mediaPlayer.Source == null)
            {
                mediaPlayer.Open(new System.Uri(playlist[currentSongIndex]));
            }

            mediaPlayer.Play();
        }

        private void PauseButton_Click(object sender, RoutedEventArgs e)
        {
            if (mediaPlayer.CanPause)
            {
                mediaPlayer.Pause();
            }
        }

        private void StopButton_Click(object sender, RoutedEventArgs e)
        {
            if (mediaPlayer.Source != null)
            {
                mediaPlayer.Stop();
            }
        }

        private void MediaPlayer_MediaEnded(object sender, System.EventArgs e)
        {
            currentSongIndex++;
            if (currentSongIndex < playlist.Count)
            {
                mediaPlayer.Open(new System.Uri(playlist[currentSongIndex]));
                mediaPlayer.Play();
            }
            else
            {
                currentSongIndex = 0;
                mediaPlayer.Close();
            }
        }
    }
}
