memoryPartition.process->memory = jobQueue[jobIndex].memory;
memoryPartition.process->resourceA = jobQueue[jobIndex].resourceA;
memoryPartition.process->resourceB = jobQueue[jobIndex].resourceB;
memoryPartition.process->resourceC = jobQueue[jobIndex].resourceC;

memoryPartition.size -= jobQueue[jobIndex].memory;
RESOURCE_A -= jobQueue[jobIndex].resourceA;
RESOURCE_B -= jobQueue[jobIndex].resourceB;
RESOURCE_C -= jobQueue[jobIndex].resourceC;
processCount++;
}
jobIndex++;
}

