}
}

// 释放分配的内存和资源
memoryPartition.size += jobProcesses[i].memory;
RESOURCE_A += jobProcesses[i].resourceA;
RESOURCE_B += jobProcesses[i].resourceB;
RESOURCE_C += jobProcesses[i].resourceC;

jobProcesses[i].memory = 0;
jobProcesses[i].resourceA = 0;
jobProcesses[i].resourceB = 0;
jobProcesses[i].resourceC = 0;
}
