Here's an example of a transliteration code in C# that converts English characters to their respective Russian counterparts:

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Transliteration
{
    private static readonly Dictionary<char, string> translitMap = new Dictionary<char, string>
    {
        { 'a', "а" },
        { 'b', "б" },
        { 'c', "ц" },
        { 'd', "д" },
        { 'e', "е" },
        { 'f', "ф" },
        { 'g', "г" },
        { 'h', "х" },
        { 'i', "и" },
        { 'j', "ж" },
        { 'k', "к" },
        { 'l', "л" },
        { 'm', "м" },
        { 'n', "н" },
        { 'o', "о" },
        { 'p', "п" },
        { 'q', "к" },
        { 'r', "р" },
        { 's', "с" },
        { 't', "т" },
        { 'u', "у" },
        { 'v', "в" },
        { 'w', "в" },
        { 'x', "кс" },
        { 'y', "ы" },
        { 'z', "з" },
    };

    public static string Transliterate(string text)
    {
        StringBuilder result = new StringBuilder();

        foreach (char c in text.ToLower())
        {
            if (translitMap.ContainsKey(c))
            {
                result.Append(translitMap[c]);
            }
            else
            {
                result.Append(c);
            }
        }

        return result.ToString();
    }

    public static void Main(string[] args)
    {
        string input = "Hello, World!";
        string transliterated = Transliterate(input);
        Console.WriteLine(transliterated);
    }
}
```

In this example, the `Transliterate` method takes an English string as input and returns the transliterated Russian string. The `translitMap` dictionary maps each English character to its corresponding Russian transliteration. The `Main` method demonstrates how to use the `Transliterate` method with a sample input.

