To initialize an n by n double array in C++, you can use a nested for loop. Here's an example:

```c++
#include <iostream>

int main() {
    int n = 5; // Change the value of n to adjust the size of the array

    double** array = new double*[n]; // Create an array of pointers to double

    // Allocate memory for each row of the array
    for (int i = 0; i < n; i++) {
        array[i] = new double[n];
    }

    // Initialize the array with values
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            array[i][j] = 0.0; // Change this line to set different initial values
        }
    }

    // Print the array
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cout << array[i][j] << " ";
        }
        std::cout << std::endl;
    }

    // Deallocate memory for each row of the array
    for (int i = 0; i < n; i++) {
        delete[] array[i];
    }

    // Deallocate memory for the array
    delete[] array;

    return 0;
}
```

In this example, the array is initialized with all elements set to 0.0. You can change this value or modify the initialization loop to set different initial values if needed.

