package com.deondigital.serialization

import com.google.gson.Gson
import com.google.gson.GsonBuilder
import java.io.Reader
import java.io.StringReader
import java.io.StringWriter
import java.io.Writer
import java.math.BigDecimal
import java.util.TreeMap

/**
 * Internal JSON representation
 */
sealed class JsonElement {
    companion object {
        private val internalGson = GsonBuilder().serializeNulls().disableHtmlEscaping().create()
        fun read(reader: Reader, gson: Gson = internalGson): JsonElement =
            toJsonElement(gson.newJsonReader(reader))

        fun read(s: String, gson: Gson = internalGson): JsonElement = read(StringReader(s), gson)
    }

    fun toJsonString(): String =
        StringWriter().also {
            serialize(this, it)
        }.toString()

    fun write(writer: Writer) = serialize(this, writer)

    sealed class JsonPrimitive : JsonElement() {
        data class JsonNumber(private val n: Number) : JsonPrimitive() {
            constructor(s: String) : this(BigDecimal(s))

            val asInt: Int
                get() = n.toInt()
            val asShort: Short
                get() = n.toShort()
            val asLong: Long
                get() = n.toLong()
            val asFloat: Float
                get() = n.toFloat()
            val asDouble: Double
                get() = n.toDouble()
            val asNumber: Number
                get() = n

            override fun equals(other: Any?): Boolean = when (other) {
                is JsonNumber -> when (other.n) {
                    is Int -> this.n == other.n
                    is Double -> this.n == other.n
                    is BigDecimal -> when (this.n) {
                        is BigDecimal -> this.n == other.n
                        else -> BigDecimal(this.n.toString()) == other.n
                    }
                    else -> this.n == other.n
                }
                else -> false
            }

            override fun hashCode(): Int = n.hashCode()
        }

        data class JsonBoolean(private val b: Boolean) : JsonPrimitive() {
            val asBoolean: Boolean
                get() = b
        }

        data class JsonString(private val s: String) : JsonPrimitive() {
            val asString: String
                get() = s
        }
    }

    class JsonObject : JsonElement() {
        // Use a sorted mutable map to ensure injectivity of encodings (o1 == o2 implies o1.toString() == o2.toString())
        // Ulrik 2020-03-02: Also, benchmarks show that a TreeMap is actually significantly faster
        // (around 17% in one benchmark) than a HashMap for this usage. PatriciaTrie from Apache Commons was
        // surprisingly much slower than both HashMap and TreeMap.
        private val map = TreeMap<String, JsonElement>(Comparator { s, t -> t.compareTo(s) })
        fun add(k: String, value: JsonElement) {
            map[k] = value
        }

        fun remove(k: String) {
            map.remove(k)
        }

        fun addProperty(name: String, value: String) =
            add(name, JsonPrimitive.JsonString(value))

        fun addProperty(name: String, value: Number) =
            add(name, JsonPrimitive.JsonNumber(value))

        fun has(key: String): Boolean = map.containsKey(key)

        operator fun get(key: String): JsonElement = map[key] ?: JsonNull

        fun keySet(): Collection<String> = map.keys

        fun entrySet(): Collection<Map.Entry<String, JsonElement>> = map.entries

        override fun equals(other: Any?): Boolean = this === other || (other is JsonObject && this.map == other.map)

        override fun hashCode(): Int = map.hashCode()

        fun shallowCopy(): JsonObject {
            val r = JsonObject()
            for ((k, v) in entrySet()) {
                r.add(k, v)
            }
            return r
        }
    }

    class JsonArray : JsonElement() {
        private val list = mutableListOf<JsonElement>()
        fun add(value: JsonElement) = list.add(value)

        fun <T> map(function: (JsonElement) -> T): List<T> = list.map { function(it) }
        fun <T> reverseMap(function: (JsonElement) -> T): List<T> = list.asReversed().map { function(it) }

        fun size(): Int = list.size

        operator fun get(i: Int): JsonElement = list[i]

        fun add(value: String) =
            list.add(JsonPrimitive.JsonString(value))

        fun add(value: Number) =
            list.add(JsonPrimitive.JsonNumber(value))

        override fun equals(other: Any?): Boolean =
            (this === other) || (other is JsonArray && this.list == other.list)

        override fun hashCode(): Int = list.hashCode()
    }

    object JsonNull : JsonElement()

    /* Deserialization functions */

    infix fun field(key: String): JsonElement =
        maybeField(key) ?: throw InvalidJsonField(key, this)

    infix fun maybeField(key: String): JsonElement? =
        if (this is JsonObject) {
            if (this.has(key) && this[key] !is JsonNull) this[key] else null
        } else throw InvalidJsonField(key, this)
}

/**
 * Convert a [JsonElement] to its native Kotlin counterpart.  A [JsonElement.JsonPrimitive.JsonBoolean]
 * becomes a [kotlin.Boolean], a [JsonElement.JsonObject] becomes a [Map], [JsonElement.JsonNull] becomes null etc.
 */
fun JsonElement.reflect(): Any? = when (this) {
    is JsonElement.JsonPrimitive.JsonBoolean -> asBoolean
    is JsonElement.JsonPrimitive.JsonNumber -> asNumber
    is JsonElement.JsonPrimitive.JsonString -> asString
    is JsonElement.JsonArray -> map { it.reflect() }
    is JsonElement.JsonObject -> entrySet().associate { it.key to it.value.reflect() }
    JsonElement.JsonNull -> null
}

/**
 * Create a [JsonElement.JsonObject] with the given entries. Null entries are ignored.
 */
fun obj(entries: List<Pair<String, JsonElement>?>) = obj(*entries.toTypedArray())

/** @see [obj] */
fun obj(vararg entries: Pair<String, JsonElement>?) =
    JsonElement.JsonObject().apply { entries.filterNotNull().forEach { (name, element) -> add(name, element) } }

/**
 * Create a [JsonElement.JsonArray] with the given elements.
 */
fun list(elms: List<JsonElement>) = JsonElement.JsonArray().apply { elms.forEach { add(it) } }

/**
 * Convert a [kotlin.String] to a [JsonElement.JsonPrimitive.JsonString].
 */
fun string(s: String) = JsonElement.JsonPrimitive.JsonString(s)

/**
 * Convert a [kotlin.Number] to a [JsonElement.JsonPrimitive.JsonNumber].
 */
fun number(i: Number) = JsonElement.JsonPrimitive.JsonNumber(i)

/**
 * Convert a [kotlin.Boolean] to a [JsonElement.JsonPrimitive.JsonBoolean].
 */
fun bool(b: Boolean) = JsonElement.JsonPrimitive.JsonBoolean(b)


write a kotlin function that, given a seed, generates a random JSON element

Sure! Here's a Kotlin function that generates a random JSON element based on a given seed:

```kotlin
import kotlin.random.Random

fun generateRandomJson(seed: Long): JsonElement {
    val random = Random(seed)

    fun generateJsonValue(): JsonElement {
        val randomNumber = random.nextInt(10)
        val randomBoolean = random.nextBoolean()
        val randomString = (0..5).map { ('a'..'z').random() }.joinToString("")

        return when (randomNumber) {
            in 0..5 -> JsonElement.JsonPrimitive.JsonNumber(randomNumber)
            6 -> JsonElement.JsonPrimitive.JsonBoolean(randomBoolean)
            else -> JsonElement.JsonPrimitive.JsonString(randomString)
        }
    }

    fun generateJsonObject(depth: Int): JsonElement.JsonObject {
        val jsonObject = JsonElement.JsonObject()

        if (depth > 0) {
            val keyCount = random.nextInt(1, 5)

            for (i in 1..keyCount) {
                val key = "key$i"
                val value = generateJsonValue()
                jsonObject.add(key, value)

                if (random.nextBoolean()) {
                    val nestedObject = generateJsonObject(depth - 1)
                    jsonObject.add(key + "_nested", nestedObject)
                }
            }
        }

        return jsonObject
    }

    fun generateJsonArray(depth: Int): JsonElement.JsonArray {
        val jsonArray = JsonElement.JsonArray()

        if (depth > 0) {
            val elementCount = random.nextInt(1, 5)

            for (i in 1..elementCount) {
                val value = generateJsonValue()
                jsonArray.add(value)

                if (random.nextBoolean()) {
                    val nestedArray = generateJsonArray(depth - 1)
                    jsonArray.add(nestedArray)
                }
            }
        }

        return jsonArray
    }

    return when (random.nextInt(0, 3)) {
        0 -> generateJsonValue()
        1 -> generateJsonObject(2)
        else -> generateJsonArray(2)
    }
}
```

Usage:
```kotlin
val seed = System.currentTimeMillis()
val randomJson = generateRandomJson(seed)
println(randomJson.toJsonString())
```

This function uses a random number generator with a given seed to generate random numbers, boolean values, and strings for the JSON element. It recursively generates random JSON objects and arrays up to a specified depth.

