        int circleSize = 100;
        int imageSize = circleSize * 10; // Increase image size for better roundness
        int x = imageSize / 2 - circleSize / 2;
        int y = imageSize / 2 - circleSize / 2;

        circleImage = new BufferedImage(imageSize, imageSize, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = circleImage.createGraphics();
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2d.setColor(Color.BLACK);
        g2d.fillOval(x, y, circleSize, circleSize);
        g2d.dispose();
    }

