                                                          0.2f, 0.4f, 0.2f,
                                                          0.1f, 0.2f, 0.1f });

        ConvolveOp convolveMax = new ConvolveOp(kernelMax);
        ConvolveOp convolveMin = new ConvolveOp(kernelMin);

        BufferedImage blurredCircleMax = new BufferedImage(circleImage.getWidth(), circleImage.getHeight(), circleImage.getType());
        BufferedImage blurredCircleMin = new BufferedImage(circleImage.getWidth(), circleImage.getHeight(), circleImage.getType());

        convolveMax.filter(circleImage, blurredCircleMax);
        convolveMin.filter(circleImage, blurredCircleMin);

        int x = getWidth() / 2 - circleImage.getWidth() / 2;
        int y = getHeight() / 2 - circleImage.getHeight() / 2;

        g2d.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);

        // Scale down the image for better roundness of small circles
        int scaledSize = circleImage.getWidth() / 10; // Scale factor of 10
        BufferedImage scaledCircleMax = new BufferedImage(scaledSize, scaledSize, BufferedImage.TYPE_INT_ARGB);
        BufferedImage scaledCircleMin = new BufferedImage(scaledSize, scaledSize, BufferedImage.TYPE_INT_ARGB);

        Graphics2D scaledGraphicsMax = scaledCircleMax.createGraphics();
        Graphics2D scaledGraphicsMin = scaledCircleMin.createGraphics();

        scaledGraphicsMax.drawImage(blurredCircleMax, 0, 0, scaledSize, scaledSize, null);
        scaledGraphicsMin.drawImage(blurredCircleMin, 0, 0, scaledSize, scaledSize, null);

        scaledGraphicsMax.dispose();
        scaledGraphicsMin.dispose();

        // Draw the scaled blurred circles with different levels of blur
        g2d.drawImage(scaledCircleMax, x - scaledSize - 20, y, null);
        g2d.drawImage(scaledCircleMin, x + 20, y, null);
    }

