```java
import javax.swing.*;
import java.awt.*;

public class BottomTextButton {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame frame = new JFrame("Bottom Text Button");
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
