Matrix look_at(const Vec3f& eye, const Vec3f& center, const Vec3f& up)
{
    auto forward = (eye - center).normalize();
    auto right   = cross(up, forward).normalize();
    auto view_up = cross(forward, right).normalize();

    auto mv = Matrix::identity();

    for (int i = 0; i < 3; ++i) {
        mv[0][i] = right[i];
        mv[1][i] = view_up[i];
        mv[2][i] = forward[i];
        mv[i][3] = -center[i];
    }

    return mv;
}

