```

4. Replace the contents of the `src/main.rs` file with the following code:

```rust
use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use uuid::Uuid;
use std::sync::{Arc, Mutex};

#[derive(Debug)]
struct Testimonial {
    id: Uuid,
    name: String,
    message: String,
}

#[derive(Debug)]
struct AppState {
    testimonials: Arc<Mutex<Vec<Testimonial>>>,
}

async fn get_testimonials(data: web::Data<AppState>) -> impl Responder {
    let testimonials = data.testimonials.lock().unwrap();
    HttpResponse::Ok().json(&*testimonials)
}

async fn add_testimonial(payload: web::Json<Testimonial>, data: web::Data<AppState>) -> impl Responder {
    let testimonial = payload.into_inner();

    let mut testimonials = data.testimonials.lock().unwrap();
    testimonials.push(testimonial);

    HttpResponse::Created().json(testimonial)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let testimonials = Arc::new(Mutex::new(vec![
        Testimonial {
            id: Uuid::new_v4(),
            name: "John Doe".to_owned(),
            message: "Great service!".to_owned(),
        },
        Testimonial {
            id: Uuid::new_v4(),
            name: "Jane Smith".to_owned(),
            message: "Excellent experience!".to_owned(),
        },
    ]));

    HttpServer::new(move || {
        App::new()
            .data(AppState {
                testimonials: Arc::clone(&testimonials),
            })
            .route("/testimonials", web::get().to(get_testimonials))
            .route("/testimonials", web::post().to(add_testimonial))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
```

5. Save the changes, navigate to the project's root directory in your terminal, and run the following command to start the server:

```sh
$ cargo run
```

The server will run at `http://127.0.0.1:8080`.

