public class KMeansClustering {
    private List<DataPoint> dataPoints;
    private List<Cluster> clusters;
    private int k;
    private double threshold;
    private int maxIterations;

    public KMeansClustering(int k, double threshold, int maxIterations) {
        this.k = k;
        this.threshold = threshold;
        this.maxIterations = maxIterations;
        dataPoints = new ArrayList<>();
        clusters = new ArrayList<>();
    }

    public void readDataPoints() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter data points in format (x,y), separated by commas. Enter 'done' when finished.");

        while (true) {
            String input = scanner.nextLine().trim();
            if (input.equalsIgnoreCase("done")) {
                break;
            }

            String[] coordinates = input.split(",");
            if (coordinates.length != 2) {
                System.out.println("Invalid input! Coordinates should be in the format (x,y). Try again.");
                continue;
            }

            try {
                double x = Double.parseDouble(coordinates[0]);
                double y = Double.parseDouble(coordinates[1]);
                dataPoints.add(new DataPoint(x, y));
            } catch (NumberFormatException e) {
                System.out.println("Invalid input! Coordinates should be numeric. Try again.");
            }
        }
    }

    public void initializeClusters() {
        for (int i = 0; i < k; i++) {
            Cluster cluster = new Cluster();
            cluster.setCentroid(dataPoints.get(i % dataPoints.size()));
            clusters.add(cluster);
        }
    }

    public void performClustering() {
        int iteration = 0;

        while (iteration < maxIterations) {
            for (Cluster cluster : clusters) {
                cluster.clearMembers();
            }

            for (DataPoint point : dataPoints) {
                double minDistance = Double.MAX_VALUE;
                Cluster closestCluster = null;

                for (Cluster cluster : clusters) {
                    double distance = calculateEuclideanDistance(point, cluster.getCentroid());
                    if (distance < minDistance) {
                        minDistance = distance;
                        closestCluster = cluster;
                    }
                }

                closestCluster.addMember(point);
            }

            boolean converged = true;
            for (Cluster cluster : clusters) {
                double sumX = 0;
                double sumY = 0;
                List<DataPoint> members = cluster.getMembers();
                int size = members.size();

                for (DataPoint member : members) {
                    sumX += member.getX();
                    sumY += member.getY();
                }

                double newCentroidX = sumX / size;
                double newCentroidY = sumY / size;

                if (Math.abs(newCentroidX - cluster.getCentroid().getX()) > threshold ||
                        Math.abs(newCentroidY - cluster.getCentroid().getY()) > threshold) {
                    cluster.setCentroid(new DataPoint(newCentroidX, newCentroidY));
                    converged = false;
                }
            }

            if (converged) {
                break;
            }

            iteration++;
        }
    }

    public double calculateEuclideanDistance(DataPoint point1, DataPoint point2) {
        double xDiff = point1.getX() - point2.getX();
        double yDiff = point1.getY() - point2.getY();
        return Math.sqrt(xDiff * xDiff + yDiff * yDiff);
    }

