fn merge_sort(arr: &mut [i32]) {
    if arr.len() <= 1 {
        return;
    }

    let mid = arr.len() / 2;

    let mut left_half = &mut arr[..mid];
    let mut right_half = &mut arr[mid..];

    merge_sort(&mut left_half);
    merge_sort(&mut right_half);

    merge(&mut left_half, &mut right_half, arr);
}


fn merge(left: &mut [i32], right: &mut [i32], arr: &mut [i32]) {
    let mut left_index = 0;
    let mut right_index = 0;
    let mut arr_index = 0;

    while left_index < left.len() && right_index < right.len() {
        if left[left_index] <= right[right_index] {
            arr[arr_index] = left[left_index];
            left_index += 1;
        } else {
            arr[arr_index] = right[right_index];
            right_index += 1;
        }
        arr_index += 1;
    }

    while left_index < left.len() {
        arr[arr_index] = left[left_index];
        left_index += 1;
        arr_index += 1;
    }

    while right_index < right.len() {
        arr[arr_index] = right[right_index];
        right_index += 1;
        arr_index += 1;
    }
}


fn main() {
    let mut arr = [4, 2, 1, 6, 8, 5, 3, 7];

    merge_sort(&mut arr);

    println!("{:?}", arr);
}
