    private List<Point> points;  // List to store data points
    private List<Cluster> clusters;  // List to store clusters

    private static class Point {
        private double x;
        private double y;

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        public double getX() {
            return x;
        }

        public double getY() {
            return y;
        }
    }

    private static class Cluster {
        private Point centroid;
        private List<Point> points;

        public Cluster(Point centroid) {
            this.centroid = centroid;
            this.points = new ArrayList<>();
        }

        public Point getCentroid() {
            return centroid;
        }

        public List<Point> getPoints() {
            return points;
        }

        public void addPoint(Point point) {
            points.add(point);
        }

        public void clearPoints() {
            points.clear();
        }
    }

    public KMeansClustering() {
        points = new ArrayList<>();
        clusters = new ArrayList<>();
    }

    public void readDataFromFile(String filename) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader(filename));
        String line;

        while ((line = reader.readLine()) != null) {
            String[] parts = line.substring(1, line.length() - 1).split(",");
            double x = Double.parseDouble(parts[0]);
            double y = Double.parseDouble(parts[1]);

            Point point = new Point(x, y);
            points.add(point);
        }

        reader.close();
    }

    public void runAlgorithm() {
        // Initialize clusters with random centroids
        Random random = new Random();
        for (int i = 0; i < K; i++) {
            int index = random.nextInt(points.size());
            Point centroid = points.get(index);
            Cluster cluster = new Cluster(centroid);
            clusters.add(cluster);
        }

        for (int iteration = 0; iteration < 10; iteration++) {  // Maximum number of iterations
            // Assign points to the nearest cluster
            for (Cluster cluster : clusters) {
                cluster.clearPoints();
            }

            for (Point point : points) {
                Cluster nearestCluster = null;
                double minDistance = Double.MAX_VALUE;
                for (Cluster cluster : clusters) {
                    double distance = calculateEuclideanDistance(point, cluster.getCentroid());
                    if (distance < minDistance) {
                        minDistance = distance;
                        nearestCluster = cluster;
                    }
                }
                nearestCluster.addPoint(point);
            }

            // Update cluster centroids
            for (Cluster cluster : clusters) {
                double sumX = 0;
                double sumY = 0;
                List<Point> points = cluster.getPoints();
                for (Point point : points) {
                    sumX += point.getX();
                    sumY += point.getY();
                }
                double updatedX = sumX / points.size();
                double updatedY = sumY / points.size();
                cluster.getCentroid().x = updatedX;
                cluster.getCentroid().y = updatedY;
            }
        }
    }

    public void printResult() {
        for (int i = 0; i < K; i++) {
            Cluster cluster = clusters.get(i);
            System.out.println("Cluster " + (i + 1) + ":");
            System.out.println("Centroid: (" + cluster.getCentroid().getX() + ", " + cluster.getCentroid().getY() + ")");
            System.out.println("Points:");
            for (Point point : cluster.getPoints()) {
                System.out.println("(" + point.getX() + ", " + point.getY() + ")");
            }
            System.out.println();
        }
    }

    private double calculateEuclideanDistance(Point point1, Point point2) {
        double deltaX = point2.getX() - point1.getX();
        double deltaY = point2.getY() - point1.getY();
        return Math.sqrt(deltaX * deltaX + deltaY * deltaY);
    }

    public static void main(String[] args) {
        KMeansClustering kMeans = new KMeansClustering();
        try {
            kMeans.readDataFromFile("data.txt");
            kMeans.runAlgorithm();
            kMeans.printResult();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
