Here is an example Java code that implements K-means clustering for 2 columns of data read from a file:

```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class KMeansClustering {

    public static void main(String[] args) {
        int k = 2; // number of clusters

        // Read data from file
        List<Point> points = readDataFromFile("data.txt");

        // Initialize centroids
        List<Point> centroids = initializeRandomCentroids(points, k);

        // Run K-means clustering
        List<Point>[] clusters = kMeansClustering(points, centroids);

        // Print the clusters
        for (int i = 0; i < k; i++) {
            System.out.println("Cluster " + (i + 1) + ":");
            for (Point point : clusters[i]) {
                System.out.println(point.getX() + "," + point.getY());
            }
            System.out.println();
        }
    }

    // Read data from file into a list of Points
    public static List<Point> readDataFromFile(String fileName) {
        List<Point> points = new ArrayList<>();

        try (BufferedReader br = new BufferedReader(new FileReader(fileName))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] coordinates = line.split(",");
                double x = Double.parseDouble(coordinates[0]);
                double y = Double.parseDouble(coordinates[1]);
                Point point = new Point(x, y);
                points.add(point);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        return points;
    }

    // Initialize random centroids from the given points
    public static List<Point> initializeRandomCentroids(List<Point> points, int k) {
        List<Point> centroids = new ArrayList<>();
        int n = points.size();

        for (int i = 0; i < k; i++) {
            int randomIndex = (int) (Math.random() * n);
            Point centroid = new Point(points.get(randomIndex).getX(), points.get(randomIndex).getY());
            centroids.add(centroid);
        }

        return centroids;
    }

    // Perform K-means clustering
    public static List<Point>[] kMeansClustering(List<Point> points, List<Point> centroids) {
        int k = centroids.size();
        List<Point>[] clusters = new ArrayList[k];

        for (int i = 0; i < k; i++) {
            clusters[i] = new ArrayList<>();
        }

        boolean convergence = false;

        while (!convergence) {
            convergence = true;

            // Assign each point to the nearest centroid
            for (Point point : points) {
                int nearestCentroidIndex = 0;
                double nearestDistance = Double.MAX_VALUE;

                for (int i = 0; i < k; i++) {
                    double distance = calculateDistance(point, centroids.get(i));
                    if (distance < nearestDistance) {
                        nearestDistance = distance;
                        nearestCentroidIndex = i;
                    }
                }

                clusters[nearestCentroidIndex].add(point);
            }

            // Update centroids
            for (int i = 0; i < k; i++) {
                double sumX = 0.0;
                double sumY = 0.0;
                int clusterSize = clusters[i].size();

                for (Point point : clusters[i]) {
                    sumX += point.getX();
                    sumY += point.getY();
                }

                double newCentroidX = sumX / clusterSize;
                double newCentroidY = sumY / clusterSize;
                Point newCentroid = new Point(newCentroidX, newCentroidY);

                if (!newCentroid.equals(centroids.get(i))) {
                    centroids.set(i, newCentroid);
                    convergence = false;
                }
            }

            // Clear clusters
            for (int i = 0; i < k; i++) {
                clusters[i].clear();
            }
        }

        return clusters;
    }

    // Calculate Euclidean distance between two points
    public static double calculateDistance(Point p1, Point p2) {
        double xDiff = p1.getX() - p2.getX();
        double yDiff = p1.getY() - p2.getY();
        return Math.sqrt(xDiff * xDiff + yDiff * yDiff);
    }
}

class Point {
    private double x;
    private double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }
}
```

