    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    // Prepare the SQL statement with a named or positional parameter
    $stmt = $pdo->prepare("INSERT INTO your_table (column1, column2) VALUES (:param1, :param2)");

