const fs = require('fs');
const axios = require('axios');
const { JSDOM } = require('jsdom');

const MAX_DEPTH = 3; // Maximum depth to crawl
const MAX_VISITED = 1000; // Maximum number of URLs to visit
const SEED_URL = 'https://example.com'; // Starting URL

const visited = new Set([SEED_URL]);
const queue = [{ url: SEED_URL, depth: 1 }];

function saveURL(url) {
  fs.appendFileSync('urls.txt', url + '\n');
}

async function crawl() {
  while (queue.length > 0 && visited.size < MAX_VISITED) {
    const { url, depth } = queue.shift();

    try {
      const response = await axios.get(url);
      const dom = new JSDOM(response.data);

      saveURL(url);

      if (depth < MAX_DEPTH) {
        const links = dom.window.document.querySelectorAll('a');
        links.forEach((link) => {
          const href = link.href;
          if (!visited.has(href)) {
            visited.add(href);
            queue.push({ url: href, depth: depth + 1 });
          }
        });
      }
    } catch (error) {
      console.error(`Error crawling ${url}: ${error.message}`);
    }
  }
}

crawl()
  .then(() => {
    console.log('Crawling complete.');
  })
  .catch((error) => {
    console.error('Error:', error);
  });
