function textify() {
    var inputText = document.getElementById("inputText").value; // Get the input text
    var outputText = scrambleText(inputText); // Scramble the text
    document.getElementById("outputText").value = outputText; // Set the output text
}

function scrambleText(text) {
    var words = text.split(" "); // Split the text into individual words
    var scrambledWords = [];

    for (var i = 0; i < words.length; i++) {
        var word = words[i];
        var letters = word.split(""); // Split each word into individual letters

        for (var j = letters.length - 1; j > 0; j--) {
            var randomIndex = Math.floor(Math.random() * (j + 1)); // Get a random index
            var temp = letters[j];
            letters[j] = letters[randomIndex];
            letters[randomIndex] = temp; // Swap positions of letters
        }

        var scrambledWord = letters.join(""); // Join the letters back into a word
        scrambledWords.push(scrambledWord);
    }

    return scrambledWords.join(" "); // Join the scrambled words with spaces
}
