   ```java
   public class MainActivity extends AppCompatActivity {

       private ImageButton previousButton;

       @Override
       protected void onCreate(Bundle savedInstanceState) {
           super.onCreate(savedInstanceState);
           setContentView(R.layout.activity_main);
       }

       public void onCardClick(View view) {
           ImageButton card = (ImageButton) view;
           Drawable cardImage = card.getDrawable();

           // Check if the card is already open
           if (cardImage.getConstantState().equals(getResources().getDrawable(R.drawable.call_back_photo_image).getConstantState())) {
               // Show the actual image for the card
               card.setImageResource(R.drawable.your_image);

               // Check if this is the first card flipped
               if (previousButton == null) {
                   previousButton = card;
               } else {
                   // Check if the pair matches
                   if (card.getDrawable().getConstantState().equals(previousButton.getDrawable().getConstantState())) {
                       // Match found, keep the cards open
                       previousButton.setEnabled(false);
                       card.setEnabled(false);
                   } else {
                       // No match, flip the cards back
                       Handler handler = new Handler();
                       handler.postDelayed(new Runnable() {
                           @Override
