   public class MainActivity extends AppCompatActivity {

       private ImageButton previousButton;

       @Override
       protected void onCreate(Bundle savedInstanceState) {
           super.onCreate(savedInstanceState);
           setContentView(R.layout.activity_main);
       }

       public void onCardClick(View view) {
           ImageButton card = (ImageButton) view;

           // Get the card's tag (photo index)
           int tag = (int) card.getTag();

           // Get the actual image resource for the card
           int imageResource = getImageResource(tag);

           // Set the clicked card's image
           card.setImageResource(imageResource);

           // Check if this is the first card flipped
           if (previousButton == null) {
               previousButton = card;
           } else {
               // Disable the grid layout clicks while processing
               GridLayout gridLayout = findViewById(R.id.gridLayout);
               gridLayout.setEnabled(false);

               // Get the tag of the previous card
               int previousTag = (int) previousButton.getTag();

               // Get the actual image resource for the previous card
               int previousImageResource = getImageResource(previousTag);

               // Check if the pair matches
               if (imageResource == previousImageResource) {
                   // Match found, keep the cards open
                   card.setEnabled(false);
                   previousButton.setEnabled(false);
                   checkGameCompletion();
               } else {
                   // No match, flip the cards back after a delay
                   new Handler().postDelayed(new Runnable() {
                       @Override
                       public void run() {
                           card.setImageResource(R.drawable.call_back_photo);
                           previousButton.setImageResource(R.drawable.call_back_photo);
                           card.setEnabled(true);
                           previousButton.setEnabled(true);
                           previousButton = null;
                           gridLayout.setEnabled(true);
                       }
                   }, 500);
               }
           }
       }

       private int getImageResource(int tag) {
           int[] images = {
               R.drawable.image1,
               R.drawable.image2,
               R.drawable.image3,
               R.drawable.image4,
               // Repeat the image resources for each pair
           };
           return images[tag % 4];  // Change "4" to the number of pairs
       }

       private void checkGameCompletion() {
           // Check if all pairs have been matched
           GridLayout gridLayout = findViewById(R.id.gridLayout);
           for (int i = 0; i < gridLayout.getChildCount(); i++) {
               ImageButton card = (ImageButton) gridLayout.getChildAt(i);
               if (card.isEnabled()) {
                   return;  // Game is not yet complete
               }
           }
           // Game is complete
           Toast.makeText(this, "Congratulations! You have completed the game!", Toast.LENGTH_SHORT).show();
       }
   }
   ```

