To send multicast data using IGMP in C without using UDP, you'll need to use raw sockets. Raw sockets allow you to create and send packets at the IP layer, giving you more control over the protocol used.

Here's an example of how to send multicast data using IGMP with raw sockets in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/ip_icmp.h>
#include <netinet/igmp.h>

#define MULTICAST_ADDRESS "239.1.2.3"
#define MULTICAST_IFACE "eth0"

int main() {
    struct sockaddr_in group_addr;
    struct ip_mreq mreq;
    int sock;

    // Create a socket
    sock = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
    if (sock < 0) {
        perror("Socket creation failed");
        exit(1);
    }

    // Set socket options to allow sending raw IP packets
    int enable = 1;
    if (setsockopt(sock, IPPROTO_IP, IP_HDRINCL, &enable, sizeof(enable)) < 0) {
        perror("Socket options set failed");
        exit(1);
    }

    // Set up IGMP group address and interface
    group_addr.sin_family = AF_INET;
    group_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDRESS);
    group_addr.sin_port = htons(0);  // 0 means any port

    // Bind the socket to the multicast group address and interface
    if (bind(sock, (struct sockaddr*) &group_addr, sizeof(group_addr)) < 0) {
        perror("Bind failed");
        exit(1);
    }

    // Set up the IGMP request
    mreq.imr_multiaddr.s_addr = inet_addr(MULTICAST_ADDRESS);
    mreq.imr_interface.s_addr = inet_addr(MULTICAST_IFACE);

    // Join the IGMP group
    if (setsockopt(sock, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("Join group failed");
        exit(1);
    }

    // Prepare the message to send
    char message[] = "Hello, multicast!";
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDRESS);
    dest_addr.sin_port = htons(0);  // 0 means any port

    // Send the message
    int bytes_sent = sendto(sock, message, strlen(message), 0, (struct sockaddr*) &dest_addr, sizeof(dest_addr));
    if (bytes_sent < 0) {
        perror("Sending message failed");
        exit(1);
    }

    printf("Message sent: %s\n", message);

    // Leave the IGMP group
    if (setsockopt(sock, IPPROTO_IP, IP_DROP_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("Leave group failed");
        exit(1);
    }

    // Close the socket
    close(sock);

    return 0;
}
```

Make sure to replace `"239.1.2.3"` with the desired multicast address and `"eth0"` with the network interface you want to use for multicasting.

This code creates a raw socket, sets the socket options to allow sending raw IP packets, binds it to the multicast address and interface, joins the IGMP group, prepares a message to send, and finally sends the message using `sendto()`. After sending the message, it leaves the IGMP group and closes the socket.

Note that raw socket operations require root privileges, so you may need to run this code with `sudo` or as a privileged user.

