{
    // Free the sent pbuf
    pbuf_free(p);
}

int main()
{
    struct udp_pcb *udp_pcb;
    err_t err;

    // Create a new UDP PCB (Protocol Control Block)
    udp_pcb = udp_new();
    if (udp_pcb == NULL) {
        printf("UDP PCB creation failed.\n");
        return 1;
    }

    // Bind the PCB to a specific port (optional)
    err = udp_bind(udp_pcb, IP_ADDR_ANY, MULTICAST_PORT);
    if (err != ERR_OK) {
        printf("UDP bind failed.\n");
        return 1;
    }

    // Set the multicast TTL (Time to Live)
    udp_set_multicast_ttl(udp_pcb, 255);

    // Join the multicast group
    ip_addr_t multicast_ip;
    IP4_ADDR(&multicast_ip, 239, 1, 2, 3); // Set multicast group IP
    err = igmp_joingroup(IP_ADDR_ANY, &multicast_ip);
    if (err != ERR_OK) {
        printf("IGMP join group failed.\n");
        return 1;
    }

    // Set the remote UDP endpoint (multicast group IP and port)
    ip_addr_t remote_ip;
    IP4_ADDR(&remote_ip, 239, 1, 2, 3); // Set multicast group IP
    struct udp_pcb *remote_pcb = udp_new_ip_type(IPADDR_TYPE_ANY);
    udp_connect(remote_pcb, &remote_ip, MULTICAST_PORT);

    // Allocate a pbuf (packet buffer) to hold the data to be sent
    struct pbuf *p = pbuf_alloc(PBUF_TRANSPORT, sizeof("Hello, multicast!"), PBUF_RAM);
    if (!p) {
        printf("pbuf allocation failed.\n");
        return 1;
    }
    memcpy(p->payload, "Hello, multicast!", sizeof("Hello, multicast!"));

    // Set the send callback function
    udp_send(udp_pcb, p);

    // Set the send callback function
    udp_sendto(udp_pcb, p, &remote_ip, MULTICAST_PORT, udp_send_callback, NULL);

    // Wait for the packet to be sent (optional)
    sys_msleep(1000);

    // Free the allocated pbuf
    pbuf_free(p);

    // Leave the multicast group
    err = igmp_leavegroup(IP_ADDR_ANY, &multicast_ip);
    if (err != ERR_OK) {
        printf("IGMP leave group failed.\n");
        return 1;
    }

    // Cleanup the UDP PCBs
    udp_remove(udp_pcb);
    udp_remove(remote_pcb);

    return 0;
}
```

