import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bucket4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class RateLimiterService {

    private final Map<String, Bucket> rateLimitBuckets = new ConcurrentHashMap<>();

    private final StringRedisTemplate redisTemplate;

    @Autowired
    public RateLimiterService(StringRedisTemplate redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    public synchronized void initializeRateLimit(String apiName, int limit) {
        Configuration configuration = Bucket4j.configurationBuilder()
                .addLimit(Bandwidth.simple(limit, Duration.ofMinutes(1)))
                .build();

        Bucket rateLimitBucket = Bucket4j.builder()
                .addConfiguration(configuration)
                .build();

        rateLimitBuckets.put(apiName, rateLimitBucket);
    }

    public boolean isRequestAllowed(String apiName) {
        Bucket rateLimitBucket = rateLimitBuckets.get(apiName);
        return rateLimitBucket.tryConsume(1);
    }

    public void updateRateLimitInRedis(String apiName, int limit) {
        redisTemplate.opsForValue().set(apiName, String.valueOf(limit));
    }

    public int getRateLimitFromRedis(String apiName) {
        String limit = redisTemplate.opsForValue().get(apiName);
        return Integer.parseInt(limit != null ? limit : "0");
    }
}
