import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.servlet.HandlerInterceptor;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class RateLimitingInterceptor implements HandlerInterceptor {

    private final RateLimiterService rateLimiterService;

    @Autowired
    public RateLimitingInterceptor(RateLimiterService rateLimiterService) {
        this.rateLimiterService = rateLimiterService;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {
        String apiName = request.getRequestURI(); // Use a unique identifier for each API

        if (rateLimiterService.isRequestAllowed(apiName)) {
            return true; // Request is within the rate limit
        }

        response.setStatus(429); // Return 429 Too Many Requests
        return false; // Request exceeded the rate limit
    }
}
```

