To ensure that the player character doesn't move beyond the bounds of the map, you can implement some boundary checks as they move around. Here's an example of how you can achieve this:

```java
import java.awt.*;
import java.awt.event.*;

public class MapGame extends Frame {
    private int mapWidth = 2048;
    private int mapHeight = 2048;
    private int frameWidth = 600;
    private int frameHeight = 600;
    private int playerX = 50;
    private int playerY = 50;

    public MapGame() {
        super("Map Game");
        setSize(frameWidth, frameHeight);
        setVisible(true);

        addWindowListener(new WindowAdapter() {
            public void windowClosing(WindowEvent we) {
                dispose();
            }
        });

        addKeyListener(new KeyAdapter() {
            public void keyPressed(KeyEvent ke) {
                handleKeyPress(ke);
            }
        });

        setFocusable(true);
    }

    public void handleKeyPress(KeyEvent ke) {
        int keyCode = ke.getKeyCode();

        switch (keyCode) {
            case KeyEvent.VK_UP:
                if (playerY - 10 >= 0) {
                    playerY -= 10;
                }
                break;
            case KeyEvent.VK_DOWN:
                if (playerY + 10 <= mapHeight - 1) {
                    playerY += 10;
                }
                break;
            case KeyEvent.VK_LEFT:
                if (playerX - 10 >= 0) {
                    playerX -= 10;
                }
                break;
            case KeyEvent.VK_RIGHT:
                if (playerX + 10 <= mapWidth - 1) {
                    playerX += 10;
                }
                break;
        }

        repaint();
