import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.stereotype.Service;

import java.util.concurrent.TimeUnit;

@Service
public class RateLimitService {

  private static final String RATE_LIMIT_KEY = "api_rate_limit"; // Redis key to store rate limit count

  @Autowired
  private RedisTemplate<String, Object> redisTemplate;

  public boolean checkRateLimit(String ipAddress) {
    String key = RATE_LIMIT_KEY + ipAddress;

    // Get the current count from Redis or initialize it to 0
    Long count = redisTemplate.opsForValue().increment(key, 1);
    if (count == 1) {
      // Set expiration time to 1 minute
      redisTemplate.expire(key, 1, TimeUnit.MINUTES);
