    private int[,] wave;
    private List<int[]> wavePossibilities;

    public Nullable<int>[,] CollapseWaveFunction(int[,] inputWave, int outputSize)
    {
        int inputSize = inputWave.GetLength(0);
        int maxOutputValue = inputWave.GetLength(1);

        if (outputSize < 1 || outputSize > inputSize)
        {
            throw new ArgumentException("Output size must be between 1 and input size.");
        }

        wave = new int[outputSize, outputSize];
        wavePossibilities = new List<int[]>();

        for (int i = 0; i < outputSize; i++)
        {
            for (int j = 0; j < outputSize; j++)
            {
                wave[i, j] = -1;
            }
        }

        Random random = new Random();
        int startX = random.Next(0, inputSize - outputSize + 1);
        int startY = random.Next(0, inputSize - outputSize + 1);

        for (int i = 0; i < outputSize; i++)
        {
            for (int j = 0; j < outputSize; j++)
            {
                List<int> possibleValues = new List<int>();

                for (int k = 0; k < maxOutputValue; k++)
                {
                    if (inputWave[startX + i, startY + j] == k)
                    {
                        possibleValues.Add(k);
                    }
                }

                if (possibleValues.Count == 0)
                {
                    throw new InvalidOperationException("No possible values for the given input.");
                }

                int randomIndex = random.Next(0, possibleValues.Count);
                int selectedValue = possibleValues[randomIndex];
                wave[i, j] = selectedValue;
                wavePossibilities.Add(new int[] { i, j, selectedValue });
            }
        }

        while (wavePossibilities.Count > 0)
        {
            int randomPossibilityIndex = random.Next(0, wavePossibilities.Count);
            int[] possibility = wavePossibilities[randomPossibilityIndex];
            wavePossibilities.RemoveAt(randomPossibilityIndex);

            if (!CheckValid(possibility[0], possibility[1], possibility[2], inputWave))
            {
                continue;
            }

            wave[possibility[0], possibility[1]] = possibility[2];

            for (int x = 0; x < outputSize; x++)
            {
                for (int y = 0; y < outputSize; y++)
                {
                    if (wave[x, y] == -1)
                    {
                        List<int> newPossibilities = new List<int>();

                        for (int k = 0; k < maxOutputValue; k++)
                        {
                            if (PossibilityAllowed(x, y, k, inputWave))
                            {
                                newPossibilities.Add(k);
                            }
                        }

                        if (newPossibilities.Count == 0)
                        {
                            throw new InvalidOperationException("No possible values for the given input.");
                        }

                        foreach (int newPossibility in newPossibilities)
                        {
                            wavePossibilities.Add(new int[] { x, y, newPossibility });
                        }
                    }
                }
            }
        }

        Nullable<int>[,] outputWave = new Nullable<int>[outputSize, outputSize];

        for (int x = 0; x < outputSize; x++)
        {
            for (int y = 0; y < outputSize; y++)
            {
                outputWave[x, y] = wave[x, y];
            }
        }

        return outputWave;
    }

    private bool CheckValid(int x, int y, int value, int[,] inputWave)
    {
        int outputSize = wave.GetLength(0);
        int inputSize = inputWave.GetLength(0);

        if (x > 0)
        {
            int leftNeighbor = wave[x - 1, y];

            if (leftNeighbor != -1 && inputWave[x - 1, y] != value)
            {
                return false;
            }
        }

        if (y > 0)
        {
            int topNeighbor = wave[x, y - 1];

            if (topNeighbor != -1 && inputWave[x, y - 1] != value)
            {
                return false;
            }
        }

        if (x < outputSize - 1)
