```c++
#include <iostream>

void outerFunction() {
    void innerFunction(); // Declaration of innerFunction

    std::cout << "Inside outerFunction" << std::endl;

    // Call the innerFunction
    innerFunction();

    // Definition of innerFunction
    void innerFunction() {
        std::cout << "Inside innerFunction" << std::endl;
    }
}

