        if (rc != SQLITE_OK) {
            std::cout << "Query execution failed: " << errorMsg << std::endl;
            sqlite3_free(errorMsg);
        }
    }
};

int main() {
    Database db("example.db");

    // Execute SQL query
    db.executeQuery("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)");
    db.executeQuery("INSERT INTO users (name) VALUES ('John')");

    return 0;
}
