public List<Map<String, Object>> findAll(String tableName, Map<String, Object> filters) {
    String filter = generateFilterClause(filters);
    List<Object> filterValues = filters.values().stream().collect(Collectors.toList());
    return executeQuery(tableName, filter, filterValues);
