Here's an example of a function in Kotlin that generates a random string including both ASCII and valid Unicode characters using an instance of Random:

```kotlin
import java.util.*

fun generateRandomString(random: Random, length: Int): String {
    val validUnicodeRanges = listOf(
        0x0020..0x007E, // ASCII printable characters
        0x00A1..0x00FF, // Latin-1 Supplement
        0x0400..0x04FF, // Cyrillic
        0x4E00..0x9FBF, // CJK Unified Ideographs
    )

    val result = StringBuilder(length)
    val currentIndexes = IntArray(validUnicodeRanges.size) { random.nextInt(validUnicodeRanges[it].last - validUnicodeRanges[it].first) }

    for (i in 0 until length) {
        val rangeIndex = random.nextInt(validUnicodeRanges.size)
        val currentIndex = currentIndexes[rangeIndex]

        val currentChar = (validUnicodeRanges[rangeIndex].first + currentIndex).toInt().toChar()
        result.append(currentChar)

        currentIndexes[rangeIndex] = (currentIndex + 1) % (validUnicodeRanges[rangeIndex].last - validUnicodeRanges[rangeIndex].first)
    }

    return result.toString()
}

fun main() {
    val random = Random()
    val generatedString = generateRandomString(random, 20)
    println(generatedString)
}
```

