    public void paint(Graphics g) {
        super.paint(g);

        Graphics2D g2d = (Graphics2D) g;
        g2d.setStroke(new BasicStroke(2));

        drawScoreSheet(g2d, OCTAVE_3_OFFSET);
        drawScoreSheet(g2d, OCTAVE_5_OFFSET);

        for (int i = 0; i < track.size(); i++) {
            MidiEvent event = track.get(i);
            MidiMessage message = event.getMessage();

            if (message instanceof ShortMessage) {
                ShortMessage shortMessage = (ShortMessage) message;

                if (shortMessage.getCommand() == ShortMessage.NOTE_ON) {
                    int octaveOffset = (shortMessage.getData1() > 60) ? OCTAVE_5_OFFSET : OCTAVE_3_OFFSET;
                    int lineIndex = (shortMessage.getData1() % 12) / 2; // Assuming equal temperament scale

                    int x = (i + 1) * BAR_SPACING;
                    int y = octaveOffset - (lineIndex * LINE_SPACING);

                    drawNote(g2d, x, y);
                }
            }
        }
    }

